  function renderAccessManagement(parent, sb, currentUser) {
    var section = createCollapsibleSection(
      "\uD83D\uDD10 Tilgangsniv\u00E5er",
      "Fullkontroll-brukere kan velge niv\u00E5 for Kristian, Sindre og Nikolai.",
      true
    );

    var explanation = el(
      "div",
      "Lesetilgang kan se og s\u00F8ke. Enkelte funksjoner kan i tillegg arbeide med oppgaver, tilbud og varetelling, men kan ikke oppdatere Quickbutik. Full kontroll gir alle handlinger og tilgang til endringsloggen."
    );
    explanation.className = "sk-note";
    explanation.style.marginBottom = "12px";
    section.body.appendChild(explanation);

    var host = el("div");
    section.body.appendChild(host);
    parent.appendChild(section.wrap);

    var manageable = {
      "kristian@golfkongen.no": true,
      "sindre@golfkongen.no": true,
      "nikolai@golfkongen.no": true
    };

    function loadUsers() {
      clear(host);
      var loading = el("div", "Henter brukere og tilgangsniv\u00E5er\u2026");
      loading.className = "sk-note";
      host.appendChild(loading);

      sb.rpc("internal_list_admin_users").then(function (result) {
        clear(host);

        if (result.error) {
          var error = el("div", "Kunne ikke hente brukere: " + result.error.message);
          error.className = "sk-warning";
          host.appendChild(error);
          return;
        }

        var rows = result.data || [];
        var wrap = el("div");
        wrap.style.overflowX = "auto";
        wrap.style.border = "1px solid #e5e7eb";
        wrap.style.borderRadius = "12px";

        var table = el("table");
        table.style.width = "100%";
        table.style.borderCollapse = "collapse";
        table.style.fontSize = "13px";

        var head = el("tr");
        ["Bruker", "Innlogging", "Sist inne", "Tilgangsniv\u00E5", "Handling"].forEach(function (label) {
          var th = el("th", label);
          th.style.padding = "10px";
          th.style.textAlign = "left";
          th.style.background = "#f8fafc";
          th.style.borderBottom = "1px solid #e5e7eb";
          head.appendChild(th);
        });

        var thead = el("thead");
        thead.appendChild(head);
        table.appendChild(thead);

        var tbody = el("tbody");

        rows.forEach(function (adminUser) {
          var tr = el("tr");
          var email = String(adminUser.email || "").toLowerCase();
          var canEdit = manageable[email] === true;

          function addCell(node) {
            var td = el("td");
            td.style.padding = "10px";
            td.style.borderBottom = "1px solid #f1f5f9";
            td.style.verticalAlign = "middle";
            td.appendChild(node);
            tr.appendChild(td);
          }

          var identity = el("div");
          identity.appendChild(el("strong", adminUser.name || adminUser.email || "-"));
          var emailNode = el("div", adminUser.email || "-");
          emailNode.style.fontSize = "11px";
          emailNode.style.color = "#64748b";
          identity.appendChild(emailNode);
          addCell(identity);

          var loginStatus = el("strong", adminUser.user_id ? "Klar" : "Venter p\u00E5 f\u00F8rste innlogging");
          loginStatus.style.color = adminUser.user_id ? "#166534" : "#92400e";
          addCell(loginStatus);

          addCell(el("span", adminUser.last_login_at ? formatAdminDateTime(adminUser.last_login_at) : "Aldri"));

          var select = el("select");
          addOption(select, "viewer", "Lesetilgang");
          addOption(select, "staff", "Enkelte funksjoner");
          addOption(select, "full", "Full kontroll");
          select.value = adminUser.access_level || "viewer";
          select.disabled = !canEdit;
          select.style.minWidth = "180px";
          addCell(select);

          var save = createPrimaryButton(canEdit ? "Lagre niv\u00E5" : "Beskyttet fullkonto");
          save.disabled = !canEdit;
          save.style.padding = "8px 10px";

          save.onclick = function () {
            save.disabled = true;
            save.textContent = "Lagrer\u2026";

            sb.rpc("internal_set_admin_user_access", {
              p_email: adminUser.email,
              p_access_level: select.value
            }).then(function (saveResult) {
              if (saveResult.error) {
                save.disabled = false;
                save.textContent = "Lagre niv\u00E5";
                alert("Kunne ikke endre tilgang: " + saveResult.error.message);
                return;
              }

              alert("Tilgangen for " + adminUser.email + " er oppdatert.");
              loadUsers();
            });
          };

          addCell(save);
          tbody.appendChild(tr);
        });

        table.appendChild(tbody);
        wrap.appendChild(table);
        host.appendChild(wrap);
      });
    }

    loadUsers();
  }

