    function runFullQuickbutikPurchasePriceSync(
      button,
      resultBox
    ) {
      if (
        state.quickbutikFullSyncRunning
      ) {
        return;
      }

      var confirmed =
        window.confirm(
          "Dette kj\u00F8rer FULL SYNK av alle gjenst\u00E5ende dokumenterte vektede innkj\u00F8pspriser til Quickbutik.\n\n" +
          "Kun purchase_price (innkj\u00F8pspris eks. mva.) sendes.\n" +
          "Lager, salgspris, synlighet og andre produktfelter endres ikke.\n\n" +
          "Synken g\u00E5r i sm\u00E5 batcher og stopper automatisk hvis Quickbutik eller Sportskongen returnerer feil.\n\n" +
          "Vil du fortsette?"
        );

      if (!confirmed) {
        return;
      }

      state.quickbutikFullSyncRunning =
        true;

      var originalLabel =
        button.textContent;

      button.disabled = true;
      button.textContent =
        "Starter full Quickbutik-synk\u2026";

      if (resultBox) {
        resultBox.style.display =
          "block";
        resultBox.textContent =
          "Starter full kostsynk. Henter innlogget session\u2026";
      }

      var totalMarked =
        0;

      var totalRequested =
        0;

      var batchNumber =
        0;

      var latestSummary =
        null;

      var accessToken =
        null;


      function updateProgress(
        message
      ) {
        if (resultBox) {
          resultBox.textContent =
            message;
        }
      }


      function sleep(
        ms
      ) {
        return new Promise(
          function (resolve) {
            setTimeout(
              resolve,
              ms
            );
          }
        );
      }


      function runNextBatch() {
        batchNumber += 1;

        if (
          batchNumber > 100
        ) {
          throw new Error(
            "Sikkerhetsstopp: mer enn 100 batcher. Synken ble stoppet for kontroll."
          );
        }

        button.textContent =
          "Synker batch " +
          String(
            batchNumber
          ) +
          "\u2026";

        updateProgress(
          "Batch " +
            String(
              batchNumber
            ) +
            " kj\u00F8rer.\n\n" +
            "Totalt sendt s\u00E5 langt: " +
            String(
              totalRequested
            ) +
            "\n" +
            "Totalt markert synket: " +
            String(
              totalMarked
            ) +
            (
              latestSummary
                ? "\nGjenst\u00E5r if\u00F8lge siste svar: " +
                  String(
                    latestSummary.needs_sync
                  )
                : ""
            )
        );

        var url =
          "https://sportskongen-quickbutik-sync.post-cd6.workers.dev/sync-purchase-prices" +
          "?dryRun=false" +
          "&limit=20";

        return fetch(
          url,
          {
            method: "GET",
            headers: {
              "Authorization":
                "Bearer " +
                accessToken
            }
          }
        )
          .then(
            function (response) {
              return response
                .json()
                .then(
                  function (data) {
                    return {
                      ok:
                        response.ok,
                      status:
                        response.status,
                      data:
                        data
                    };
                  }
                );
            }
          )
          .then(
            function (result) {
              if (
                !result.ok ||
                !result.data ||
                result.data.ok !== true
              ) {
                throw new Error(
                  "Batch " +
                    String(
                      batchNumber
                    ) +
                    " feilet (" +
                    String(
                      result.status
                    ) +
                    "): " +
                    JSON.stringify(
                      result.data
                    )
                );
              }

              var requested =
                Number(
                  result.data.requested ||
                  0
                );

              var marked =
                Number(
                  result.data.marked_synced ||
                  0
                );

              totalRequested +=
                requested;

              totalMarked +=
                marked;

              latestSummary =
                result.data.summary ||
                latestSummary;

              if (
                requested === 0
              ) {
                return {
                  done:
                    true
                };
              }

              if (
                latestSummary &&
                Number(
                  latestSummary.needs_sync ||
                  0
                ) === 0
              ) {
                return {
                  done:
                    true
                };
              }

              return sleep(
                350
              ).then(
                function () {
                  return runNextBatch();
                }
              );
            }
          );
      }


      sb.auth.getSession()
        .then(
          function (sessionResult) {
            var session =
              sessionResult.data &&
              sessionResult.data.session;

            accessToken =
              session &&
              session.access_token;

            if (!accessToken) {
              throw new Error(
                "Fant ikke innlogget Supabase-session."
              );
            }

            return runNextBatch();
          }
        )
        .then(
          function () {
            var remaining =
              latestSummary
                ? Number(
                    latestSummary.needs_sync ||
                    0
                  )
                : null;

            updateProgress(
              "FULL SYNK FERDIG.\n\n" +
              "Batcher: " +
              String(
                batchNumber
              ) +
              "\n" +
              "Kostm\u00E5l sendt: " +
              String(
                totalRequested
              ) +
              "\n" +
              "Kostm\u00E5l markert synket: " +
              String(
                totalMarked
              ) +
              "\n" +
              "Gjenst\u00E5r: " +
              String(
                remaining === null
                  ? "ukjent"
                  : remaining
              ) +
              "\n\n" +
              "Lagerantall og salgspriser er ikke endret."
            );

            alert(
              "Full Quickbutik-kostsynk er ferdig.\n\n" +
              "Kostm\u00E5l markert synket: " +
              String(
                totalMarked
              ) +
              "\n" +
              "Gjenst\u00E5r: " +
              String(
                remaining === null
                  ? "ukjent"
                  : remaining
              ) +
              "\n\n" +
              "Send meg resultatet f\u00F8r vi rydder bort testknappene."
            );
          }
        )
        .catch(
          function (error) {
            updateProgress(
              "SYNK STOPPET.\n\n" +
              "Batch: " +
              String(
                batchNumber
              ) +
              "\n" +
              "Sendt f\u00F8r stopp: " +
              String(
                totalRequested
              ) +
              "\n" +
              "Markert synket f\u00F8r stopp: " +
              String(
                totalMarked
              ) +
              "\n\n" +
              (
                error &&
                error.message
                  ? error.message
                  : String(error)
              )
            );

            alert(
              "Full Quickbutik-synk ble stoppet.\n\n" +
              (
                error &&
                error.message
                  ? error.message
                  : String(error)
              ) +
              "\n\n" +
              "Allerede vellykkede batcher er bevart. Ikke start p\u00E5 nytt f\u00F8r vi har kontrollert feilen."
            );
          }
        )
        .finally(
          function () {
            state.quickbutikFullSyncRunning =
              false;

            button.disabled = false;
            button.textContent =
              originalLabel;
          }
        );
    }


