    function num(value) {
      var parsed = Number(value);

      return Number.isFinite(parsed)
        ? parsed
        : 0;
    }

    function maybeNum(value) {
      if (
        value === null ||
        value === undefined ||
        value === ""
      ) {
        return null;
      }

      var parsed = Number(value);

      return Number.isFinite(parsed)
        ? parsed
        : null;
    }

    function fmtNumber(
      value,
      digits
    ) {
      var parsed = maybeNum(value);

      if (parsed === null) {
        return "\u2013";
      }

      return parsed.toLocaleString(
        "no-NO",
        {
          minimumFractionDigits:
            digits || 0,
          maximumFractionDigits:
            digits || 0
        }
      );
    }

    function fmtMoneyNok(value) {
      var parsed = maybeNum(value);

      if (parsed === null) {
        return "\u2013";
      }

      return parsed.toLocaleString(
        "no-NO",
        {
          minimumFractionDigits: 2,
          maximumFractionDigits: 2
        }
      ) + " kr";
    }

    function fmtCurrency(
      value,
      currency
    ) {
      var parsed = maybeNum(value);

      if (parsed === null) {
        return "\u2013";
      }

      return parsed.toLocaleString(
        "no-NO",
        {
          minimumFractionDigits: 2,
          maximumFractionDigits: 2
        }
      ) +
        " " +
        String(currency || "");
    }

    function fmtDate(value) {
      if (!value) {
        return "\u2013";
      }

      var parts =
        String(value).split("-");

      if (parts.length !== 3) {
        return String(value);
      }

      return (
        parts[2] +
        "." +
        parts[1] +
        "." +
        parts[0]
      );
    }

