    function normalizeSupplierName(
      value
    ) {
      return String(
        value || ""
      )
        .toLowerCase()
        .replace(
          /[^a-z0-9\u00E6\u00F8\u00E5]+/g,
          " "
        )
        .replace(
          /\s+/g,
          " "
        )
        .trim();
    }

    function parseNordicNumber(
      value
    ) {
      if (
        value === null ||
        value === undefined
      ) {
        return null;
      }

      var cleaned =
        String(value)
          .replace(
            /\u00a0/g,
            " "
          )
          .replace(
            /[\u2212\u2013\u2014]/g,
            "-"
          )
          .replace(
            /\s+/g,
            ""
          )
          .replace(
            /\./g,
            ""
          )
          .replace(
            ",",
            "."
          )
          .trim();

      if (!cleaned) {
        return null;
      }

      var parsed =
        Number(cleaned);

      return Number.isFinite(parsed)
        ? parsed
        : null;
    }


    function parseEnglishNumber(
      value
    ) {
      if (
        value === null ||
        value === undefined
      ) {
        return null;
      }

      var cleaned =
        String(value)
          .replace(
            /\u00a0/g,
            " "
          )
          .replace(
            /\s+/g,
            ""
          )
          .replace(
            /,/g,
            ""
          )
          .trim();

      if (!cleaned) {
        return null;
      }

      var parsed =
        Number(cleaned);

      return Number.isFinite(parsed)
        ? parsed
        : null;
    }


    function loadPdfJs() {
      if (
        window.pdfjsLib &&
        window.pdfjsLib.getDocument
      ) {
        return Promise.resolve(
          window.pdfjsLib
        );
      }

      if (state.pdfJsPromise) {
        return state.pdfJsPromise;
      }

      state.pdfJsPromise =
        new Promise(
          function (
            resolve,
            reject
          ) {
            var script =
              document.createElement(
                "script"
              );

            script.src =
              "https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js";

            script.async = true;
            script.crossOrigin =
              "anonymous";

            var timer =
              setTimeout(
                function () {
                  reject(
                    new Error(
                      "PDF-leseren brukte for lang tid p\u00E5 \u00E5 laste."
                    )
                  );
                },
                20000
              );

            script.onload =
              function () {
                clearTimeout(timer);

                if (
                  !window.pdfjsLib ||
                  !window.pdfjsLib
                    .getDocument
                ) {
                  reject(
                    new Error(
                      "PDF-leseren ble lastet, men kunne ikke startes."
                    )
                  );
                  return;
                }

                window.pdfjsLib
                  .GlobalWorkerOptions
                  .workerSrc =
                  "https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js";

                resolve(
                  window.pdfjsLib
                );
              };

            script.onerror =
              function () {
                clearTimeout(timer);

                reject(
                  new Error(
                    "Kunne ikke laste PDF-leseren fra jsDelivr."
                  )
                );
              };

            document.head.appendChild(
              script
            );
          }
        );

      return state.pdfJsPromise;
    }

    function pdfTextContentToLines(
      content
    ) {
      var groups = [];

      (
        content &&
        content.items
          ? content.items
          : []
      ).forEach(
        function (item) {
          var value =
            String(
              item.str || ""
            ).trim();

          if (!value) {
            return;
          }

          var x =
            item.transform &&
            item.transform.length > 4
              ? Number(
                  item.transform[4]
                )
              : 0;

          var y =
            item.transform &&
            item.transform.length > 5
              ? Number(
                  item.transform[5]
                )
              : 0;

          var group =
            groups.find(
              function (candidate) {
                return (
                  Math.abs(
                    candidate.y - y
                  ) < 2.3
                );
              }
            );

          if (!group) {
            group = {
              y: y,
              items: []
            };

            groups.push(group);
          }

          group.items.push({
            x: x,
            value: value
          });
        }
      );

      groups.sort(
        function (a, b) {
          return b.y - a.y;
        }
      );

      return groups.map(
        function (group) {
          group.items.sort(
            function (a, b) {
              return a.x - b.x;
            }
          );

          return group.items
            .map(
              function (item) {
                return item.value;
              }
            )
            .join(" ")
            .replace(
              /\s+/g,
              " "
            )
            .trim();
        }
      );
    }

    function extractPdfText(
      file
    ) {
      return loadPdfJs()
        .then(
          function (pdfjsLib) {
            return file
              .arrayBuffer()
              .then(
                function (
                  buffer
                ) {
                  return pdfjsLib
                    .getDocument({
                      data:
                        new Uint8Array(
                          buffer
                        )
                    })
                    .promise;
                }
              );
          }
        )
        .then(
          function (pdf) {
            var jobs = [];

            for (
              var pageNo = 1;
              pageNo <=
              pdf.numPages;
              pageNo += 1
            ) {
              (
                function (
                  currentPage
                ) {
                  jobs.push(
                    pdf
                      .getPage(
                        currentPage
                      )
                      .then(
                        function (page) {
                          return page
                            .getTextContent()
                            .then(
                              function (
                                content
                              ) {
                                return {
                                  page:
                                    currentPage,
                                  lines:
                                    pdfTextContentToLines(
                                      content
                                    )
                                };
                              }
                            );
                        }
                      )
                  );
                }
              )(pageNo);
            }

            return Promise.all(
              jobs
            );
          }
        );
    }

    function latitudeRowMatch(
      line
    ) {
      var compact =
        String(line || "")
          .replace(
            /\u00a0/g,
            " "
          )
          .replace(
            /\s+/g,
            " "
          )
          .trim();

      /*
       * Permanent Latitude-normalisering.
       *
       * Vi har n\u00E5 sett flere generasjoner av samme Latitude-faktura:
       *
       * A) SKU + EAN + dato:
       *   118078 EAN: 733... 2026-04-14 2 pcs 94,50 189,00
       *
       * B) SKU UTEN EAN + dato:
       *   120648 2026-04-14 2 pcs 120,00 240,00
       *
       * C) dato f\u00F8rst + SKU/EAN til slutt:
       *   2026-02-17 2 pcs 124,50 30% 174,30 117490 EAN: 733...
       *
       * D) som C, men SKU kan ligge limt rett etter summen i PDF-tekstlaget.
       *
       * Rabattprosent er valgfri.
       * EAN er valgfri.
       *
       * Alt normaliseres til samme format som resten av parseren forventer:
       *   [1] dato
       *   [2] antall
       *   [3] enhetspris
       *   [4] faktisk linjesum
       *   [5] leverand\u00F8rens artikkelnummer
       *   [6] EAN eller null
       */

      var skuFirst =
        compact.match(
          /^(\d{5,})(?:\s+EAN:\s*(\d{8,14}))?\s+(\d{4}-\d{2}-\d{2})\s+(\d+(?:[.,]\d+)?)\s+pcs\s+([\d\s]+,\d{2})\s+(?:\d+(?:[.,]\d+)?\s*%\s+)?([\d\s]+,\d{2})$/i
        );

      if (skuFirst) {
        return [
          skuFirst[0],
          skuFirst[3],
          skuFirst[4],
          skuFirst[5],
          skuFirst[6],
          skuFirst[1],
          skuFirst[2] || null
        ];
      }


      var dateFirst =
        compact.match(
          /^(\d{4}-\d{2}-\d{2})\s+(\d+(?:[.,]\d+)?)\s+pcs\s+([\d\s]+,\d{2})\s+(?:\d+(?:[.,]\d+)?\s*%\s+)?([\d\s]+,\d{2})\s+(\d{5,})(?:\s+EAN:\s*(\d{8,14}))?$/i
        );

      if (dateFirst) {
        return [
          dateFirst[0],
          dateFirst[1],
          dateFirst[2],
          dateFirst[3],
          dateFirst[4],
          dateFirst[5],
          dateFirst[6] || null
        ];
      }


      /*
       * Enkelte PDF-tekstlag limer SKU rett p\u00E5 linjesummen:
       *   ... 174,30117490 EAN: ...
       *
       * Denne varianten brukes bare n\u00E5r EAN finnes, slik at skillet mellom
       * bel\u00F8p og artikkelnummer fortsatt er entydig.
       */
      var dateFirstJoined =
        compact.match(
          /^(\d{4}-\d{2}-\d{2})\s+(\d+(?:[.,]\d+)?)\s+pcs\s+([\d\s]+,\d{2})\s+(?:\d+(?:[.,]\d+)?\s*%\s+)?([\d\s]+,\d{2})(\d{5,})\s+EAN:\s*(\d{8,14})$/i
        );

      if (dateFirstJoined) {
        return [
          dateFirstJoined[0],
          dateFirstJoined[1],
          dateFirstJoined[2],
          dateFirstJoined[3],
          dateFirstJoined[4],
          dateFirstJoined[5],
          dateFirstJoined[6]
        ];
      }


      return null;
    }

    function latitudeSpecialCostMatch(
      line
    ) {
      var compact =
        String(line || "")
          .replace(
            /\u00a0/g,
            " "
          )
          .replace(
            /\s+/g,
            " "
          )
          .trim();

      var match = null;

      /*
       * Eksempler fra Latitude:
       *
       *   1 pcs 100,00 100,00 90002
       *   1 pcs 2 595,00 2 595,00 90000
       *
       * PDF.js kan ogs\u00E5 flytte artikkelnummeret f\u00F8rst eller legge inn dato.
       */
      var patterns = [
        /^1(?:\s+pcs)?\s+([\d\s]+,\d{2})\s+([\d\s]+,\d{2})\s+(90000|90002)$/i,
        /^1(?:\s+pcs)?\s+([\d\s]+,\d{2})\s+([\d\s]+,\d{2})(90000|90002)$/i,
        /^(90000|90002)\s+1(?:\s+pcs)?\s+([\d\s]+,\d{2})\s+([\d\s]+,\d{2})$/i,
        /^(\d{4}-\d{2}-\d{2})\s+1(?:\s+pcs)?\s+([\d\s]+,\d{2})\s+([\d\s]+,\d{2})\s+(90000|90002)$/i
      ];

      match =
        compact.match(
          patterns[0]
        ) ||
        compact.match(
          patterns[1]
        );

      if (match) {
        return {
          supplier_sku:
            match[3],
          unit_price:
            parseNordicNumber(
              match[1]
            ),
          amount:
            parseNordicNumber(
              match[2]
            )
        };
      }

      match =
        compact.match(
          patterns[2]
        );

      if (match) {
        return {
          supplier_sku:
            match[1],
          unit_price:
            parseNordicNumber(
              match[2]
            ),
          amount:
            parseNordicNumber(
              match[3]
            )
        };
      }

      match =
        compact.match(
          patterns[3]
        );

      if (match) {
        return {
          supplier_sku:
            match[4],
          unit_price:
            parseNordicNumber(
              match[2]
            ),
          amount:
            parseNordicNumber(
              match[3]
            )
        };
      }

      return null;
    }

    function parseLatitude64Pdf(
      pages
    ) {
      var allLines = [];

      (pages || []).forEach(
        function (page) {
          (
            page.lines || []
          ).forEach(
            function (rawLine) {
              var clean =
                String(
                  rawLine || ""
                )
                  .replace(
                    /\u00a0/g,
                    " "
                  )
                  .replace(
                    /\s+/g,
                    " "
                  )
                  .trim();

              if (clean) {
                allLines.push(
                  clean
                );
              }
            }
          );
        }
      );

      var fullText =
        allLines.join("\n");

      if (
        !/Latitude\s*64/i.test(
          fullText
        ) &&
        !/latitude64\.com/i.test(
          fullText
        )
      ) {
        return null;
      }

      if (
        !/Faktura\s+\d+/i.test(
          fullText
        )
      ) {
        return null;
      }

      var invoiceNoMatch =
        fullText.match(
          /Faktura\s+([0-9]+)/i
        );

      var invoiceDateMatch =
        fullText.match(
          /Datum\s*:?\s*(\d{4}-\d{2}-\d{2})/i
        );

      var dueDateMatch =
        fullText.match(
          /F\u00F6rfallodatum\s*:?\s*(\d{4}-\d{2}-\d{2})/i
        );

      /*
       * P\u00E5 enkelte DiscGolfPark-PDF-er ligger kolonneoverskriftene
       * "Kundnr.  Datum  Sida" p\u00E5 \u00E9n tekstlinje og verdiene
       * "C10847  2026-08-18  1 av 1" p\u00E5 neste. Da st\u00E5r ikke ordet
       * Datum direkte foran datoen i PDF-teksten.
       */
      if (!invoiceDateMatch) {
        for (
          var d = 0;
          d < allLines.length - 1;
          d += 1
        ) {
          if (
            /Kundnr\./i.test(
              allLines[d]
            ) &&
            /Datum/i.test(
              allLines[d]
            )
          ) {
            var headerDate =
              String(
                allLines[d + 1] || ""
              ).match(
                /(\d{4}-\d{2}-\d{2})/
              );

            if (headerDate) {
              invoiceDateMatch =
                headerDate;
              break;
            }
          }
        }
      }

      /*
       * Samme kolonnelogikk brukes for
       * "F\u00F6rfallodatum  Betalningsvillkor".
       */
      if (!dueDateMatch) {
        for (
          var fd = 0;
          fd < allLines.length - 1;
          fd += 1
        ) {
          if (
            /F\u00F6rfallodatum/i.test(
              allLines[fd]
            )
          ) {
            var dueHeaderDate =
              String(
                allLines[fd + 1] || ""
              ).match(
                /(\d{4}-\d{2}-\d{2})/
              );

            if (dueHeaderDate) {
              dueDateMatch =
                dueHeaderDate;
              break;
            }
          }
        }
      }

      /*
       * Siste sikkerhetsnett for akkurat denne fakturatypen:
       * - leveringsdatoene p\u00E5 varelinjene er ofte dagen f\u00F8r fakturadato
       * - forfallsdato er senere enn fakturadato
       *
       * Vi bruker kun dette n\u00E5r de eksplisitte headerfors\u00F8kene feiler.
       */
      if (
        !invoiceDateMatch ||
        !dueDateMatch
      ) {
        var uniqueIsoDates = [];

        allLines.forEach(
          function (line) {
            var found =
              String(
                line || ""
              ).match(
                /\b\d{4}-\d{2}-\d{2}\b/g
              ) || [];

            found.forEach(
              function (value) {
                if (
                  uniqueIsoDates.indexOf(
                    value
                  ) < 0
                ) {
                  uniqueIsoDates.push(
                    value
                  );
                }
              }
            );
          }
        );

        uniqueIsoDates.sort();

        if (
          !dueDateMatch &&
          uniqueIsoDates.length >= 2
        ) {
          dueDateMatch = [
            "",
            uniqueIsoDates[
              uniqueIsoDates.length - 1
            ]
          ];
        }

        if (
          !invoiceDateMatch &&
          uniqueIsoDates.length >= 2
        ) {
          invoiceDateMatch = [
            "",
            uniqueIsoDates[
              uniqueIsoDates.length - 2
            ]
          ];
        }
      }

      var currencyMatch =
        fullText.match(
          /Summa\s+totalt\s+([A-Z]{3})/i
        ) ||
        fullText.match(
          /Summa\s+([A-Z]{3})\s*Lev\.datum/i
        );

      var currency =
        currencyMatch
          ? String(
              currencyMatch[1]
            ).toUpperCase()
          : "SEK";

      var rows = [];
      var costs = [];

      /*
       * ------------------------------------------------------------
       * TYPE A: ordin\u00E6re Latitude-/House of Discs-varefakturaer.
       *
       * Dette er den gamle parseren som allerede brukes p\u00E5 f.eks.
       * faktura 2010943. Den beholdes uendret som f\u00F8rste fors\u00F8k.
       * ------------------------------------------------------------
       */
      (pages || []).forEach(
        function (page) {
          var inItems = false;

          /*
           * Latitude-PDF-er finnes i minst to tekst-rekkef\u00F8lger:
           *
           * 1) beskrivelse -> tallrad -> HS/COO
           * 2) tallrad -> beskrivelse -> HS/COO
           *
           * Faktura 2008760 bruker nr. 2 selv om den visuelt ser lik ut.
           * Vi st\u00F8tter derfor begge uten \u00E5 gjette.
           */
          var pendingDescription = [];
          var openNumericMatch = null;

          function finishLatitudeRow(
            match,
            descriptionParts
          ) {
            if (!match) {
              return;
            }

            var description =
              (descriptionParts || [])
                .join(" ")
                .replace(
                  /\s+/g,
                  " "
                )
                .trim();

            /*
             * Importmotoren krever beskrivelse. Vi skal normalt alltid ha
             * funnet den fra PDF-en. Fallbacken gj\u00F8r likevel at en uvanlig
             * tekststr\u00F8m ikke stopper hele fakturaen; SKU/EAN gj\u00F8r fortsatt
             * produktkoblingen mulig.
             */
            if (!description) {
              description =
                "Latitude vare " +
                String(
                  match[5] || ""
                );
            }

            rows.push({
              line_number:
                rows.length + 1,
              supplier_sku:
                match[5],
              ean:
                match[6],
              description:
                description,
              quantity:
                parseNordicNumber(
                  match[2]
                ),
              unit_price:
                parseNordicNumber(
                  match[3]
                ),
              line_total:
                parseNordicNumber(
                  match[4]
                )
            });
          }

          (
            page.lines || []
          ).forEach(
            function (rawLine) {
              var line =
                String(
                  rawLine || ""
                )
                  .replace(
                    /\s+/g,
                    " "
                  )
                  .trim();

              if (!line) {
                return;
              }

              if (
                /Antal/i.test(line) &&
                /Artikel/i.test(line)
              ) {
                inItems = true;
                pendingDescription = [];
                openNumericMatch = null;
                return;
              }

              if (!inItems) {
                return;
              }

              if (
                /^Summa totalt\b/i.test(
                  line
                )
              ) {
                if (openNumericMatch) {
                  finishLatitudeRow(
                    openNumericMatch,
                    pendingDescription
                  );
                }

                inItems = false;
                pendingDescription = [];
                openNumericMatch = null;
                return;
              }

              /*
               * Frakt/Pall er egne kostlinjer og skal aldri brukes som
               * produktbeskrivelse. Selve 90000/90002-radene leses separat.
               */
              if (
                /^Frakt$/i.test(
                  line
                ) ||
                /^Pall\s*-\s*EUR$/i.test(
                  line
                )
              ) {
                return;
              }

              if (
                /^COO:/i.test(line) ||
                /^HS Code:/i.test(line) ||
                (
                  /COO:/i.test(line) &&
                  /HS Code:/i.test(line)
                )
              ) {
                /*
                 * I tallrad-f\u00F8rst-formatet markerer HS/COO slutten p\u00E5
                 * beskrivelsen til den \u00E5pne varen.
                 */
                if (openNumericMatch) {
                  finishLatitudeRow(
                    openNumericMatch,
                    pendingDescription
                  );

                  openNumericMatch = null;
                  pendingDescription = [];
                }

                return;
              }

              var match =
                latitudeRowMatch(
                  line
                );

              if (match) {
                /*
                 * Hvis forrige tallrad fortsatt er \u00E5pen, avslutt den f\u00F8rst.
                 * Dette er sikkerhetsnett for PDF-er uten egen HS/COO-linje.
                 */
                if (openNumericMatch) {
                  finishLatitudeRow(
                    openNumericMatch,
                    pendingDescription
                  );

                  openNumericMatch = null;
                  pendingDescription = [];
                }

                /*
                 * Har vi allerede tekst f\u00F8r tallraden, er dette det gamle
                 * beskrivelse-f\u00F8rst-formatet og raden kan lagres n\u00E5.
                 */
                if (
                  pendingDescription.length > 0
                ) {
                  finishLatitudeRow(
                    match,
                    pendingDescription
                  );

                  pendingDescription = [];
                  return;
                }

                /*
                 * Ellers bruker PDF-en tallrad f\u00F8rst. Vent p\u00E5 beskrivelsen
                 * som kommer p\u00E5 neste linje(r).
                 */
                openNumericMatch =
                  match;
                pendingDescription = [];
                return;
              }

              pendingDescription.push(
                line
              );
            }
          );

          /*
           * Sikkerhetsnett for siste vare p\u00E5 siden dersom PDF-en ikke har
           * HS/COO etter den.
           */
          if (openNumericMatch) {
            finishLatitudeRow(
              openNumericMatch,
              pendingDescription
            );
          }
        }
      );

      /*
       * Latitude bruker egne artikler for logistikk:
       *   90000 = Frakt
       *   90002 = Pall - EUR
       *
       * Disse mangler normalt EAN og skal derfor aldri bli varelinjer.
       * Vi leser dem eksplisitt og fordeler dem etter vareverdi.
       */
      if (
        rows.length > 0
      ) {
        var seenSpecialCosts = {};

        allLines.forEach(
          function (line) {
            var special =
              latitudeSpecialCostMatch(
                line
              );

            if (
              !special ||
              !special.supplier_sku ||
              !Number.isFinite(
                num(
                  special.amount
                )
              )
            ) {
              return;
            }

            var sku =
              String(
                special.supplier_sku
              );

            if (
              seenSpecialCosts[sku]
            ) {
              return;
            }

            seenSpecialCosts[sku] =
              true;

            if (
              sku === "90000"
            ) {
              costs.push({
                cost_type:
                  "shipping",
                description:
                  "Frakt",
                amount:
                  num(
                    special.amount
                  ),
                allocation_method:
                  "by_value"
              });

              return;
            }

            if (
              sku === "90002"
            ) {
              costs.push({
                cost_type:
                  "other",
                description:
                  "Pall - EUR",
                amount:
                  num(
                    special.amount
                  ),
                allocation_method:
                  "by_value"
              });
            }
          }
        );
      }

      /*
       * Ekstra robust fallback for 90000/90002:
       * enkelte Latitude-PDF-er grupperer logistikkradene annerledes enn
       * ordin\u00E6re varelinjer. S\u00F8k derfor ogs\u00E5 direkte i hele tekstlaget.
       * Deduplisering skjer p\u00E5 artikkelnummer.
       */
      if (
        rows.length > 0
      ) {
        var existingCostDescriptions =
          costs.map(
            function (cost) {
              return String(
                cost.description || ""
              ).toLowerCase();
            }
          );

        function addLatitudeFallbackCost(
          sku,
          amount
        ) {
          var numericAmount =
            num(
              amount
            );

          if (
            !Number.isFinite(
              numericAmount
            ) ||
            numericAmount < 0
          ) {
            return;
          }

          if (
            sku === "90000" &&
            existingCostDescriptions.indexOf(
              "frakt"
            ) < 0
          ) {
            costs.push({
              cost_type:
                "shipping",
              description:
                "Frakt",
              amount:
                numericAmount,
              allocation_method:
                "by_value"
            });

            existingCostDescriptions.push(
              "frakt"
            );

            return;
          }

          if (
            sku === "90002" &&
            existingCostDescriptions.indexOf(
              "pall - eur"
            ) < 0
          ) {
            costs.push({
              cost_type:
                "other",
              description:
                "Pall - EUR",
              amount:
                numericAmount,
              allocation_method:
                "by_value"
            });

            existingCostDescriptions.push(
              "pall - eur"
            );
          }
        }

        var palletFallback =
          fullText.match(
            /(?:^|\n)\s*90002\s+1(?:\s+pcs)?\s+([\d\s]+,\d{2})\s+([\d\s]+,\d{2})(?:\s|$)/im
          );

        if (palletFallback) {
          addLatitudeFallbackCost(
            "90002",
            parseNordicNumber(
              palletFallback[2]
            )
          );
        }

        var shippingFallback =
          fullText.match(
            /(?:^|\n)\s*90000\s+1(?:\s+pcs)?\s+([\d\s]+,\d{2})\s+([\d\s]+,\d{2})(?:\s|$)/im
          );

        if (shippingFallback) {
          addLatitudeFallbackCost(
            "90000",
            parseNordicNumber(
              shippingFallback[2]
            )
          );
        }
      }


      /*
       * ------------------------------------------------------------
       * TYPE B: DiscGolfPark / utstyrsfaktura.
       *
       * Typisk struktur:
       *
       * 115500  EAN: ...  2026-08-17  5 pcs  3 203,00  16 015,00
       * DGP DiscGolfPark Pro Target (permanent)
       *
       * 115520 ... 5 pcs 0,00 0,00
       * DGP Top with chains & basket (target set)
       *
       * 117370 ... 5 pcs 429,00 2 145,00
       * Concrete base w/tightening ring
       *
       * 115974 ... 1 pcs 550,00 550,00
       * DGP Handling
       *
       * 90000 ... 1 pcs 3 923,00 3 923,00
       * Shipping
       *
       * Her skal:
       *   - betalte hovedvarer bli varelinjer
       *   - 0-kroners komponenter ignoreres (de f\u00F8lger hovedvaren)
       *   - concrete base / jordfeste bli tilleggskost
       *   - handling bli tilleggskost
       *   - shipping bli frakt
       *
       * Dermed blir hele fakturabel\u00F8pet med i reell kost, uten at
       * komponentene blir egne GolfKongen-produkter.
       * ------------------------------------------------------------
       */
      if (
        rows.length === 0 &&
        /Enhetspris/i.test(
          fullText
        ) &&
        /Lev\.datum/i.test(
          fullText
        )
      ) {
        var equipmentRaw = [];
        var current = null;
        var inEquipment = false;

        function finishEquipmentRow() {
          if (!current) {
            return;
          }

          current.description =
            String(
              current.description ||
              ""
            )
              .replace(
                /\s+/g,
                " "
              )
              .trim();

          equipmentRaw.push(
            current
          );

          current = null;
        }

        function equipmentAnchorMatch(
          line
        ) {
          var compact =
            String(
              line || ""
            )
              .replace(
                /\u00a0/g,
                " "
              )
              .replace(
                /\s+/g,
                " "
              )
              .trim();

          /*
           * Artikkel f\u00F8rst, EAN valgfri.
           */
          var match =
            compact.match(
              /^(\d{5,})(?:\s+EAN:\s*(\d{8,14}))?\s+(\d{4}-\d{2}-\d{2})\s+(\d+(?:[.,]\d+)?)(?:\s+pcs)?\s+([\d\s]+,\d{2})\s+([\d\s]+,\d{2})(?:\s+(.*))?$/i
            );

          if (match) {
            return {
              supplier_sku:
                match[1],
              ean:
                match[2] || null,
              date:
                match[3],
              quantity:
                parseNordicNumber(
                  match[4]
                ),
              unit_price:
                parseNordicNumber(
                  match[5]
                ),
              line_total:
                parseNordicNumber(
                  match[6]
                ),
              description:
                match[7] || ""
            };
          }

          /*
           * Noen PDF-er kan plassere datoen f\u00F8rst.
           */
          match =
            compact.match(
              /^(\d{4}-\d{2}-\d{2})\s+(\d+(?:[.,]\d+)?)(?:\s+pcs)?\s+([\d\s]+,\d{2})\s+([\d\s]+,\d{2})\s+(\d{5,})(?:\s+EAN:\s*(\d{8,14}))?(?:\s+(.*))?$/i
            );

          if (match) {
            return {
              supplier_sku:
                match[5],
              ean:
                match[6] || null,
              date:
                match[1],
              quantity:
                parseNordicNumber(
                  match[2]
                ),
              unit_price:
                parseNordicNumber(
                  match[3]
                ),
              line_total:
                parseNordicNumber(
                  match[4]
                ),
              description:
                match[7] || ""
            };
          }

          return null;
        }

        allLines.forEach(
          function (line) {
            if (
              /Artikel/i.test(line) &&
              /Lev\.datum/i.test(line) &&
              /Enhetspris/i.test(line)
            ) {
              inEquipment = true;
              finishEquipmentRow();
              return;
            }

            if (!inEquipment) {
              return;
            }

            if (
              /^Outside Community/i.test(
                line
              ) ||
              /^Netto\b/i.test(
                line
              ) ||
              /^Summa totalt\b/i.test(
                line
              )
            ) {
              finishEquipmentRow();
              inEquipment = false;
              return;
            }

            if (
              /^HS Code:/i.test(line) ||
              /^COO:/i.test(line) ||
              (
                /HS Code:/i.test(line) &&
                /COO:/i.test(line)
              )
            ) {
              return;
            }

            var anchor =
              equipmentAnchorMatch(
                line
              );

            if (anchor) {
              finishEquipmentRow();
              current = anchor;
              return;
            }

            if (current) {
              /*
               * EAN kan ligge p\u00E5 egen PDF-tekstlinje.
               */
              var eanOnly =
                line.match(
                  /^EAN:\s*(\d{8,14})$/i
                );

              if (eanOnly) {
                current.ean =
                  eanOnly[1];
                return;
              }

              current.description =
                (
                  current.description
                    ? (
                        current.description +
                        " "
                      )
                    : ""
                ) +
                line;
            }
          }
        );

        finishEquipmentRow();


        /*
         * Ekstra fallback n\u00E5r PDF-en har artikkelnummer og resten av
         * tallkolonnene p\u00E5 \u00E9n tekstlinje, men beskrivelsen p\u00E5 neste.
         */
        if (
          equipmentRaw.length === 0
        ) {
          var flat =
            allLines.join(" ");

          var flatPattern =
            /(?:^|\s)(\d{5,})(?:\s+EAN:\s*(\d{8,14}))?\s+(\d{4}-\d{2}-\d{2})\s+(\d+(?:[.,]\d+)?)(?:\s+pcs)?\s+([\d\s]+,\d{2})\s+([\d\s]+,\d{2})\s+(.+?)(?=\s+\d{5,}(?:\s+EAN:|\s+\d{4}-\d{2}-\d{2})|\s+Outside Community|\s+Netto\b|$)/gi;

          var flatMatch;

          while (
            (
              flatMatch =
                flatPattern.exec(
                  flat
                )
            ) !== null
          ) {
            equipmentRaw.push({
              supplier_sku:
                flatMatch[1],
              ean:
                flatMatch[2] || null,
              date:
                flatMatch[3],
              quantity:
                parseNordicNumber(
                  flatMatch[4]
                ),
              unit_price:
                parseNordicNumber(
                  flatMatch[5]
                ),
              line_total:
                parseNordicNumber(
                  flatMatch[6]
                ),
              description:
                String(
                  flatMatch[7] || ""
                )
                  .replace(
                    /HS Code:.*?(?=\s+\d{5,}|\s+Outside Community|\s+Netto\b|$)/gi,
                    ""
                  )
                  .replace(
                    /\s+/g,
                    " "
                  )
                  .trim()
            });
          }
        }


        equipmentRaw.forEach(
          function (item) {
            var description =
              String(
                item.description ||
                ""
              )
                .replace(
                  /HS Code:.*$/i,
                  ""
                )
                .replace(
                  /COO:.*$/i,
                  ""
                )
                .replace(
                  /\s+/g,
                  " "
                )
                .trim();

            var amount =
              num(
                item.line_total
              );

            var unitPrice =
              num(
                item.unit_price
              );

            /*
             * 0-kroners komponenter er deler av hovedproduktet og skal
             * derfor ikke skape manuelle produktlinjer i kostkontrollen.
             */
            if (
              amount === 0 &&
              unitPrice === 0
            ) {
              return;
            }

            var isShipping =
              String(
                item.supplier_sku
              ) === "90000" ||
              /\bshipping\b/i.test(
                description
              ) ||
              /\bfrakt\b/i.test(
                description
              );

            var isHandling =
              /\bhandling\b/i.test(
                description
              );

            var isConcreteBase =
              /concrete\s+base/i.test(
                description
              ) ||
              /tightening\s+ring/i.test(
                description
              ) ||
              /\bjordfeste\b/i.test(
                description
              );

            if (
              isShipping ||
              isHandling ||
              isConcreteBase
            ) {
              costs.push({
                cost_type:
                  isShipping
                    ? "shipping"
                    : "other",

                description:
                  isConcreteBase
                    ? (
                        description ||
                        "Concrete base / jordfeste"
                      )
                    : (
                        description ||
                        (
                          isHandling
                            ? "Handling"
                            : "Shipping"
                        )
                      ),

                amount:
                  amount,

                /*
                 * P\u00E5 disse DiscGolfPark-fakturaene er kostnadene en del
                 * av den ferdige m\u00E5lkurven. by_value gj\u00F8r ogs\u00E5 l\u00F8sningen
                 * trygg hvis en senere faktura har flere betalte m\u00E5ltyper.
                 */
                allocation_method:
                  "by_value"
              });

              return;
            }

            rows.push({
              line_number:
                rows.length + 1,
              supplier_sku:
                item.supplier_sku,
              ean:
                item.ean,
              description:
                description,
              quantity:
                item.quantity,
              unit_price:
                item.unit_price,
              line_total:
                item.line_total
            });
          }
        );
      }


      var totalMatch =
        fullText.match(
          /Summa\s+totalt\s+[A-Z]{3}\s+([\d\s]+,\d{2})/i
        );

      var invoiceTotal =
        totalMatch
          ? parseNordicNumber(
              totalMatch[1]
            )
          : null;

      /*
       * Enkel fallback til Netto hvis "Summa totalt SEK" blir splittet
       * annerledes i PDF-teksten.
       */
      if (
        invoiceTotal === null
      ) {
        var netFallback =
          fullText.match(
            /(?:^|\n)\s*Netto\s+([\d\s]+,\d{2})(?:\s|$)/im
          );

        if (netFallback) {
          invoiceTotal =
            parseNordicNumber(
              netFallback[1]
            );
        }
      }

      var goodsTotal =
        rows.reduce(
          function (
            sum,
            row
          ) {
            return (
              sum +
              num(
                row.line_total
              )
            );
          },
          0
        );

      var extraTotal =
        costs.reduce(
          function (
            sum,
            cost
          ) {
            return (
              sum +
              num(
                cost.amount
              )
            );
          },
          0
        );

      var computedTotal =
        goodsTotal +
        extraTotal;

      var difference =
        invoiceTotal === null
          ? null
          : Math.abs(
              computedTotal -
              invoiceTotal
            );

      return {
        parser:
          rows.length > 0 &&
          costs.some(
            function (cost) {
              return (
                /concrete\s+base/i.test(
                  cost.description || ""
                ) ||
                /\bhandling\b/i.test(
                  cost.description || ""
                )
              );
            }
          )
            ? "latitude64-equipment-v1"
            : "latitude64-v2",

        parser_label:
          "Latitude 64 / House of Discs \u00B7 v5",

        supplier_hint:
          "Latitude 64",

        invoice_number:
          invoiceNoMatch
            ? invoiceNoMatch[1]
            : "",

        invoice_date:
          invoiceDateMatch
            ? invoiceDateMatch[1]
            : "",

        due_date:
          dueDateMatch
            ? dueDateMatch[1]
            : "",

        currency:
          currency,

        rows:
          rows,

        costs:
          costs,

        goods_total:
          goodsTotal,

        /*
         * UI-feltet heter Frakt/tillegg. Derfor skal dette v\u00E6re SUMMEN
         * av concrete base + handling + shipping, ikke bare shipping.
         */
        shipping_total:
          extraTotal,

        invoice_total:
          invoiceTotal,

        computed_total:
          computedTotal,

        difference:
          difference,

        raw_text:
          fullText
      };
    }

    function parseSuneSportPdf(
      pages
    ) {
      var fullLines = [];

      (pages || []).forEach(
        function (page) {
          (
            page.lines || []
          ).forEach(
            function (line) {
              var clean =
                String(
                  line || ""
                )
                  .replace(
                    /\u00a0/g,
                    " "
                  )
                  .replace(
                    /\s+/g,
                    " "
                  )
                  .trim();

              if (clean) {
                fullLines.push(
                  clean
                );
              }
            }
          );
        }
      );

      var fullText =
        fullLines.join("\n");

      if (
        !/Sune\s+Sport\s+AS/i.test(
          fullText
        )
      ) {
        return null;
      }

      var invoiceNoMatch =
        fullText.match(
          /Fakturanr\.\s*:?\s*(?:\n\s*)?([0-9]+)/i
        );

      var invoiceDateMatch =
        fullText.match(
          /Fakturadato\s*:?\s*(?:\n\s*)?(\d{2}\.\d{2}\.\d{4})/i
        );

      if (
        !invoiceNoMatch ||
        !invoiceDateMatch
      ) {
        return null;
      }

      function toIsoDate(
        value
      ) {
        var match =
          String(
            value || ""
          )
            .trim()
            .match(
              /^(\d{2})\.(\d{2})\.(\d{4})$/
            );

        return match
          ? (
              match[3] +
              "-" +
              match[2] +
              "-" +
              match[1]
            )
          : "";
      }

      /*
       * Sune Sport-PDF-en legger ofte tabellcellene i separate PDF-tekst-
       * elementer. Derfor kan vi ikke kreve at en hel varelinje ligger p\u00E5
       * \u00E9n visuell tekstlinje.
       *
       * Vi lager i stedet en tokenstr\u00F8m og leser strukturen:
       *
       * SKU -> beskrivelse -> antall -> STK -> pris -> MVA -> rabatt -> total
       */
      var tokens = [];

      fullLines.forEach(
        function (line) {
          String(line)
            .split(/\s+/)
            .forEach(
              function (token) {
                if (token) {
                  tokens.push(
                    token
                  );
                }
              }
            );
        }
      );

      function isSku(
        token
      ) {
        return (
          /^\d{8}$/.test(
            token
          ) ||
          /^\d{2,}-\d{2,}$/.test(
            token
          ) ||
          /^(?:FI|FD)\d?-[A-Z0-9-]+$/i.test(
            token
          )
        );
      }

      function isQty(
        token
      ) {
        return /^\d+\.\d{2}$/.test(
          token
        );
      }

      function isMoney(
        token
      ) {
        return /^[\d,]+\.\d{2}$/.test(
          token
        );
      }

      var startIndex = -1;
      var stopIndex =
        tokens.length;

      for (
        var si = 0;
        si < tokens.length;
        si += 1
      ) {
        if (
          /^Varenr\.?$/i.test(
            tokens[si]
          )
        ) {
          startIndex =
            si + 1;
          break;
        }
      }

      if (startIndex < 0) {
        startIndex = 0;
      }

      for (
        var ei =
          startIndex;
        ei < tokens.length;
        ei += 1
      ) {
        if (
          /^MVA$/i.test(
            tokens[ei]
          ) &&
          /^spesifisering$/i.test(
            tokens[
              ei + 1
            ] || ""
          )
        ) {
          stopIndex = ei;
          break;
        }
      }

      var rows = [];
      var i = startIndex;

      while (i < stopIndex) {
        if (!isSku(tokens[i])) {
          i += 1;
          continue;
        }

        var sku =
          tokens[i];
        i += 1;

        var descriptionTokens = [];

        /*
         * Beskrivelsen varer frem til f\u00F8rste tall med to desimaler som
         * umiddelbart etterf\u00F8lges av STK.
         */
        while (
          i < stopIndex &&
          !(
            isQty(
              tokens[i]
            ) &&
            /^STK$/i.test(
              tokens[
                i + 1
              ] || ""
            )
          )
        ) {
          /*
           * Hvis vi m\u00F8ter en ny SKU f\u00F8r antall/STK, var forrige kandidat
           * ikke en gyldig varelinje.
           */
          if (
            isSku(
              tokens[i]
            )
          ) {
            break;
          }

          descriptionTokens.push(
            tokens[i]
          );
          i += 1;
        }

        if (
          i >= stopIndex ||
          !isQty(tokens[i]) ||
          !/^STK$/i.test(
            tokens[
              i + 1
            ] || ""
          )
        ) {
          continue;
        }

        var quantity =
          parseEnglishNumber(
            tokens[i]
          );

        i += 2;

        if (
          i >= stopIndex ||
          !isMoney(
            tokens[i]
          )
        ) {
          continue;
        }

        var unitPrice =
          parseEnglishNumber(
            tokens[i]
          );

        i += 1;

        /*
         * Sune kan levere "25 %" som to tokens eller "25%" som ett.
         */
        if (
          /^25$/i.test(
            tokens[i] || ""
          ) &&
          /^%$/i.test(
            tokens[
              i + 1
            ] || ""
          )
        ) {
          i += 2;
        } else if (
          /^25%$/i.test(
            tokens[i] || ""
          )
        ) {
          i += 1;
        }

        /*
         * Rabatt kan v\u00E6re 0%, 15% eller andre prosenter.
         * Sune kan levere den som "15%" eller "15 %".
         */
        var discountPercent = 0;

        if (
          /^\d+(?:[.,]\d+)?%$/i.test(
            tokens[i] || ""
          )
        ) {
          discountPercent =
            parseEnglishNumber(
              String(
                tokens[i]
              ).replace(
                "%",
                ""
              )
            ) || 0;

          i += 1;
        } else if (
          /^\d+(?:[.,]\d+)?$/i.test(
            tokens[i] || ""
          ) &&
          /^%$/i.test(
            tokens[
              i + 1
            ] || ""
          )
        ) {
          discountPercent =
            parseEnglishNumber(
              tokens[i]
            ) || 0;

          i += 2;
        }

        if (
          i >= stopIndex ||
          !isMoney(
            tokens[i]
          )
        ) {
          continue;
        }

        var lineTotal =
          parseEnglishNumber(
            tokens[i]
          );

        i += 1;

        var description =
          descriptionTokens
            .join(" ")
            .replace(
              /\s*-\s+/g,
              "-"
            )
            .replace(
              /\s+/g,
              " "
            )
            .trim();

        if (
          !description ||
          quantity === null ||
          unitPrice === null ||
          lineTotal === null
        ) {
          continue;
        }

        /*
         * Fakturaens "Pris" er f\u00F8r linjerabatt. For kostmotoren vil vi lagre
         * faktisk nettopris per enhet, slik at 15 % rabatt blir med i
         * innkj\u00F8psprisen. Linjesummen er fasiten fordi den ogs\u00E5 fanger
         * fakturaens avrunding.
         */
        var netUnitPrice =
          quantity > 0
            ? lineTotal / quantity
            : unitPrice;

        rows.push({
          line_number:
            rows.length + 1,
          supplier_sku:
            sku,
          ean:
            null,
          description:
            description,
          quantity:
            quantity,
          unit_price:
            netUnitPrice,
          line_total:
            lineTotal,
          list_unit_price:
            unitPrice,
          discount_percent:
            discountPercent
        });
      }

      var exVatMatch =
        fullText.match(
          /Bel\u00F8p ekskl\.\s*MVA\s*(?:\n\s*)?([\d,]+\.\d{2})/i
        );

      var vatMatch =
        fullText.match(
          /Totalt MVA bel\u00F8p\s*(?:\n\s*)?([\d,]+\.\d{2})/i
        );

      var grossMatch =
        fullText.match(
          /\u00C5 betale\s+([A-Z]{3})\s*(?:\n\s*)?([\d,]+\.\d{2})/i
        );

      /*
       * Sune Sport kan legge frakt som egen linje, f.eks.
       * "Freight 423.00". Dette er en direkte innkj\u00F8pskost og skal derfor
       * tas med i kostgrunnlaget, men IKKE som varelinje.
       */
      var freightMatch =
        fullText.match(
          /(?:^|\n)\s*(?:Freight|Frakt)\s+([\d,]+\.\d{2})(?:\s|$)/i
        );

      var shippingTotal =
        freightMatch
          ? parseEnglishNumber(
              freightMatch[1]
            )
          : 0;

      var goodsTotal =
        rows.reduce(
          function (
            sum,
            row
          ) {
            return (
              sum +
              num(
                row.line_total
              )
            );
          },
          0
        );

      var exVatTotal =
        exVatMatch
          ? parseEnglishNumber(
              exVatMatch[1]
            )
          : null;

      var vatTotal =
        vatMatch
          ? parseEnglishNumber(
              vatMatch[1]
            )
          : null;

      var grossTotal =
        grossMatch
          ? parseEnglishNumber(
              grossMatch[2]
            )
          : null;

      var currency =
        grossMatch
          ? String(
              grossMatch[1]
            ).toUpperCase()
          : "NOK";

      var computedTotal =
        goodsTotal +
        shippingTotal;

      var difference =
        exVatTotal === null
          ? null
          : Math.abs(
              computedTotal -
              exVatTotal
            );

      return {
        parser:
          "sune-sport-v5",
        parser_label:
          "Sune Sport AS",
        supplier_hint:
          "Sune Sport AS",
        invoice_number:
          invoiceNoMatch[1],
        invoice_date:
          toIsoDate(
            invoiceDateMatch[1]
          ),
        due_date:
          "",
        currency:
          currency,
        rows:
          rows,
        costs:
          shippingTotal > 0
            ? [
                {
                  cost_type:
                    "shipping",
                  description:
                    "Freight",
                  amount:
                    shippingTotal,
                  allocation_method:
                    "by_value"
                }
              ]
            : [],
        goods_total:
          goodsTotal,
        shipping_total:
          shippingTotal,
        invoice_total:
          exVatTotal,
        total_label:
          "Bel\u00F8p ekskl. MVA",
        vat_total:
          vatTotal,
        gross_total:
          grossTotal,
        computed_total:
          computedTotal,
        difference:
          difference,
        raw_text:
          fullText
      };
    }


    function parseDiscFinderPdf(
      pages
    ) {
      var fullLines = [];

      (pages || []).forEach(
        function (page) {
          (
            page.lines || []
          ).forEach(
            function (line) {
              var clean =
                String(
                  line || ""
                )
                  .replace(
                    /\u00a0/g,
                    " "
                  )
                  .replace(
                    /\s+/g,
                    " "
                  )
                  .trim();

              if (clean) {
                fullLines.push(
                  clean
                );
              }
            }
          );
        }
      );

      var fullText =
        fullLines.join("\n");

      if (
        !/DiscFinder\s+AS/i.test(
          fullText
        )
      ) {
        return null;
      }

      /*
       * DiscFinder-fakturaene har i eksempelet:
       *   Fakturanr.: 100549
       *   Dato       30.08.2026
       *   Forfallsdato 09.09.2026
       *
       * Feltene kan havne p\u00E5 samme eller separate PDF-tekstlinjer.
       */
      var invoiceNoMatch =
        fullText.match(
          /Fakturanr\.?\s*:?\s*(?:\n\s*)?([0-9]+)/i
        );

      var invoiceDateMatch =
        fullText.match(
          /(?:^|\n)\s*Dato\s*:?\s*(?:\n\s*)?(\d{2}\.\d{2}\.\d{4})(?:\s|$)/im
        );

      var dueDateMatch =
        fullText.match(
          /Forfallsdato\s*:?\s*(?:\n\s*)?(\d{2}\.\d{2}\.\d{4})/i
        );

      if (
        !invoiceNoMatch ||
        !invoiceDateMatch
      ) {
        return null;
      }

      function discFinderIsoDate(
        value
      ) {
        var match =
          String(
            value || ""
          )
            .trim()
            .match(
              /^(\d{2})\.(\d{2})\.(\d{4})$/
            );

        return match
          ? (
              match[3] +
              "-" +
              match[2] +
              "-" +
              match[1]
            )
          : "";
      }

      /*
       * Radformat:
       *   #DFV2-5 - DiscFinder V2 5-pak 150,00 15 25 % 2 812,50
       *   #Frakt Bring - Frakt          100,00  1 25 %   125,00
       *
       * Sum-kolonnen er inkl. MVA, mens Enhetspris er eks. MVA.
       * Kostmotoren skal derfor bruke Enhetspris \u00D7 Antall som vare-/fraktkost.
       *
       * Vi flater ut PDF-tekstlinjene fordi tabellcellene kan deles opp
       * forskjellig fra PDF til PDF.
       */
      var flatText =
        fullLines.join(" ");

      var rowPattern =
        /#(.+?)\s+-\s+(.+?)\s+(\d[\d\s.]*,\d{2})\s+(\d+(?:[.,]\d+)?)\s+(\d+(?:[.,]\d+)?)\s*%\s+(\d[\d\s.]*,\d{2})(?=\s+#|\s+Netto\b|\s+Mva\b|\s+\u00C5 betale\b|$)/gi;

      var rows = [];
      var costs = [];
      var rowMatch;

      while (
        (
          rowMatch =
            rowPattern.exec(
              flatText
            )
        ) !== null
      ) {
        var supplierSku =
          String(
            rowMatch[1] || ""
          )
            .replace(
              /\s+/g,
              " "
            )
            .trim();

        var description =
          String(
            rowMatch[2] || ""
          )
            .replace(
              /\s+/g,
              " "
            )
            .trim();

        var unitPrice =
          parseNordicNumber(
            rowMatch[3]
          );

        var quantity =
          parseNordicNumber(
            rowMatch[4]
          );

        var vatPercent =
          parseNordicNumber(
            rowMatch[5]
          );

        var grossLineTotal =
          parseNordicNumber(
            rowMatch[6]
          );

        if (
          unitPrice === null ||
          quantity === null ||
          quantity <= 0
        ) {
          continue;
        }

        var netLineTotal =
          unitPrice *
          quantity;

        var isShipping =
          /^frakt\b/i.test(
            supplierSku
          ) ||
          /^frakt\b/i.test(
            description
          ) ||
          /\bbring\b/i.test(
            supplierSku
          );

        if (isShipping) {
          costs.push({
            cost_type:
              "shipping",
            description:
              (
                supplierSku +
                " - " +
                description
              )
                .replace(
                  /\s+/g,
                  " "
                )
                .trim(),
            amount:
              netLineTotal,
            allocation_method:
              "by_value",
            gross_amount:
              grossLineTotal,
            vat_percent:
              vatPercent
          });

          continue;
        }

        rows.push({
          line_number:
            rows.length + 1,
          supplier_sku:
            supplierSku,
          ean:
            null,
          description:
            description,
          quantity:
            quantity,
          unit_price:
            unitPrice,
          line_total:
            netLineTotal,
          list_unit_price:
            unitPrice,
          discount_percent:
            0,
          gross_line_total:
            grossLineTotal,
          vat_percent:
            vatPercent
        });
      }

      var netMatch =
        fullText.match(
          /(?:^|\n)\s*Netto\s+(\d[\d\s.]*,\d{2})(?:\s|$)/im
        );

      var vatMatch =
        fullText.match(
          /(?:^|\n)\s*Mva\s+(\d[\d\s.]*,\d{2})(?:\s|$)/im
        );

      var grossMatch =
        fullText.match(
          /\u00C5 betale(?:\s+NOK)?\s+(\d[\d\s.]*,\d{2})/i
        );

      var goodsTotal =
        rows.reduce(
          function (
            sum,
            row
          ) {
            return (
              sum +
              num(
                row.line_total
              )
            );
          },
          0
        );

      var shippingTotal =
        costs.reduce(
          function (
            sum,
            cost
          ) {
            return (
              sum +
              num(
                cost.amount
              )
            );
          },
          0
        );

      var netTotal =
        netMatch
          ? parseNordicNumber(
              netMatch[1]
            )
          : null;

      var vatTotal =
        vatMatch
          ? parseNordicNumber(
              vatMatch[1]
            )
          : null;

      var grossTotal =
        grossMatch
          ? parseNordicNumber(
              grossMatch[1]
            )
          : null;

      var computedTotal =
        goodsTotal +
        shippingTotal;

      var difference =
        netTotal === null
          ? null
          : Math.abs(
              computedTotal -
              netTotal
            );

      return {
        parser:
          "discfinder-v1",
        parser_label:
          "DiscFinder AS",
        supplier_hint:
          "DiscFinder AS",
        invoice_number:
          invoiceNoMatch[1],
        invoice_date:
          discFinderIsoDate(
            invoiceDateMatch[1]
          ),
        due_date:
          dueDateMatch
            ? discFinderIsoDate(
                dueDateMatch[1]
              )
            : "",
        currency:
          "NOK",
        rows:
          rows,
        costs:
          costs,
        goods_total:
          goodsTotal,
        shipping_total:
          shippingTotal,
        invoice_total:
          netTotal,
        total_label:
          "Netto ekskl. MVA",
        vat_total:
          vatTotal,
        gross_total:
          grossTotal,
        computed_total:
          computedTotal,
        difference:
          difference,
        raw_text:
          fullText
      };
    }


    function parseDiscGolfShopPdf(
      pages
    ) {
      var fullLines = [];

      (pages || []).forEach(
        function (page) {
          (
            page.lines || []
          ).forEach(
            function (rawLine) {
              var clean =
                String(
                  rawLine || ""
                )
                  .replace(
                    /\u00a0/g,
                    " "
                  )
                  .replace(
                    /\s+/g,
                    " "
                  )
                  .trim();

              if (clean) {
                fullLines.push(
                  clean
                );
              }
            }
          );
        }
      );

      var fullText =
        fullLines.join("\n");

      if (
        !/DiscGolfShop\s+AS/i.test(
          fullText
        ) &&
        !/Discgolfshop\s+AS/i.test(
          fullText
        )
      ) {
        return null;
      }

      var invoiceNoMatch =
        fullText.match(
          /Fakturanr\.?\s*:?\s*(?:\n\s*)?([0-9]+)/i
        );

      var invoiceDateMatch =
        fullText.match(
          /(?:^|\n)\s*Dato\s*:?\s*(?:\n\s*)?(\d{2}\.\d{2}\.\d{4})(?:\s|$)/im
        );

      var dueDateMatch =
        fullText.match(
          /Forfallsdato\s*:?\s*(?:\n\s*)?(\d{2}\.\d{2}\.\d{4})/i
        );

      if (
        !invoiceNoMatch ||
        !invoiceDateMatch
      ) {
        return null;
      }

      function dgshopIsoDate(
        value
      ) {
        var match =
          String(
            value || ""
          )
            .trim()
            .match(
              /^(\d{2})\.(\d{2})\.(\d{4})$/
            );

        return match
          ? (
              match[3] +
              "-" +
              match[2] +
              "-" +
              match[1]
            )
          : "";
      }

      var rows = [];
      var costs = [];

      /*
       * DiscGolfShop bruker Fiken-lignende fakturaoppsett over flere sider:
       *
       *   MVP/Axiom Neutron           115,00   15   25 %   2 156,25
       *   Neutron Trail - Goliath
       *
       *   Frakt                       346,00    1   25 %     432,50
       *   Postnord pakke til bedrift
       *
       *   \u00D8reavrunding                  0,25    1    0 %       0,25
       *
       * Sum-kolonnen er inkl. MVA. Reell varekost er Enhetspris \u00D7 Antall,
       * alts\u00E5 eks. MVA. Tekstlinjen under tall-linjen h\u00F8rer til samme vare.
       */
      var numberTailPattern =
        /^(.+?)\s+([\u2212\u2013\u2014-]?\d[\d\s.]*,\d{2})\s+(\d+(?:[.,]\d+)?)\s+(\d+(?:[.,]\d+)?)\s*%\s+([\u2212\u2013\u2014-]?\d[\d\s.]*,\d{2})$/i;

      function isTableHeader(
        line
      ) {
        return (
          /Beskrivelse/i.test(
            line
          ) &&
          /Enhetspris/i.test(
            line
          ) &&
          /Antall/i.test(
            line
          ) &&
          /Mva/i.test(
            line
          )
        );
      }

      function isStopLine(
        line
      ) {
        return (
          /^Netto\b/i.test(
            line
          ) ||
          /^Mva\b/i.test(
            line
          ) ||
          /^\u00C5 betale\b/i.test(
            line
          ) ||
          /^Alle bel\u00F8p er oppgitt/i.test(
            line
          ) ||
          /^Fortsetter p\u00E5 neste side/i.test(
            line
          ) ||
          /^DiscGolfShop AS\b/i.test(
            line
          ) ||
          /^Discgolfshop AS\b/i.test(
            line
          )
        );
      }

      function cleanDescription(
        primary,
        continuation
      ) {
        var first =
          String(
            primary || ""
          )
            .replace(
              /\s+/g,
              " "
            )
            .trim();

        var second =
          String(
            continuation || ""
          )
            .replace(
              /\s+/g,
              " "
            )
            .trim();

        /*
         * Den nederste tekstlinjen inneholder normalt det spesifikke
         * produktnavnet (f.eks. "Neutron Trail - Goliath"), mens \u00F8verste
         * linje gir MVP/Axiom/plastfamilie. Vi beholder begge for smartmatch.
         */
        if (
          first &&
          second
        ) {
          return (
            first +
            " / " +
            second
          );
        }

        return (
          second ||
          first
        );
      }

      function finishRow(
        pending
      ) {
        if (!pending) {
          return;
        }

        var description =
          cleanDescription(
            pending.primary_description,
            pending.continuation.join(
              " "
            )
          );

        if (!description) {
          return;
        }

        var quantity =
          num(
            pending.quantity
          );

        var unitPrice =
          num(
            pending.unit_price
          );

        var combinedLower =
          description.toLowerCase();

        var isShipping =
          /^frakt\b/i.test(
            pending.primary_description
          ) ||
          /\bpostnord\b/i.test(
            combinedLower
          ) ||
          /\bfrakt\b/i.test(
            combinedLower
          );

        var isRounding =
          /\u00F8reavrunding/i.test(
            combinedLower
          ) ||
          /avrunding/i.test(
            combinedLower
          ) ||
          /rounding/i.test(
            combinedLower
          );

        if (
          !Number.isFinite(
            quantity
          ) ||
          quantity <= 0 ||
          !Number.isFinite(
            unitPrice
          ) ||
          (
            unitPrice < 0 &&
            !(
              isRounding &&
              unitPrice >= -1
            )
          )
        ) {
          return;
        }

        var netLineTotal =
          unitPrice *
          quantity;

        if (
          isShipping ||
          isRounding
        ) {
          costs.push({
            cost_type:
              isShipping
                ? "shipping"
                : "other",

            description:
              description,

            amount:
              netLineTotal,

            allocation_method:
              "by_value",

            gross_amount:
              pending.gross_line_total,

            vat_percent:
              pending.vat_percent
          });

          return;
        }

        rows.push({
          line_number:
            rows.length + 1,

          /*
           * DiscGolfShop-fakturaene har ikke eget varenummer i tabellen.
           * Produktmatch skjer derfor p\u00E5 produktnavn, og bekreftede navn
           * kan gjenbrukes av smartmatcheren p\u00E5 senere fakturaer.
           */
          supplier_sku:
            null,

          ean:
            null,

          description:
            description,

          quantity:
            quantity,

          unit_price:
            unitPrice,

          line_total:
            netLineTotal,

          list_unit_price:
            unitPrice,

          discount_percent:
            0,

          gross_line_total:
            pending.gross_line_total,

          vat_percent:
            pending.vat_percent
        });
      }


      (pages || []).forEach(
        function (page) {
          var inTable = false;
          var pending = null;

          (
            page.lines || []
          ).forEach(
            function (rawLine) {
              var line =
                String(
                  rawLine || ""
                )
                  .replace(
                    /\u00a0/g,
                    " "
                  )
                  .replace(
                    /\s+/g,
                    " "
                  )
                  .trim();

              if (!line) {
                return;
              }

              if (
                isTableHeader(
                  line
                )
              ) {
                finishRow(
                  pending
                );

                pending = null;
                inTable = true;
                return;
              }

              if (!inTable) {
                return;
              }

              if (
                isStopLine(
                  line
                )
              ) {
                finishRow(
                  pending
                );

                pending = null;

                if (
                  /^Netto\b/i.test(
                    line
                  ) ||
                  /^Alle bel\u00F8p/i.test(
                    line
                  ) ||
                  /^Fortsetter p\u00E5 neste side/i.test(
                    line
                  )
                ) {
                  inTable = false;
                }

                return;
              }

              var numericRow =
                line.match(
                  numberTailPattern
                );

              if (
                numericRow
              ) {
                finishRow(
                  pending
                );

                pending = {
                  primary_description:
                    numericRow[1],

                  continuation:
                    [],

                  unit_price:
                    parseNordicNumber(
                      numericRow[2]
                    ),

                  quantity:
                    parseNordicNumber(
                      numericRow[3]
                    ),

                  vat_percent:
                    parseNordicNumber(
                      numericRow[4]
                    ),

                  gross_line_total:
                    parseNordicNumber(
                      numericRow[5]
                    )
                };

                return;
              }

              /*
               * Den andre beskrivelseslinjen kommer normalt etter tallene.
               * Ignorer kjente side-/headerlinjer som kan ligge mellom.
               */
              if (
                pending &&
                !/^FAKTURA$/i.test(
                  line
                ) &&
                !/^Forfallsdato\b/i.test(
                  line
                ) &&
                !/^Kontonr\./i.test(
                  line
                ) &&
                !/^\u00C5 betale\b/i.test(
                  line
                )
              ) {
                pending.continuation.push(
                  line
                );
              }
            }
          );

          finishRow(
            pending
          );
        }
      );


      /*
       * Fallback for PDF-er der tabellkolonnene blir sl\u00E5tt sammen annerledes:
       * finn alle tekstsekvenser som slutter med pris + antall + MVA + sum.
       */
      if (
        rows.length === 0
      ) {
        var flatText =
          fullLines.join(" ");

        var flatPattern =
          /(.+?)\s+([\u2212\u2013\u2014-]?\d[\d\s.]*,\d{2})\s+(\d+(?:[.,]\d+)?)\s+(\d+(?:[.,]\d+)?)\s*%\s+([\u2212\u2013\u2014-]?\d[\d\s.]*,\d{2})(?=\s+(?:MVP\/Axiom|Frakt\b|\u00D8reavrunding\b|Netto\b|Mva\b|\u00C5 betale\b|$))/gi;

        var flatMatch;

        while (
          (
            flatMatch =
              flatPattern.exec(
                flatText
              )
          ) !== null
        ) {
          var fallbackPrimary =
            String(
              flatMatch[1] || ""
            )
              .replace(
                /.*?Beskrivelse\s+Enhetspris\s+Antall\s+Mva\s+Sum\s+/i,
                ""
              )
              .trim();

          finishRow({
            primary_description:
              fallbackPrimary,
            continuation:
              [],
            unit_price:
              parseNordicNumber(
                flatMatch[2]
              ),
            quantity:
              parseNordicNumber(
                flatMatch[3]
              ),
            vat_percent:
              parseNordicNumber(
                flatMatch[4]
              ),
            gross_line_total:
              parseNordicNumber(
                flatMatch[5]
              )
          });
        }
      }


      var netMatch =
        fullText.match(
          /(?:^|\n)\s*Netto\s+(\d[\d\s.]*,\d{2})(?:\s|$)/im
        );

      var vatMatch =
        fullText.match(
          /(?:^|\n)\s*Mva\s+(\d[\d\s.]*,\d{2})(?:\s|$)/im
        );

      var grossMatch =
        fullText.match(
          /\u00C5 betale\s+(\d[\d\s.]*,\d{2})/i
        );

      var goodsTotal =
        rows.reduce(
          function (
            sum,
            row
          ) {
            return (
              sum +
              num(
                row.line_total
              )
            );
          },
          0
        );

      var extraTotal =
        costs.reduce(
          function (
            sum,
            cost
          ) {
            return (
              sum +
              num(
                cost.amount
              )
            );
          },
          0
        );

      var netTotal =
        netMatch
          ? parseNordicNumber(
              netMatch[1]
            )
          : null;

      var vatTotal =
        vatMatch
          ? parseNordicNumber(
              vatMatch[1]
            )
          : null;

      var grossTotal =
        grossMatch
          ? parseNordicNumber(
              grossMatch[1]
            )
          : null;

      var computedTotal =
        goodsTotal +
        extraTotal;

      var difference =
        netTotal === null
          ? null
          : Math.abs(
              computedTotal -
              netTotal
            );

      return {
        parser:
          "discgolfshop-v1",

        parser_label:
          "DiscGolfShop AS",

        supplier_hint:
          "DiscGolfShop AS",

        invoice_number:
          invoiceNoMatch[1],

        invoice_date:
          dgshopIsoDate(
            invoiceDateMatch[1]
          ),

        due_date:
          dueDateMatch
            ? dgshopIsoDate(
                dueDateMatch[1]
              )
            : "",

        currency:
          "NOK",

        rows:
          rows,

        costs:
          costs,

        goods_total:
          goodsTotal,

        shipping_total:
          extraTotal,

        invoice_total:
          netTotal,

        total_label:
          "Netto ekskl. MVA",

        vat_total:
          vatTotal,

        gross_total:
          grossTotal,

        computed_total:
          computedTotal,

        difference:
          difference,

        raw_text:
          fullText
      };
    }


    function parseOtbEuropePdf(
      pages
    ) {
      var fullLines = [];

      (pages || []).forEach(
        function (page) {
          (
            page.lines || []
          ).forEach(
            function (rawLine) {
              var clean =
                String(
                  rawLine || ""
                )
                  .replace(
                    /\u00a0/g,
                    " "
                  )
                  .replace(
                    /\s+/g,
                    " "
                  )
                  .trim();

              if (clean) {
                fullLines.push(
                  clean
                );
              }
            }
          );
        }
      );

      var fullText =
        fullLines.join("\n");

      if (
        !/OTB\s+Europe\s+AB/i.test(
          fullText
        ) &&
        !/Payment\s+information\s+for\s+OTB\s+Europe/i.test(
          fullText
        )
      ) {
        return null;
      }


      var invoiceNoMatch =
        fullText.match(
          /Invoice\s+No\.?\s*([0-9]+)/i
        );

      var invoiceDateMatch =
        fullText.match(
          /Invoice\s+date\s+(\d{4}-\d{2}-\d{2})/i
        );

      var dueDateMatch =
        fullText.match(
          /Due\s+date\s+(\d{4}-\d{2}-\d{2})/i
        );

      if (
        !invoiceNoMatch ||
        !invoiceDateMatch
      ) {
        return null;
      }


      var rows = [];
      var costs = [];


      /*
       * OTB Europe-format:
       *
       *   Designation Quantity PPU Total
       *   Big Z Luna - 170-172 grams 6,00 13,00 78,00
       *
       * Produktnavnet kan inneholde \u00E5rstall, bindestrek, gram og "Vary".
       * Derfor leser vi alltid de TRE siste tallfeltene som:
       *
       *   Quantity | PPU | Total
       *
       * og lar alt foran v\u00E6re produktbeskrivelsen.
       */
      (pages || []).forEach(
        function (page) {
          var inItems = false;

          (
            page.lines || []
          ).forEach(
            function (rawLine) {
              var line =
                String(
                  rawLine || ""
                )
                  .replace(
                    /\u00a0/g,
                    " "
                  )
                  .replace(
                    /\s+/g,
                    " "
                  )
                  .trim();

              if (!line) {
                return;
              }

              if (
                /^Designation\s+Quantity\s+PPU\s+Total$/i.test(
                  line
                )
              ) {
                inItems = true;
                return;
              }

              if (!inItems) {
                return;
              }

              if (
                /^Payment\s+information\s+for\s+OTB\s+Europe/i.test(
                  line
                ) ||
                /^Rate\b/i.test(
                  line
                ) ||
                /^Shipping\s+Excl\.\s*VAT/i.test(
                  line
                )
              ) {
                inItems = false;
                return;
              }

              var match =
                line.match(
                  /^(.+?)\s+(\d+(?:[.,]\d+)?)\s+(\d[\d\s.]*,\d{2})\s+(\d[\d\s.]*,\d{2})$/i
                );

              if (!match) {
                return;
              }

              var description =
                String(
                  match[1] || ""
                )
                  .replace(
                    /\s+/g,
                    " "
                  )
                  .trim();

              var quantity =
                parseNordicNumber(
                  match[2]
                );

              var unitPrice =
                parseNordicNumber(
                  match[3]
                );

              var lineTotal =
                parseNordicNumber(
                  match[4]
                );

              if (
                !description ||
                quantity === null ||
                quantity <= 0 ||
                unitPrice === null ||
                unitPrice < 0 ||
                lineTotal === null ||
                lineTotal < 0
              ) {
                return;
              }

              rows.push({
                line_number:
                  rows.length + 1,

                supplier_sku:
                  null,

                ean:
                  null,

                description:
                  description,

                quantity:
                  quantity,

                unit_price:
                  unitPrice,

                line_total:
                  lineTotal,

                list_unit_price:
                  unitPrice,

                discount_percent:
                  0
              });
            }
          );
        }
      );


      /*
       * Footer:
       *
       *   Shipping Excl. VAT Total DUE PAYMENT
       *   35,00 1 600,05 1 600,05 USD 1 600,05
       *
       * "Rate 9,315230" er OTBs svenske regnskapskurs, IKKE NOK-kurs.
       * Den skal derfor ikke brukes. Systemet henter i stedet historisk
       * USD/NOK fra Norges Bank p\u00E5 fakturadatoen.
       */
      var footerMatch =
        fullText.match(
          /Shipping\s+Excl\.\s*VAT\s+Total\s+DUE\s+PAYMENT\s*\n?\s*([\d\s.]+,\d{2})\s+([\d\s.]+,\d{2})\s+([\d\s.]+,\d{2})\s+USD\s+([\d\s.]+,\d{2})/i
        );


      var shippingTotal =
        footerMatch
          ? parseNordicNumber(
              footerMatch[1]
            )
          : 0;

      var invoiceTotal =
        footerMatch
          ? parseNordicNumber(
              footerMatch[2]
            )
          : null;

      var duePayment =
        footerMatch
          ? parseNordicNumber(
              footerMatch[4]
            )
          : null;


      if (
        shippingTotal !== null &&
        shippingTotal > 0
      ) {
        costs.push({
          cost_type:
            "shipping",

          description:
            "Shipping",

          amount:
            shippingTotal,

          allocation_method:
            "by_value"
        });
      }


      var goodsTotal =
        rows.reduce(
          function (
            sum,
            row
          ) {
            return (
              sum +
              num(
                row.line_total
              )
            );
          },
          0
        );


      var computedTotal =
        goodsTotal +
        (
          shippingTotal || 0
        );


      var difference =
        invoiceTotal === null
          ? null
          : Math.abs(
              computedTotal -
              invoiceTotal
            );


      return {
        parser:
          "otb-europe-v1",

        parser_label:
          "OTB Europe AB \u00B7 v1",

        supplier_hint:
          "OTB Europe AB",

        invoice_number:
          invoiceNoMatch[1],

        invoice_date:
          invoiceDateMatch[1],

        due_date:
          dueDateMatch
            ? dueDateMatch[1]
            : "",

        currency:
          "USD",

        rows:
          rows,

        costs:
          costs,

        goods_total:
          goodsTotal,

        shipping_total:
          shippingTotal || 0,

        invoice_total:
          invoiceTotal,

        total_label:
          "Excl. VAT",

        vat_total:
          0,

        gross_total:
          duePayment,

        computed_total:
          computedTotal,

        difference:
          difference,

        raw_text:
          fullText
      };
    }


    function parseSupplierPdf(
      pages
    ) {
      var parsed =
        parseLatitude64Pdf(
          pages
        );

      if (parsed) {
        return parsed;
      }

      parsed =
        parseSuneSportPdf(
          pages
        );

      if (parsed) {
        return parsed;
      }

      parsed =
        parseDiscGolfShopPdf(
          pages
        );

      if (parsed) {
        return parsed;
      }

      parsed =
        parseOtbEuropePdf(
          pages
        );

      if (parsed) {
        return parsed;
      }

      parsed =
        parseDiscFinderPdf(
          pages
        );

      if (parsed) {
        return parsed;
      }

      return {
        parser:
          "unsupported",
        parser_label:
          "Ukjent fakturaformat",
        rows: [],
        costs: [],
        raw_text:
          (pages || [])
            .map(
              function (page) {
                return (
                  page.lines || []
                ).join("\n");
              }
            )
            .join("\n\n")
      };
    }

    function findSupplierByHint(
      hint
    ) {
      var wanted =
        normalizeSupplierName(
          hint
        );

      var suppliers =
        (
          data &&
          Array.isArray(
            data.suppliers
          )
            ? data.suppliers
            : []
        ).filter(
          function (supplier) {
            return (
              supplier.is_active !==
              false
            );
          }
        );

      return (
        suppliers.find(
          function (supplier) {
            var name =
              normalizeSupplierName(
                supplier.name
              );

            return (
              name === wanted ||
              name.indexOf(
                wanted
              ) !== -1 ||
              wanted.indexOf(
                name
              ) !== -1
            );
          }
        ) || null
      );
    }

    function fxDateMinusDays(
      isoDate,
      days
    ) {
      var date =
        new Date(
          isoDate +
          "T12:00:00"
        );

      if (
        !Number.isFinite(
          date.getTime()
        )
      ) {
        return isoDate;
      }

      date.setDate(
        date.getDate() -
        Number(
          days || 0
        )
      );

      var year =
        date.getFullYear();

      var month =
        String(
          date.getMonth() + 1
        ).padStart(
          2,
          "0"
        );

      var day =
        String(
          date.getDate()
        ).padStart(
          2,
          "0"
        );

      return (
        year +
        "-" +
        month +
        "-" +
        day
      );
    }

    function parseNorgesBankCsvNumber(
      value
    ) {
      var clean =
        String(
          value === null ||
          value === undefined
            ? ""
            : value
        )
          .replace(
            /\u00a0/g,
            ""
          )
          .replace(
            /\s+/g,
            ""
          )
          .trim();

      if (!clean) {
        return null;
      }

      /*
       * API-et kan bruke komma eller punktum avhengig av locale/format.
       */
      if (
        clean.indexOf(",") >= 0 &&
        clean.indexOf(".") >= 0
      ) {
        if (
          clean.lastIndexOf(",") >
          clean.lastIndexOf(".")
        ) {
          clean =
            clean
              .replace(
                /\./g,
                ""
              )
              .replace(
                ",",
                "."
              );
        } else {
          clean =
            clean.replace(
              /,/g,
              ""
            );
        }
      } else {
        clean =
          clean.replace(
            ",",
            "."
          );
      }

      var parsed =
        Number(
          clean
        );

      return Number.isFinite(
        parsed
      )
        ? parsed
        : null;
    }

    function parseSemicolonCsv(
      textValue
    ) {
      var lines =
        String(
          textValue || ""
        )
          .replace(
            /^\uFEFF/,
            ""
          )
          .split(
            /\r?\n/
          )
          .filter(
            function (line) {
              return (
                String(
                  line || ""
                ).trim() !==
                ""
              );
            }
          );

      if (!lines.length) {
        return [];
      }

      function parseLine(
        line
      ) {
        var result = [];
        var current = "";
        var quoted = false;

        for (
          var i = 0;
          i < line.length;
          i += 1
        ) {
          var char =
            line[i];

          if (char === '"') {
            if (
              quoted &&
              line[
                i + 1
              ] === '"'
            ) {
              current += '"';
              i += 1;
            } else {
              quoted =
                !quoted;
            }

            continue;
          }

          if (
            char === ";" &&
            !quoted
          ) {
            result.push(
              current
            );
            current = "";
            continue;
          }

          current += char;
        }

        result.push(
          current
        );

        return result;
      }

      var headers =
        parseLine(
          lines[0]
        ).map(
          function (header) {
            return String(
              header || ""
            ).trim();
          }
        );

      return lines
        .slice(1)
        .map(
          function (line) {
            var values =
              parseLine(
                line
              );

            var row = {};

            headers.forEach(
              function (
                header,
                index
              ) {
                row[header] =
                  values[index] !==
                  undefined
                    ? values[index]
                    : "";
              }
            );

            return row;
          }
        );
    }

    function fetchNorgesBankFxRate(
      currency,
      invoiceDate
    ) {
      var code =
        String(
          currency || ""
        )
          .trim()
          .toUpperCase();

      if (
        !code ||
        !invoiceDate
      ) {
        return Promise.resolve(
          null
        );
      }

      if (code === "NOK") {
        return Promise.resolve({
          rate: 1,
          rate_date:
            invoiceDate,
          source:
            "NOK",
          source_reference:
            null
        });
      }

      var startDate =
        fxDateMinusDays(
          invoiceDate,
          7
        );

      var series =
        "B." +
        encodeURIComponent(
          code
        ) +
        ".NOK.SP";

      var url =
        "https://data.norges-bank.no/api/data/EXR/" +
        series +
        "?format=csv" +
        "&startPeriod=" +
        encodeURIComponent(
          startDate
        ) +
        "&endPeriod=" +
        encodeURIComponent(
          invoiceDate
        ) +
        "&locale=en" +
        "&bom=exclude";

      return fetch(
        url,
        {
          method: "GET",
          headers: {
            Accept:
              "text/csv,text/plain;q=0.9,*/*;q=0.8"
          },
          cache: "no-store"
        }
      )
        .then(
          function (
            response
          ) {
            if (!response.ok) {
              throw new Error(
                "Norges Bank svarte HTTP " +
                String(
                  response.status
                )
              );
            }

            return response.text();
          }
        )
        .then(
          function (
            csvText
          ) {
            var rows =
              parseSemicolonCsv(
                csvText
              );

            var matches =
              rows
                .filter(
                  function (
                    row
                  ) {
                    return (
                      String(
                        row.BASE_CUR ||
                        ""
                      )
                        .trim()
                        .toUpperCase() ===
                        code &&
                      String(
                        row.QUOTE_CUR ||
                        ""
                      )
                        .trim()
                        .toUpperCase() ===
                        "NOK" &&
                      String(
                        row.TIME_PERIOD ||
                        ""
                      ).trim() <=
                        invoiceDate
                    );
                  }
                )
                .map(
                  function (
                    row
                  ) {
                    var observed =
                      parseNorgesBankCsvNumber(
                        row.OBS_VALUE
                      );

                    var unitMult =
                      parseNorgesBankCsvNumber(
                        row.UNIT_MULT
                      );

                    if (
                      observed ===
                      null
                    ) {
                      return null;
                    }

                    if (
                      unitMult ===
                      null
                    ) {
                      unitMult = 0;
                    }

                    var scale =
                      Math.pow(
                        10,
                        unitMult
                      );

                    if (
                      !Number.isFinite(
                        scale
                      ) ||
                      scale <= 0
                    ) {
                      return null;
                    }

                    return {
                      rate:
                        observed /
                        scale,
                      rate_date:
                        String(
                          row.TIME_PERIOD ||
                          ""
                        ).trim(),
                      source:
                        "Norges Bank \u2013 daglig valutakurs",
                      source_reference:
                        "EXR/B." +
                        code +
                        ".NOK.SP"
                    };
                  }
                )
                .filter(
                  function (
                    row
                  ) {
                    return (
                      row &&
                      row.rate_date &&
                      Number.isFinite(
                        row.rate
                      ) &&
                      row.rate > 0
                    );
                  }
                )
                .sort(
                  function (
                    a,
                    b
                  ) {
                    return String(
                      b.rate_date
                    ).localeCompare(
                      String(
                        a.rate_date
                      )
                    );
                  }
                );

            var found =
              matches[0] ||
              null;

            if (!found) {
              return null;
            }

            /*
             * Lagre kursen i v\u00E5r egen historikk s\u00E5 neste faktura p\u00E5 samme
             * dato slipper nytt API-kall. Hvis RLS eller nettverk skulle
             * stoppe lagringen, brukes kursen fortsatt i denne importen.
             */
            return sb
              .from(
                "internal_fx_rates"
              )
              .upsert(
                {
                  currency_code:
                    code,
                  rate_date:
                    found.rate_date,
                  nok_per_unit:
                    found.rate,
                  source_label:
                    found.source,
                  source_reference:
                    found.source_reference
                },
                {
                  onConflict:
                    "currency_code,rate_date"
                }
              )
              .then(
                function (
                  saveResult
                ) {
                  if (
                    saveResult.error
                  ) {
                    console.warn(
                      "Kunne ikke cache Norges Bank-kurs:",
                      saveResult.error
                    );
                  }

                  return found;
                }
              )
              .catch(
                function () {
                  return found;
                }
              );
          }
        );
    }

    function safeKnownFxRate(
      currency,
      invoiceDate
    ) {
      if (
        !currency ||
        !invoiceDate
      ) {
        return Promise.resolve(
          null
        );
      }

      var code =
        String(
          currency
        )
          .trim()
          .toUpperCase();

      if (code === "NOK") {
        return Promise.resolve({
          rate: 1,
          rate_date:
            invoiceDate,
          source: "NOK",
          source_reference:
            null
        });
      }

      /*
       * 1) Pr\u00F8v f\u00F8rst v\u00E5r egen valutahistorikk.
       *
       * Tabellen bruker source_label/source_reference. Tidligere frontend
       * spurte feilaktig etter kolonnen "source", som ikke finnes.
       */
      return sb
        .from(
          "internal_fx_rates"
        )
        .select(
          "currency_code,rate_date,nok_per_unit,source_label,source_reference"
        )
        .eq(
          "currency_code",
          code
        )
        .lte(
          "rate_date",
          invoiceDate
        )
        .order(
          "rate_date",
          { ascending: false }
        )
        .limit(1)
        .then(
          function (result) {
            if (result.error) {
              throw result.error;
            }

            var row =
              result.data &&
              result.data[0]
                ? result.data[0]
                : null;

            if (row) {
              var invoiceMs =
                new Date(
                  invoiceDate +
                  "T12:00:00"
                ).getTime();

              var rateMs =
                new Date(
                  row.rate_date +
                  "T12:00:00"
                ).getTime();

              var dayDiff =
                Math.round(
                  (
                    invoiceMs -
                    rateMs
                  ) /
                  86400000
                );

              /*
               * Maks 7 dager dekker helg/helligdag, men hindrer at en gammel
               * lagret kurs brukes p\u00E5 en ny fakturadato.
               */
              if (
                dayDiff >= 0 &&
                dayDiff <= 7
              ) {
                return {
                  rate:
                    num(
                      row.nok_per_unit
                    ),
                  rate_date:
                    row.rate_date,
                  source:
                    row.source_label ||
                    "Norges Bank",
                  source_reference:
                    row.source_reference ||
                    null
                };
              }
            }

            /*
             * 2) Mangler kursen lokalt: hent automatisk fra Norges Banks
             * \u00E5pne API. Ved helg/helligdag brukes seneste publiserte kurs
             * opptil 7 dager f\u00F8r fakturadatoen.
             */
            return fetchNorgesBankFxRate(
              code,
              invoiceDate
            );
          }
        )
        .catch(
          function (
            localError
          ) {
            console.warn(
              "Lokal valutakursoppslag feilet, pr\u00F8ver Norges Bank direkte:",
              localError
            );

            return fetchNorgesBankFxRate(
              code,
              invoiceDate
            );
          }
        );
    }

    function shipmentDateDistanceDays(
      a,
      b
    ) {
      if (!a || !b) {
        return 9999;
      }

      var aMs =
        new Date(
          a + "T12:00:00"
        ).getTime();

      var bMs =
        new Date(
          b + "T12:00:00"
        ).getTime();

      if (
        !Number.isFinite(aMs) ||
        !Number.isFinite(bMs)
      ) {
        return 9999;
      }

      return Math.abs(
        Math.round(
          (aMs - bMs) /
          86400000
        )
      );
    }

    function shipmentCandidatesForImport(
      supplierName,
      invoiceDateValue,
      invoiceNumberValue
    ) {
      var normalizedSupplier =
        normalizeSupplierName(
          supplierName
        );

      return (
        state.summaries || []
      )
        .filter(
          function (summary) {
            if (
              normalizeSupplierName(
                summary.supplier_name
              ) !==
              normalizedSupplier
            ) {
              return false;
            }

            if (
              String(
                summary.invoice_number ||
                ""
              ).trim() ===
              String(
                invoiceNumberValue ||
                ""
              ).trim()
            ) {
              return false;
            }

            return (
              shipmentDateDistanceDays(
                summary.invoice_date,
                invoiceDateValue
              ) <= 7
            );
          }
        )
        .sort(
          function (a, b) {
            var aDiff =
              shipmentDateDistanceDays(
                a.invoice_date,
                invoiceDateValue
              );

            var bDiff =
              shipmentDateDistanceDays(
                b.invoice_date,
                invoiceDateValue
              );

            if (aDiff !== bDiff) {
              return aDiff - bDiff;
            }

            return String(
              b.invoice_date || ""
            ).localeCompare(
              String(
                a.invoice_date || ""
              )
            );
          }
        );
    }

    function createSharedShipmentAfterImport(
      options
    ) {
      var invoiceIds =
        (
          options.existingInvoiceIds ||
          []
        ).slice();

      var invoiceNumbers =
        (
          options.existingInvoiceNumbers ||
          []
        ).slice();

      var referenceParts =
        [
          options.currentInvoiceNumber
        ].concat(
          invoiceNumbers
        );

      var shipmentReference =
        (
          options.supplierName +
          " \u00B7 " +
          options.invoiceDate +
          " \u00B7 " +
          referenceParts.join(" + ")
        ).slice(
          0,
          240
        );

      return sb.rpc(
        "internal_supplier_shipment_create",
        {
          p_supplier_id:
            options.supplierId,
          p_reference:
            shipmentReference,
          p_shipment_date:
            options.invoiceDate,
          p_notes:
            "Felles forsendelse opprettet fra PDF-import. Frakt/tillegg stod p\u00E5 faktura " +
            options.currentInvoiceNumber +
            "."
        }
      )
        .then(
          function (createResult) {
            if (createResult.error) {
              throw createResult.error;
            }

            var shipment =
              createResult.data &&
              createResult.data[0]
                ? createResult.data[0]
                : null;

            if (
              !shipment ||
              !shipment.shipment_id
            ) {
              throw new Error(
                "Forsendelsen ble ikke opprettet."
              );
            }

            var shipmentId =
              shipment.shipment_id;

            var links =
              [
                options.currentInvoiceId
              ].concat(
                invoiceIds
              );

            return Promise.all(
              links.map(
                function (invoiceId) {
                  return sb.rpc(
                    "internal_supplier_shipment_link_invoice",
                    {
                      p_shipment_id:
                        shipmentId,
                      p_invoice_id:
                        invoiceId
                    }
                  ).then(
                    function (result) {
                      if (result.error) {
                        throw result.error;
                      }

                      return result.data;
                    }
                  );
                }
              )
            ).then(
              function () {
                var costs =
                  options.costs || [];

                return Promise.all(
                  costs.map(
                    function (cost) {
                      return sb.rpc(
                        "internal_supplier_shipment_add_cost",
                        {
                          p_shipment_id:
                            shipmentId,
                          p_source_invoice_id:
                            options.currentInvoiceId,
                          p_cost_type:
                            cost.cost_type ||
                            "shipping",
                          p_description:
                            cost.description ||
                            "Frakt",
                          p_amount_ex_vat_currency:
                            cost.amount,
                          p_currency:
                            options.currency,
                          p_exchange_rate_to_nok:
                            options.currency ===
                            "NOK"
                              ? 1
                              : options.rate,
                          p_exchange_rate_date:
                            options.rateDate ||
                            options.invoiceDate,
                          p_exchange_rate_source:
                            options.rateSource ||
                            (
                              options.currency ===
                              "NOK"
                                ? "NOK"
                                : "Manuell ved PDF-import"
                            ),
                          p_exchange_rate_reference:
                            null,
                          p_allocation_method:
                            cost.allocation_method ||
                            "by_value"
                        }
                      ).then(
                        function (result) {
                          if (result.error) {
                            throw result.error;
                          }

                          return result.data;
                        }
                      );
                    }
                  )
                ).then(
                  function () {
                    return {
                      shipment_id:
                        shipmentId,
                      shipment_reference:
                        shipment.shipment_reference,
                      linked_invoice_count:
                        links.length
                    };
                  }
                );
              }
            );
          }
        );
    }

    function refreshSharedShipmentForInvoice(
      invoiceId
    ) {
      return sb
        .from(
          "internal_supplier_shipment_invoices"
        )
        .select(
          "shipment_id"
        )
        .eq(
          "invoice_id",
          invoiceId
        )
        .limit(1)
        .then(
          function (result) {
            if (result.error) {
              throw result.error;
            }

            var link =
              result.data &&
              result.data[0]
                ? result.data[0]
                : null;

            if (
              !link ||
              !link.shipment_id
            ) {
              return {
                linked: false,
                refreshed_invoices: 0,
                skipped_invoices: 0
              };
            }

            return sb.rpc(
              "internal_supplier_shipment_refresh_costed",
              {
                p_shipment_id:
                  link.shipment_id
              }
            ).then(
              function (
                refreshResult
              ) {
                if (
                  refreshResult.error
                ) {
                  throw refreshResult.error;
                }

                var row =
                  refreshResult.data &&
                  refreshResult.data[0]
                    ? refreshResult.data[0]
                    : {};

                return {
                  linked: true,
                  shipment_id:
                    link.shipment_id,
                  refreshed_invoices:
                    Number(
                      row.refreshed_invoices ||
                      0
                    ),
                  skipped_invoices:
                    Number(
                      row.skipped_invoices ||
                      0
                    )
                };
              }
            );
          }
        );
    }


    function renderPdfImport(
      file,
      parsed
    ) {
      clear(right);

      var section =
        el("div");

      section.className =
        "sk-invoice-section";

      section.appendChild(
        el(
          "h3",
          "\uD83D\uDCC4 Ny faktura fra PDF"
        )
      );

      var intro =
        el(
          "div",
          "Kontroller at leverand\u00F8r, fakturanummer, dato, valuta, varelinjer og frakt ser riktig ut. Velg \u00ABFelles forsendelse\u00BB bare n\u00E5r flere fakturaer faktisk kom i samme levering."
        );

      intro.className =
        "sk-invoice-section-sub";
      section.appendChild(
        intro
      );

      if (
        parsed.parser ===
        "unsupported"
      ) {
        var unsupported =
          el(
            "div",
            "Dette PDF-formatet st\u00F8ttes ikke automatisk enn\u00E5. Ingenting er importert."
          );

        unsupported.className =
          "sk-invoice-import-status sk-bad";
        section.appendChild(
          unsupported
        );

        var fileMeta =
          el(
            "div",
            "Fil: " +
              file.name
          );

        fileMeta.className =
          "sk-invoice-small";
        section.appendChild(
          fileMeta
        );

        var back =
          createButton(
            "Tilbake til fakturaer"
          );

        back.style.marginTop =
          "10px";

        back.onclick =
          function () {
            if (
              state.selectedInvoiceId
            ) {
              loadInvoiceDetails(
                state.selectedInvoiceId
              );
            } else {
              refreshAll(null);
            }
          };

        section.appendChild(
          back
        );

        right.appendChild(
          section
        );
        return;
      }

      var supplier =
        findSupplierByHint(
          parsed.supplier_hint
        );

      var suppliers =
        (
          data &&
          Array.isArray(
            data.suppliers
          )
            ? data.suppliers
            : []
        )
          .filter(
            function (item) {
              return (
                item.is_active !==
                false
              );
            }
          )
          .slice()
          .sort(
            function (a, b) {
              return String(
                a.name || ""
              ).localeCompare(
                String(
                  b.name || ""
                ),
                "nb"
              );
            }
          );

      var fields =
        el("div");

      fields.className =
        "sk-invoice-import-grid";

      function makeField(
        labelText,
        control
      ) {
        var label =
          el("label");

        label.appendChild(
          el(
            "span",
            labelText
          )
        );

        label.appendChild(
          control
        );

        fields.appendChild(
          label
        );
      }

      var supplierSelect =
        el("select");

      var emptyOption =
        el(
          "option",
          "Velg leverand\u00F8r"
        );
      emptyOption.value = "";
      supplierSelect.appendChild(
        emptyOption
      );

      suppliers.forEach(
        function (item) {
          var option =
            el(
              "option",
              item.name
            );

          var supplierId =
            item.supplier_id ||
            item.id ||
            "";

          option.value =
            supplierId;

          if (
            supplier &&
            (
              supplier.supplier_id ||
              supplier.id
            ) ===
              supplierId
          ) {
            option.selected =
              true;
          }

          supplierSelect.appendChild(
            option
          );
        }
      );

      makeField(
        "Leverand\u00F8r",
        supplierSelect
      );

      var invoiceNo =
        el("input");
      invoiceNo.type = "text";
      invoiceNo.value =
        parsed.invoice_number ||
        "";
      makeField(
        "Fakturanummer",
        invoiceNo
      );

      var invoiceDate =
        el("input");
      invoiceDate.type = "date";
      invoiceDate.value =
        parsed.invoice_date ||
        "";
      makeField(
        "Fakturadato",
        invoiceDate
      );

      var dueDate =
        el("input");
      dueDate.type = "date";
      dueDate.value =
        parsed.due_date ||
        "";
      makeField(
        "Forfallsdato",
        dueDate
      );

      var currency =
        el("input");
      currency.type = "text";
      currency.maxLength = 3;
      currency.value =
        parsed.currency ||
        "";
      makeField(
        "Valuta",
        currency
      );

      var fxRate =
        el("input");
      fxRate.type = "number";
      fxRate.step = "0.000001";
      fxRate.min = "0";
      fxRate.placeholder =
        "NOK per 1 valuta";
      makeField(
        "Valutakurs til NOK",
        fxRate
      );

      section.appendChild(
        fields
      );

      var fxInfo =
        el(
          "div",
          "Sjekker kjent valutakurs\u2026"
        );

      fxInfo.className =
        "sk-invoice-small";
      fxInfo.style.marginTop =
        "7px";

      section.appendChild(
        fxInfo
      );

      var fxMeta = {
        rate_date: null,
        source: null
      };

      function refreshKnownFx() {
        var code =
          String(
            currency.value || ""
          )
            .trim()
            .toUpperCase();

        var date =
          invoiceDate.value;

        fxInfo.textContent =
          "Sjekker kjent valutakurs\u2026";

        safeKnownFxRate(
          code,
          date
        )
          .then(
            function (known) {
              if (known) {
                fxRate.value =
                  String(
                    known.rate
                  );

                fxMeta.rate_date =
                  known.rate_date;

                fxMeta.source =
                  known.source;

                fxInfo.textContent =
                  "Valutakurs funnet: " +
                  fmtNumber(
                    known.rate,
                    4
                  ) +
                  " NOK/" +
                  code +
                  " \u00B7 " +
                  fmtDate(
                    known.rate_date
                  ) +
                  " \u00B7 " +
                  String(
                    known.source ||
                    "Norges Bank"
                  );
              } else {
                fxMeta.rate_date =
                  null;
                fxMeta.source =
                  null;

                if (code === "NOK") {
                  fxRate.value = "1";
                  fxInfo.textContent =
                    "NOK-faktura: kurs 1,0000.";
                } else {
                  fxRate.value = "";
                  fxInfo.textContent =
                    "Fant ikke valutakurs automatisk hos Norges Bank. Du kan skrive inn NOK per 1 " +
                    code +
                    " f\u00F8r import.";
                }
              }
            }
          )
          .catch(
            function (error) {
              fxMeta.rate_date =
                null;
              fxMeta.source =
                null;

              fxInfo.textContent =
                "Kunne ikke hente valutakurs automatisk: " +
                skReadableError(
                  error &&
                  error.message
                    ? error.message
                    : error
                );
            }
          );
      }

      currency.onchange =
        refreshKnownFx;
      invoiceDate.onchange =
        refreshKnownFx;

      refreshKnownFx();

      var summaryCards =
        el("div");

      summaryCards.className =
        "sk-invoice-import-summary";

      addSummaryCard(
        summaryCards,
        "Parser",
        parsed.parser_label
      );

      addSummaryCard(
        summaryCards,
        "Varelinjer",
        parsed.rows.length
      );

      addSummaryCard(
        summaryCards,
        "Varer",
        fmtCurrency(
          parsed.goods_total,
          parsed.currency
        )
      );

      addSummaryCard(
        summaryCards,
        "Frakt/tillegg",
        fmtCurrency(
          parsed.shipping_total,
          parsed.currency
        )
      );

      addSummaryCard(
        summaryCards,
        parsed.total_label ||
          "Fakturatotal",
        fmtCurrency(
          parsed.invoice_total,
          parsed.currency
        )
      );

      section.appendChild(
        summaryCards
      );

      var validationOk =
        parsed.rows.length > 0 &&
        (
          parsed.difference ===
            null ||
          parsed.difference <=
            0.05
        );

      var validation =
        el(
          "div",
          validationOk
            ? (
                "Kontroll OK: parseren fant " +
                String(
                  parsed.rows.length
                ) +
                " varelinjer. Beregnet kostgrunnlag = " +
                fmtCurrency(
                  parsed.computed_total,
                  parsed.currency
                ) +
                (
                  parsed.invoice_total !==
                  null
                    ? ", som matcher " +
                      String(
                        parsed.total_label ||
                        "fakturatotalen"
                      ).toLowerCase() +
                      "."
                    : "."
                )
              )
            : (
                "Import stoppet: beregnet total matcher ikke fakturaen. Avvik " +
                fmtCurrency(
                  parsed.difference,
                  parsed.currency
                ) +
                "."
              )
        );

      validation.className =
        "sk-invoice-import-status " +
        (
          validationOk
            ? "sk-ok"
            : "sk-bad"
        );

      section.appendChild(
        validation
      );

      if (
        parsed.vat_total !==
          undefined &&
        parsed.vat_total !== null
      ) {
        var vatNote =
          el(
            "div",
            "MVA holdes utenfor reell innkj\u00F8pskost. Fakturaen viser " +
              fmtCurrency(
                parsed.vat_total,
                parsed.currency
              ) +
              " i MVA" +
              (
                parsed.gross_total !==
                  undefined &&
                parsed.gross_total !==
                  null
                  ? " og " +
                    fmtCurrency(
                      parsed.gross_total,
                      parsed.currency
                    ) +
                    " \u00E5 betale."
                  : "."
              )
          );

        vatNote.className =
          "sk-invoice-small";
        vatNote.style.marginTop =
          "7px";

        section.appendChild(
          vatNote
        );
      }

      var shipmentDecision = {
        mode: "local",
        selectedInvoiceIds: {},
        selectedInvoiceNumbers: {}
      };

      var shipmentBox =
        el("div");

      function selectedSupplierName() {
        var option =
          supplierSelect.options[
            supplierSelect.selectedIndex
          ];

        return option
          ? String(
              option.textContent ||
              ""
            ).trim()
          : "";
      }

      function renderShipmentChoice() {
        clear(
          shipmentBox
        );

        if (
          !parsed.costs ||
          !parsed.costs.length ||
          num(
            parsed.shipping_total
          ) <= 0
        ) {
          shipmentBox.style.display =
            "none";
          return;
        }

        shipmentBox.style.display =
          "grid";
        shipmentBox.className =
          "sk-shipment-box";

        shipmentBox.appendChild(
          el(
            "div",
            "\uD83D\uDE9A Frakt / felles forsendelse"
          )
        ).className =
          "sk-shipment-title";

        shipmentBox.appendChild(
          el(
            "div",
            "PDF-en har " +
              fmtCurrency(
                parsed.shipping_total,
                parsed.currency
              ) +
              " i frakt/tillegg. Velg om kostnaden gjelder bare denne fakturaen eller flere fakturaer som ble sendt samlet."
          )
        ).className =
          "sk-invoice-small";

        var candidates =
          shipmentCandidatesForImport(
            selectedSupplierName(),
            invoiceDate.value,
            invoiceNo.value
          );

        var localLabel =
          el("label");
        localLabel.className =
          "sk-shipment-option";

        var localRadio =
          el("input");
        localRadio.type =
          "radio";
        localRadio.name =
          "sk-freight-mode";
        localRadio.value =
          "local";
        localRadio.checked =
          shipmentDecision.mode ===
          "local";

        var localText =
          el("div");

        localText.appendChild(
          el(
            "div",
            "Kun denne fakturaen"
          )
        ).style.fontWeight =
          "900";

        localText.appendChild(
          el(
            "div",
            "Hele frakten fordeles bare p\u00E5 varelinjene i faktura " +
              (
                invoiceNo.value ||
                "denne fakturaen"
              ) +
              "."
          )
        ).className =
          "sk-invoice-small";

        localLabel.appendChild(
          localRadio
        );
        localLabel.appendChild(
          localText
        );

        shipmentBox.appendChild(
          localLabel
        );

        var sharedLabel =
          el("label");
        sharedLabel.className =
          "sk-shipment-option";

        var sharedRadio =
          el("input");
        sharedRadio.type =
          "radio";
        sharedRadio.name =
          "sk-freight-mode";
        sharedRadio.value =
          "shared";
        sharedRadio.checked =
          shipmentDecision.mode ===
          "shared";

        var sharedText =
          el("div");

        sharedText.appendChild(
          el(
            "div",
            "Felles forsendelse"
          )
        ).style.fontWeight =
          "900";

        sharedText.appendChild(
          el(
            "div",
            "Frakten fordeles etter vareverdi p\u00E5 alle valgte fakturaer i samme fysiske levering."
          )
        ).className =
          "sk-invoice-small";

        sharedLabel.appendChild(
          sharedRadio
        );
        sharedLabel.appendChild(
          sharedText
        );

        shipmentBox.appendChild(
          sharedLabel
        );

        var candidatesWrap =
          el("div");
        candidatesWrap.className =
          "sk-shipment-candidates";

        if (candidates.length) {
          var sameDay =
            candidates.filter(
              function (
                candidate
              ) {
                return (
                  shipmentDateDistanceDays(
                    candidate.invoice_date,
                    invoiceDate.value
                  ) === 0
                );
              }
            );

          var hint =
            el(
              "div",
              sameDay.length
                ? (
                    "Mulig felles levering funnet samme dato: " +
                    sameDay
                      .map(
                        function (
                          candidate
                        ) {
                          return candidate.invoice_number;
                        }
                      )
                      .join(", ")
                  )
                : "Velg fakturaene som faktisk kom i samme levering."
            );

          hint.className =
            "sk-shipment-hint";
          candidatesWrap.appendChild(
            hint
          );

          candidates.forEach(
            function (
              candidate
            ) {
              var candidateLabel =
                el("label");
              candidateLabel.className =
                "sk-shipment-candidate";

              var checkbox =
                el("input");
              checkbox.type =
                "checkbox";
              checkbox.checked =
                !!shipmentDecision
                  .selectedInvoiceIds[
                    candidate.invoice_id
                  ];

              checkbox.disabled =
                shipmentDecision.mode !==
                "shared";

              checkbox.onchange =
                function () {
                  if (
                    checkbox.checked
                  ) {
                    shipmentDecision
                      .selectedInvoiceIds[
                        candidate.invoice_id
                      ] = true;

                    shipmentDecision
                      .selectedInvoiceNumbers[
                        candidate.invoice_id
                      ] =
                        candidate.invoice_number;
                  } else {
                    delete shipmentDecision
                      .selectedInvoiceIds[
                        candidate.invoice_id
                      ];

                    delete shipmentDecision
                      .selectedInvoiceNumbers[
                        candidate.invoice_id
                      ];
                  }
                };

              var candidateText =
                el(
                  "span",
                  String(
                    candidate.invoice_number
                  ) +
                    " \u00B7 " +
                    fmtDate(
                      candidate.invoice_date
                    ) +
                    " \u00B7 " +
                    (
                      candidate.status ===
                      "costed"
                        ? "kostpris lagret"
                        : "til kontroll"
                    )
                );

              candidateLabel.appendChild(
                checkbox
              );
              candidateLabel.appendChild(
                candidateText
              );

              candidatesWrap.appendChild(
                candidateLabel
              );
            }
          );
        } else {
          candidatesWrap.appendChild(
            el(
              "div",
              "Ingen tidligere faktura fra samme leverand\u00F8r de siste 7 dagene er tilgjengelig \u00E5 koble til."
            )
          ).className =
            "sk-invoice-small";
        }

        shipmentBox.appendChild(
          candidatesWrap
        );

        localRadio.onchange =
          function () {
            shipmentDecision.mode =
              "local";

            renderShipmentChoice();
          };

        sharedRadio.onchange =
          function () {
            shipmentDecision.mode =
              "shared";

            renderShipmentChoice();
          };
      }

      renderShipmentChoice();

      supplierSelect.addEventListener(
        "change",
        renderShipmentChoice
      );

      invoiceDate.addEventListener(
        "change",
        renderShipmentChoice
      );

      invoiceNo.addEventListener(
        "input",
        renderShipmentChoice
      );

      section.appendChild(
        shipmentBox
      );

      var rowSection =
        createCollapsibleSection(
          "Varelinjer \u00B7 " +
            String(
              parsed.rows.length
            ),
          "Kontroller at varelinjene ser riktige ut f\u00F8r import.",
          false
        );

      var wrap =
        el("div");
      wrap.className =
        "sk-invoice-preview-wrap";

      var table =
        el("table");
      table.className =
        "sk-invoice-preview-table";

      var thead =
        el("thead");
      var trh =
        el("tr");

      [
        "#",
        "Beskrivelse",
        "Varenr.",
        "EAN",
        "Ant.",
        "Pris/stk netto",
        "Rabatt",
        "Linjesum"
      ].forEach(
        function (label) {
          trh.appendChild(
            el("th", label)
          );
        }
      );

      thead.appendChild(
        trh
      );
      table.appendChild(
        thead
      );

      var tbody =
        el("tbody");

      parsed.rows.forEach(
        function (row) {
          var tr =
            el("tr");

          [
            row.line_number,
            row.description,
            row.supplier_sku ||
              "\u2013",
            row.ean || "\u2013",
            fmtNumber(
              row.quantity,
              0
            ),
            fmtCurrency(
              row.unit_price,
              parsed.currency
            ),
            row.discount_percent !==
              undefined
              ? (
                  fmtNumber(
                    row.discount_percent,
                    0
                  ) + "%"
                )
              : "\u2013",
            fmtCurrency(
              row.line_total,
              parsed.currency
            )
          ].forEach(
            function (
              value,
              index
            ) {
              var td =
                el(
                  "td",
                  String(value)
                );

              if (
                index >= 4
              ) {
                td.className =
                  "sk-num";
              }

              tr.appendChild(
                td
              );
            }
          );

          tbody.appendChild(
            tr
          );
        }
      );

      table.appendChild(
        tbody
      );
      wrap.appendChild(
        table
      );
      rowSection.body.appendChild(
        wrap
      );
      section.appendChild(
        rowSection.wrap
      );

      var actions =
        el("div");
      actions.className =
        "sk-invoice-actions";

      var importBtn =
        createPrimaryButton(
          "Importer faktura til kontroll"
        );

      importBtn.disabled =
        !validationOk;

      importBtn.onclick =
        function () {
          var supplierId =
            supplierSelect.value;

          var code =
            String(
              currency.value || ""
            )
              .trim()
              .toUpperCase();

          var rate =
            maybeNum(
              fxRate.value
            );

          if (!supplierId) {
            alert(
              "Velg leverand\u00F8r."
            );
            return;
          }

          if (
            !invoiceNo.value.trim()
          ) {
            alert(
              "Fakturanummer mangler."
            );
            return;
          }

          if (
            !invoiceDate.value
          ) {
            alert(
              "Fakturadato mangler."
            );
            return;
          }

          if (
            !/^[A-Z]{3}$/.test(
              code
            )
          ) {
            alert(
              "Valuta m\u00E5 v\u00E6re en trebokstavskode, for eksempel SEK eller EUR."
            );
            return;
          }

          if (
            code !== "NOK" &&
            (
              rate === null ||
              rate <= 0
            )
          ) {
            alert(
              "Legg inn riktig valutakurs til NOK f\u00F8r import."
            );
            return;
          }

          var sharedInvoiceIds =
            Object.keys(
              shipmentDecision
                .selectedInvoiceIds
            ).filter(
              function (
                invoiceId
              ) {
                return !!shipmentDecision
                  .selectedInvoiceIds[
                    invoiceId
                  ];
              }
            );

          var sharedInvoiceNumbers =
            sharedInvoiceIds.map(
              function (
                invoiceId
              ) {
                return shipmentDecision
                  .selectedInvoiceNumbers[
                    invoiceId
                  ];
              }
            );

          if (
            shipmentDecision.mode ===
              "shared" &&
            parsed.costs &&
            parsed.costs.length &&
            sharedInvoiceIds.length === 0
          ) {
            alert(
              "Velg minst \u00E9n annen faktura som tilh\u00F8rer samme fysiske forsendelse."
            );
            return;
          }

          var freightMessage =
            parsed.costs &&
            parsed.costs.length
              ? (
                  shipmentDecision.mode ===
                  "shared"
                    ? (
                        " Frakt/tillegg " +
                        fmtCurrency(
                          parsed.shipping_total,
                          code
                        ) +
                        " blir fordelt over faktura " +
                        invoiceNo.value.trim() +
                        " + " +
                        sharedInvoiceNumbers.join(
                          ", "
                        ) +
                        "."
                      )
                    : (
                        " Frakt/tillegg " +
                        fmtCurrency(
                          parsed.shipping_total,
                          code
                        ) +
                        " blir fordelt kun p\u00E5 denne fakturaen."
                      )
                )
              : "";

          if (
            !window.confirm(
              "Importere faktura " +
                invoiceNo.value.trim() +
                " med " +
                String(
                  parsed.rows.length
                ) +
                " varelinjer?" +
                freightMessage +
                " Lagerantall endres ikke."
            )
          ) {
            return;
          }

          importBtn.disabled =
            true;
          importBtn.textContent =
            "Importerer\u2026";

          var costRows =
            shipmentDecision.mode ===
              "shared"
              ? []
              : parsed.costs.map(
                  function (cost) {
                    return {
                      cost_type:
                        cost.cost_type,
                      description:
                        cost.description,
                      amount:
                        cost.amount,
                      currency:
                        code,
                      exchange_rate_to_nok:
                        code === "NOK"
                          ? 1
                          : rate,
                      exchange_rate_date:
                        fxMeta.rate_date ||
                        invoiceDate.value,
                      exchange_rate_source:
                        fxMeta.source ||
                        (
                          code === "NOK"
                            ? "NOK"
                            : "Manuell ved PDF-import"
                        ),
                      allocation_method:
                        cost.allocation_method ||
                        "by_value"
                    };
                  }
                );

          sb.rpc(
            "internal_supplier_invoice_import_create",
            {
              p_supplier_id:
                supplierId,
              p_invoice_number:
                invoiceNo.value.trim(),
              p_invoice_date:
                invoiceDate.value,
              p_due_date:
                dueDate.value ||
                null,
              p_currency:
                code,
              p_exchange_rate_to_nok:
                code === "NOK"
                  ? 1
                  : rate,
              p_exchange_rate_date:
                fxMeta.rate_date ||
                invoiceDate.value,
              p_exchange_rate_source:
                fxMeta.source ||
                (
                  code === "NOK"
                    ? "NOK"
                    : "Manuell ved PDF-import"
                ),
              p_exchange_rate_reference:
                null,
              p_source_file_name:
                file.name,
              p_source_file_mime_type:
                file.type ||
                "application/pdf",
              p_notes:
                "PDF-import via Admin v5.11 \u00B7 " +
                parsed.parser,
              p_rows:
                parsed.rows,
              p_costs:
                costRows
            }
          )
            .then(
              function (result) {
                if (result.error) {
                  throw result.error;
                }

                var row =
                  result.data &&
                  result.data[0]
                    ? result.data[0]
                    : null;

                if (!row) {
                  throw new Error(
                    "Importen returnerte ingen faktura."
                  );
                }

                var smartSuggestionInfo = {
                  added: 0,
                  still_unmatched:
                    Number(
                      row.unmatched_lines ||
                      0
                    )
                };

                var finishImport =
                  function (
                    shipmentInfo
                  ) {
                    var shipmentText =
                      shipmentInfo
                        ? (
                            " Felles forsendelse er opprettet med " +
                            String(
                              shipmentInfo
                                .linked_invoice_count ||
                              0
                            ) +
                            " fakturaer. Frakten beregnes over hele forsendelsen n\u00E5r kostpris ferdigstilles."
                          )
                        : "";

                    alert(
                      "Faktura importert. " +
                        String(
                          row.auto_confirmed_lines ||
                          0
                        ) +
                        " linjer ble automatisk bekreftet fra tidligere SKU/EAN-l\u00E6ring, " +
                        String(
                          row.suggested_lines ||
                          0
                        ) +
                        " fikk produktforslag og " +
                        String(
                          row.unmatched_lines ||
                          0
                        ) +
                        " var ukjente ved r\u00E5import." +
                        (
                          smartSuggestionInfo.added > 0
                            ? (
                                " Smart navnmatch fant " +
                                String(
                                  smartSuggestionInfo.added
                                ) +
                                " produktforslag."
                              )
                            : ""
                        ) +
                        " " +
                        String(
                          smartSuggestionInfo.still_unmatched
                        ) +
                        " linjer st\u00E5r fortsatt uten sikker produktmatch." +
                        shipmentText +
                        " Lagerantall er ikke endret."
                    );

                    state.pdfImport =
                      null;

                    refreshAll(
                      row.invoice_id
                    );
                  };

                var continueAfterSmartMatch =
                  function () {
                    if (
                      shipmentDecision.mode ===
                        "shared" &&
                      parsed.costs &&
                      parsed.costs.length
                    ) {
                      createSharedShipmentAfterImport(
                        {
                          supplierId:
                            supplierId,
                          supplierName:
                            selectedSupplierName(),
                          currentInvoiceId:
                            row.invoice_id,
                          currentInvoiceNumber:
                            invoiceNo.value.trim(),
                          invoiceDate:
                            invoiceDate.value,
                          existingInvoiceIds:
                            sharedInvoiceIds,
                          existingInvoiceNumbers:
                            sharedInvoiceNumbers,
                          costs:
                            parsed.costs,
                          currency:
                            code,
                          rate:
                            code === "NOK"
                              ? 1
                              : rate,
                          rateDate:
                            fxMeta.rate_date ||
                            invoiceDate.value,
                          rateSource:
                            fxMeta.source ||
                            (
                              code === "NOK"
                                ? "NOK"
                                : "Manuell ved PDF-import"
                            )
                        }
                      )
                        .then(
                          function (
                            shipmentInfo
                          ) {
                            finishImport(
                              shipmentInfo
                            );
                          }
                        )
                        .catch(
                          function (
                            shipmentError
                          ) {
                            alert(
                              "Fakturaen ble importert, men felles forsendelse kunne ikke opprettes: " +
                                skReadableError(
                                  shipmentError &&
                                  shipmentError.message
                                    ? shipmentError.message
                                    : shipmentError
                                ) +
                                ". Ikke ferdigstill kostpris f\u00F8r dette er rettet."
                            );

                            state.pdfImport =
                              null;

                            refreshAll(
                              row.invoice_id
                            );
                          }
                        );

                      return;
                    }

                    finishImport(
                      null
                    );
                  };

                sb.rpc(
                  "internal_supplier_invoice_apply_smart_suggestions",
                  {
                    p_invoice_id:
                      row.invoice_id
                  }
                )
                  .then(
                    function (smartResult) {
                      if (smartResult.error) {
                        throw smartResult.error;
                      }

                      var smartRow =
                        smartResult.data &&
                        smartResult.data[0]
                          ? smartResult.data[0]
                          : {};

                      smartSuggestionInfo.added =
                        Number(
                          smartRow.suggestions_added ||
                          0
                        );

                      smartSuggestionInfo.still_unmatched =
                        Number(
                          smartRow.still_unmatched ||
                          0
                        );

                      continueAfterSmartMatch();
                    }
                  )
                  .catch(
                    function (smartError) {
                      console.warn(
                        "Smart produktmatch feilet:",
                        smartError
                      );

                      continueAfterSmartMatch();
                    }
                  );
              }
            )
            .catch(
              function (error) {
                importBtn.disabled =
                  false;
                importBtn.textContent =
                  "Importer faktura til kontroll";

                alert(
                  "Kunne ikke importere fakturaen: " +
                    skReadableError(
                      error &&
                      error.message
                        ? error.message
                        : error
                    )
                );
              }
            );
        };

      var cancel =
        createButton(
          "Avbryt"
        );

      cancel.onclick =
        function () {
          state.pdfImport =
            null;

          if (
            state.selectedInvoiceId
          ) {
            loadInvoiceDetails(
              state.selectedInvoiceId
            );
          } else {
            refreshAll(null);
          }
        };

      actions.appendChild(
        importBtn
      );
      actions.appendChild(
        cancel
      );

      section.appendChild(
        actions
      );

      right.appendChild(
        section
      );
    }

    function startPdfImport(
      file
    ) {
      if (!file) {
        return;
      }

      if (
        file.type &&
        file.type !==
          "application/pdf" &&
        !/\.pdf$/i.test(
          file.name || ""
        )
      ) {
        alert(
          "Velg en PDF-faktura."
        );
        return;
      }

      setLoading(
        right,
        "Leser PDF og finner fakturalinjer\u2026"
      );

      extractPdfText(file)
        .then(
          function (pages) {
            var parsed =
              parseSupplierPdf(
                pages
              );

            state.pdfImport = {
              file: file,
              parsed: parsed
            };

            renderPdfImport(
              file,
              parsed
            );
          }
        )
        .catch(
          function (error) {
            clear(right);

            var warning =
              el(
                "div",
                "Kunne ikke lese PDF-en: " +
                  skReadableError(
                    error &&
                    error.message
                      ? error.message
                      : error
                  )
              );

            warning.className =
              "sk-warning";

            right.appendChild(
              warning
            );
          }
        );
    }

    function refreshAll(
      keepInvoiceId
    ) {
      setLoading(
        left,
        "Laster fakturaer\u2026"
      );

      setLoading(
        right,
        "Laster fakturakontroll\u2026"
      );

      Promise.all([
        sb
          .from(
            "internal_supplier_invoice_review_summary_view"
          )
          .select("*")
          .order(
            "invoice_date",
            { ascending: false }
          ),

        sb
          .from(
            "internal_supplier_invoices_view"
          )
          .select("*")
          .order(
            "invoice_date",
            { ascending: false }
          ),

        sb
          .from(
            "internal_supplier_invoice_import_summary_view"
          )
          .select("*")
          .order(
            "invoice_date",
            { ascending: false }
          )
      ])
        .then(
          function (results) {
            state.summaries =
              resultData(
                results[0],
                "Fakturaoversikt"
              );

            state.invoiceMeta =
              resultData(
                results[1],
                "Fakturadetaljer"
              );

            state.importSummaries =
              resultData(
                results[2],
                "Fakturatotaler"
              );

            var preferred =
              keepInvoiceId ||
              state.selectedInvoiceId;

            if (
              preferred &&
              state.summaries.some(
                function (row) {
                  return (
                    row.invoice_id ===
                    preferred
                  );
                }
              )
            ) {
              state.selectedInvoiceId =
                preferred;
            } else {
              state.selectedInvoiceId =
                state.summaries.length
                  ? state.summaries[0]
                      .invoice_id
                  : null;
            }

            renderInvoiceList();

            if (
              state.selectedInvoiceId
            ) {
              loadInvoiceDetails(
                state.selectedInvoiceId
              );
            } else {
              clear(right);

              var empty = el(
                "div",
                "Det ligger ingen leverand\u00F8rfakturaer i systemet enn\u00E5."
              );

              empty.className =
                "sk-note";

              right.appendChild(
                empty
              );
            }
          }
        )
        .catch(
          function (error) {
            clear(left);
            clear(right);

            var box = el(
              "div",
              "Kunne ikke laste leverand\u00F8rfakturaer: " +
                skReadableError(
                  error &&
                  error.message
                    ? error.message
                    : error
                )
            );

            box.className =
              "sk-warning";

            right.appendChild(box);
          }
        );
    }

    function renderInvoiceList() {
      clear(left);

      var headingRow =
        el("div");

      headingRow.style.display =
        "flex";
      headingRow.style.alignItems =
        "center";
      headingRow.style.justifyContent =
        "space-between";
      headingRow.style.gap =
        "8px";
      headingRow.style.marginBottom =
        "8px";

      var heading =
        el(
          "div",
          "Fakturaer"
        );

      heading.style.fontWeight =
        "900";
      heading.style.fontSize =
        "13px";

      headingRow.appendChild(
        heading
      );

      left.appendChild(
        headingRow
      );


      var uploadBox =
        el("div");

      uploadBox.className =
        "sk-invoice-upload";

      uploadBox.appendChild(
        el(
          "div",
          "Ny leverand\u00F8rfaktura"
        )
      ).className =
        "sk-invoice-upload-title";

      var uploadInfo =
        el(
          "div",
          "Last opp leverand\u00F8rens PDF. Kjente formater leses automatisk, og ukjente formater stoppes f\u00F8r noe lagres."
        );

      uploadInfo.className =
        "sk-invoice-small";

      uploadBox.appendChild(
        uploadInfo
      );

      var fileInput =
        el("input");

      fileInput.type = "file";
      fileInput.accept =
        "application/pdf,.pdf";
      fileInput.style.display =
        "none";

      var uploadBtn =
        createPrimaryButton(
          "\uFF0B Last opp PDF"
        );

      uploadBtn.onclick =
        function () {
          fileInput.value = "";
          fileInput.click();
        };

      fileInput.onchange =
        function () {
          var file =
            fileInput.files &&
            fileInput.files[0]
              ? fileInput.files[0]
              : null;

          startPdfImport(
            file
          );
        };

      uploadBox.appendChild(
        uploadBtn
      );

      uploadBox.appendChild(
        fileInput
      );

      left.appendChild(
        uploadBox
      );


      /*
       * ------------------------------------------------------------
       * Fakturafilter
       *
       * Standard:
       *   Alle leverand\u00F8rer, nyeste fakturadato f\u00F8rst.
       *
       * Ved valg av leverand\u00F8r:
       *   Bare den leverand\u00F8rens fakturaer, fortsatt nyeste f\u00F8rst.
       * ------------------------------------------------------------
       */

      var supplierNames = [];

      state.summaries.forEach(
        function (summary) {
          var supplierName =
            String(
              summary.supplier_name ||
              ""
            ).trim();

          if (
            supplierName &&
            supplierNames.indexOf(
              supplierName
            ) === -1
          ) {
            supplierNames.push(
              supplierName
            );
          }
        }
      );

      supplierNames.sort(
        function (a, b) {
          return a.localeCompare(
            b,
            "nb"
          );
        }
      );


      var filterBox =
        el("div");

      filterBox.style.marginTop =
        "10px";
      filterBox.style.padding =
        "10px";
      filterBox.style.border =
        "1px solid #dbe3ee";
      filterBox.style.borderRadius =
        "12px";
      filterBox.style.background =
        "#fff";

      var filterLabel =
        el(
          "div",
          "Fakturaliste"
        );

      filterLabel.style.fontSize =
        "11px";
      filterLabel.style.fontWeight =
        "900";
      filterLabel.style.marginBottom =
        "6px";
      filterLabel.style.color =
        "#475569";

      filterBox.appendChild(
        filterLabel
      );

      var supplierSelect =
        el("select");

      supplierSelect.style.width =
        "100%";
      supplierSelect.style.boxSizing =
        "border-box";
      supplierSelect.style.minHeight =
        "38px";
      supplierSelect.style.border =
        "1px solid #cbd5e1";
      supplierSelect.style.borderRadius =
        "9px";
      supplierSelect.style.padding =
        "7px 9px";
      supplierSelect.style.background =
        "#fff";
      supplierSelect.style.fontWeight =
        "700";


      var allOption =
        document.createElement(
          "option"
        );

      allOption.value = "";
      allOption.textContent =
        "Alle leverand\u00F8rer \u00B7 nyeste f\u00F8rst";

      supplierSelect.appendChild(
        allOption
      );


      supplierNames.forEach(
        function (supplierName) {
          var option =
            document.createElement(
              "option"
            );

          option.value =
            supplierName;

          option.textContent =
            supplierName;

          supplierSelect.appendChild(
            option
          );
        }
      );

      supplierSelect.value =
        state.invoiceSupplierFilter ||
        "";

      filterBox.appendChild(
        supplierSelect
      );


      var visibleSummaries =
        state.summaries
          .filter(
            function (summary) {
              if (
                !state.invoiceSupplierFilter
              ) {
                return true;
              }

              return (
                String(
                  summary.supplier_name ||
                  ""
                ) ===
                state.invoiceSupplierFilter
              );
            }
          )
          .slice()
          .sort(
            function (a, b) {
              var dateA =
                String(
                  a.invoice_date ||
                  ""
                );

              var dateB =
                String(
                  b.invoice_date ||
                  ""
                );

              if (
                dateA !== dateB
              ) {
                return dateB.localeCompare(
                  dateA
                );
              }

              return String(
                b.invoice_number ||
                ""
              ).localeCompare(
                String(
                  a.invoice_number ||
                  ""
                )
              );
            }
          );


      var toggleBtn =
        createButton(
          state.invoiceListOpen
            ? "Skjul fakturaer"
            : (
                "Vis fakturaer \u00B7 " +
                visibleSummaries.length
              )
        );

      toggleBtn.style.width =
        "100%";
      toggleBtn.style.marginTop =
        "7px";

      filterBox.appendChild(
        toggleBtn
      );

      left.appendChild(
        filterBox
      );


      supplierSelect.onchange =
        function () {
          state.invoiceSupplierFilter =
            supplierSelect.value ||
            "";

          var filtered =
            state.summaries
              .filter(
                function (summary) {
                  if (
                    !state.invoiceSupplierFilter
                  ) {
                    return true;
                  }

                  return (
                    String(
                      summary.supplier_name ||
                      ""
                    ) ===
                    state.invoiceSupplierFilter
                  );
                }
              )
              .slice()
              .sort(
                function (a, b) {
                  return String(
                    b.invoice_date ||
                    ""
                  ).localeCompare(
                    String(
                      a.invoice_date ||
                      ""
                    )
                  );
                }
              );

          var selectedStillVisible =
            filtered.some(
              function (summary) {
                return (
                  summary.invoice_id ===
                  state.selectedInvoiceId
                );
              }
            );

          if (
            !selectedStillVisible
          ) {
            state.selectedInvoiceId =
              filtered.length
                ? filtered[0].invoice_id
                : null;
          }

          renderInvoiceList();

          if (
            state.selectedInvoiceId
          ) {
            loadInvoiceDetails(
              state.selectedInvoiceId
            );
          } else {
            clear(right);

            var emptyFiltered =
              el(
                "div",
                "Ingen fakturaer for valgt leverand\u00F8r."
              );

            emptyFiltered.className =
              "sk-note";

            right.appendChild(
              emptyFiltered
            );
          }
        };


      toggleBtn.onclick =
        function () {
          state.invoiceListOpen =
            !state.invoiceListOpen;

          renderInvoiceList();
        };


      if (
        !state.invoiceListOpen
      ) {
        var closedNote =
          el(
            "div",
            visibleSummaries.length +
              (
                visibleSummaries.length === 1
                  ? " faktura skjult."
                  : " fakturaer skjult."
              )
          );

        closedNote.className =
          "sk-invoice-small";

        closedNote.style.padding =
          "9px 2px";

        left.appendChild(
          closedNote
        );

        return;
      }


      var list =
        el("div");

      list.className =
        "sk-invoice-list";


      if (
        !visibleSummaries.length
      ) {
        var empty =
          el(
            "div",
            "Ingen fakturaer."
          );

        empty.className =
          "sk-warning";

        list.appendChild(
          empty
        );
      }


      visibleSummaries.forEach(
        function (summary) {
          var card =
            el("button");

          card.type = "button";

          card.className =
            "sk-invoice-card" +
            (
              summary.invoice_id ===
              state.selectedInvoiceId
                ? " sk-active"
                : ""
            );


          var top =
            el("div");

          top.className =
            "sk-invoice-card-top";


          var name =
            el(
              "strong",
              (
                summary.supplier_name ||
                "Leverand\u00F8r"
              ) +
                " \u00B7 " +
                (
                  summary.invoice_number ||
                  "uten nr."
                )
            );


          var statusInfo =
            invoiceStatusLabel(
              summary.status
            );


          top.appendChild(
            name
          );

          top.appendChild(
            statusBadge(
              statusInfo.label,
              statusInfo.tone
            )
          );

          card.appendChild(
            top
          );


          var readyLineCount =
            Number(
              summary.confirmed_lines ||
              0
            ) +
            Number(
              summary.ignored_lines ||
              0
            );

          var meta =
            el(
              "div",
              fmtDate(
                summary.invoice_date
              ) +
                " \u00B7 " +
                String(
                  summary.currency ||
                  ""
                ) +
                " \u00B7 " +
                String(
                  readyLineCount
                ) +
                "/" +
                String(
                  summary.total_lines ||
                  0
                ) +
                " klare"
            );

          meta.className =
            "sk-invoice-small";

          card.appendChild(
            meta
          );


          var total =
            Number(
              summary.total_lines ||
              0
            );


          var confirmed =
            Number(
              summary.confirmed_lines ||
              0
            ) +
            Number(
              summary.ignored_lines ||
              0
            );


          var progress =
            el("div");

          progress.className =
            "sk-invoice-progress";


          var fill =
            el("span");

          fill.style.width =
            (
              total > 0
                ? Math.min(
                    100,
                    confirmed /
                      total *
                      100
                  )
                : 0
            ) +
            "%";


          progress.appendChild(
            fill
          );

          card.appendChild(
            progress
          );


          card.onclick =
            function () {
              state.selectedInvoiceId =
                summary.invoice_id;

              renderInvoiceList();

              loadInvoiceDetails(
                summary.invoice_id
              );
            };


          list.appendChild(
            card
          );
        }
      );


      left.appendChild(
        list
      );
    }

    function loadVariantsForProducts(
      productIds
    ) {
      state.variantsByProduct =
        {};

      var unique = [];

      (productIds || []).forEach(
        function (id) {
          if (
            id &&
            unique.indexOf(id) === -1
          ) {
            unique.push(id);
          }
        }
      );

      if (!unique.length) {
        return Promise.resolve();
      }

      return sb
        .from(
          "internal_product_variants_view"
        )
        .select(
          "id,product_id,product_name,quickbutik_variant_sku,variant_name,stock_quantity,purchase_price_ex_vat,is_active"
        )
        .in(
          "product_id",
          unique
        )
        .eq(
          "is_active",
          true
        )
        .order(
          "quickbutik_variant_sku",
          { ascending: true }
        )
        .then(
          function (result) {
            if (result.error) {
              throw result.error;
            }

            (
              result.data || []
            ).forEach(
              function (variant) {
                if (
                  !state
                    .variantsByProduct[
                      variant.product_id
                    ]
                ) {
                  state
                    .variantsByProduct[
                      variant.product_id
                    ] = [];
                }

                state
                  .variantsByProduct[
                    variant.product_id
                  ]
                  .push(
                    variant
                  );
              }
            );
          }
        );
    }

    function loadInvoiceCostReferences(
      rows
    ) {
      state.productsById = {};
      state.variantsById = {};

      var productIds = [];
      var variantIds = [];

      (rows || []).forEach(
        function (row) {
          if (
            row.resolved_product_id &&
            productIds.indexOf(
              row.resolved_product_id
            ) === -1
          ) {
            productIds.push(
              row.resolved_product_id
            );
          }

          if (
            row.resolved_product_variant_id &&
            variantIds.indexOf(
              row.resolved_product_variant_id
            ) === -1
          ) {
            variantIds.push(
              row.resolved_product_variant_id
            );
          }
        }
      );

      var queries = [];

      if (productIds.length) {
        queries.push(
          sb
            .from(
              "internal_products_view"
            )
            .select(
              "id,name,brand,sales_price_inc_vat,sales_price_ex_vat,vat_rate,purchase_price_ex_vat,is_active"
            )
            .in(
              "id",
              productIds
            )
        );
      } else {
        queries.push(
          Promise.resolve({
            data: [],
            error: null
          })
        );
      }

      if (variantIds.length) {
        queries.push(
          sb
            .from(
              "internal_product_variants_view"
            )
            .select(
              "id,product_id,quickbutik_variant_sku,variant_name,sales_price_inc_vat,purchase_price_ex_vat,is_active"
            )
            .in(
              "id",
              variantIds
            )
        );
      } else {
        queries.push(
          Promise.resolve({
            data: [],
            error: null
          })
        );
      }

      return Promise.all(
        queries
      ).then(
        function (results) {
          if (results[0].error) {
            throw results[0].error;
          }

          if (results[1].error) {
            throw results[1].error;
          }

          (
            results[0].data || []
          ).forEach(
            function (product) {
              state.productsById[
                product.id
              ] = product;
            }
          );

          (
            results[1].data || []
          ).forEach(
            function (variant) {
              state.variantsById[
                variant.id
              ] = variant;
            }
          );
        }
      );
    }


    function loadInvoiceDetails(
      invoiceId
    ) {
      setLoading(
        right,
        "Laster faktura " +
          String(
            (
              findSummary(invoiceId) ||
              {}
            ).invoice_number ||
            ""
          ) +
          "\u2026"
      );

      Promise.all([
        sb
          .from(
            "internal_supplier_invoice_variant_review_view"
          )
          .select("*")
          .eq(
            "invoice_id",
            invoiceId
          )
          .order(
            "line_number",
            { ascending: true }
          ),

        sb
          .from(
            "internal_supplier_invoice_cost_only_allocation_view"
          )
          .select("*")
          .eq(
            "invoice_id",
            invoiceId
          )
          .order(
            "line_number",
            { ascending: true }
          ),

        sb
          .from(
            "internal_product_real_cost_history_view"
          )
          .select("*")
          .eq(
            "invoice_id",
            invoiceId
          )
          .order(
            "product_name",
            { ascending: true }
          ),

        sb
          .from(
            "internal_inventory_cost_movements"
          )
          .select(
            "id,movement_type"
          )
          .eq(
            "invoice_id",
            invoiceId
          )
          .eq(
            "movement_type",
            "invoice_weighted_average"
          )
      ])
        .then(
          function (results) {
            state.reviewRows =
              resultData(
                results[0],
                "Fakturalinjer"
              );

            state.previewRows =
              resultData(
                results[1],
                "Kost-preview"
              );

            state.costHistoryRows =
              resultData(
                results[2],
                "Lagret kosthistorikk"
              );

            state.selectedInvoiceApplied =
              resultData(
                results[3],
                "Kostoppdatering"
              ).length > 0;

            var editableProductIds =
              state.reviewRows
                .filter(
                  function (row) {
                    return (
                      row.resolved_product_id &&
                      Number(
                        row.active_variant_count ||
                        0
                      ) > 0
                    );
                  }
                )
                .map(
                  function (row) {
                    return row.resolved_product_id;
                  }
                );

            return Promise.all([
              loadVariantsForProducts(
                editableProductIds
              ),
              loadInvoiceCostReferences(
                state.reviewRows
              )
            ]);
          }
        )
        .then(
          function () {
            renderInvoiceDetails(
              invoiceId
            );
          }
        )
        .catch(
          function (error) {
            clear(right);

            var box = el(
              "div",
              "Kunne ikke laste fakturaen: " +
                skReadableError(
                  error &&
                  error.message
                    ? error.message
                    : error
                )
            );

            box.className =
              "sk-warning";

            right.appendChild(box);
          }
        );
    }

    function addSummaryCard(
      grid,
      label,
      value
    ) {
      var card = el("div");
      card.className =
        "sk-invoice-summary-card";

      card.appendChild(
        el("span", label)
      );

      card.appendChild(
        el(
          "strong",
          String(value)
        )
      );

      grid.appendChild(card);
    }

    function renderInvoiceDetails(
      invoiceId
    ) {
      clear(right);

      var summary =
        findSummary(invoiceId) ||
        {};

      var meta =
        findMeta(invoiceId) ||
        {};

      var importSummary =
        findImportSummary(
          invoiceId
        ) || {};

      var head = el("div");
      head.className =
        "sk-page-head";
      head.style.marginBottom =
        "8px";

      var headText = el("div");

      var title =
        el(
          "h2",
          (
            summary.supplier_name ||
            "Leverand\u00F8r"
          ) +
            " \u00B7 faktura " +
            (
              summary.invoice_number ||
              "uten nr."
            )
        );

      title.style.fontSize =
        "20px";

      headText.appendChild(title);

      var sub =
        el(
          "p",
          fmtDate(
            summary.invoice_date
          ) +
            " \u00B7 " +
            String(
              summary.currency ||
              ""
            ) +
            " \u00B7 kurs " +
            fmtNumber(
              summary.exchange_rate_to_nok,
              4
            ) +
            " NOK per " +
            String(
              summary.currency ||
              "valuta"
            )
        );

      headText.appendChild(sub);
      head.appendChild(headText);

      var statusInfo =
        invoiceStatusLabel(
          summary.status
        );

      head.appendChild(
        statusBadge(
          statusInfo.label,
          statusInfo.tone
        )
      );

      right.appendChild(head);

      var finance =
        el("div");

      finance.className =
        "sk-invoice-small";
      finance.style.marginBottom =
        "8px";

      var foreignTotal =
        maybeNum(
          importSummary
            .calculated_invoice_total_currency
        );

      var fx =
        maybeNum(
          summary.exchange_rate_to_nok
        );

      var nokTotal =
        foreignTotal !== null &&
        fx !== null
          ? foreignTotal * fx
          : null;

      finance.textContent =
        "Varer " +
        fmtCurrency(
          importSummary
            .goods_total_currency,
          summary.currency
        ) +
        " \u00B7 frakt/tillegg " +
        fmtCurrency(
          importSummary
            .extra_cost_total_currency,
          summary.currency
        ) +
        " \u00B7 total " +
        fmtCurrency(
          foreignTotal,
          summary.currency
        ) +
        (
          String(
            summary.currency ||
            ""
          ).toUpperCase() !== "NOK" &&
          nokTotal !== null
            ? (
                " \u00B7 ca. " +
                fmtMoneyNok(
                  nokTotal
                )
              )
            : ""
        );

      right.appendChild(
        finance
      );

      if (
        meta.source_file_name
      ) {
        var source =
          el(
            "div",
            "Kilde: " +
              meta.source_file_name
          );

        source.className =
          "sk-invoice-small";

        right.appendChild(
          source
        );
      }

      var totalLines =
        Number(
          summary.total_lines ||
          0
        );

      var finishedLines =
        Number(
          summary.confirmed_lines ||
          0
        ) +
        Number(
          summary.ignored_lines ||
          0
        );

      var remainingLines =
        Number(
          summary.remaining_review_lines ||
          0
        );

      var invoiceDate =
        String(
          summary.invoice_date ||
          ""
        );

      var historicalBaselineInvoice =
        summary.status === "costed" &&
        invoiceDate &&
        invoiceDate <= "2026-08-30";

      var workflow =
        el("div");

      workflow.style.margin =
        "12px 0";
      workflow.style.padding =
        "14px 16px";
      workflow.style.borderRadius =
        "12px";
      workflow.style.border =
        state.selectedInvoiceApplied ||
        historicalBaselineInvoice ||
        remainingLines === 0
          ? "1px solid #86efac"
          : "1px solid #fcd34d";
      workflow.style.background =
        state.selectedInvoiceApplied ||
        historicalBaselineInvoice ||
        remainingLines === 0
          ? "#f0fdf4"
          : "#fffbeb";

      var workflowTitle =
        el(
          "div",
          state.selectedInvoiceApplied
            ? "\u2705 Ferdig oppdatert"
            : (
                historicalBaselineInvoice
                  ? "\u2705 Historisk faktura ferdig"
                  : (
                      remainingLines > 0
                        ? (
                            "\u26A0\uFE0F " +
                            String(
                              remainingLines
                            ) +
                            (
                              remainingLines === 1
                                ? " linje m\u00E5 kontrolleres"
                                : " linjer m\u00E5 kontrolleres"
                            )
                          )
                        : "\u2705 Klar til oppdatering"
                    )
              )
        );

      workflowTitle.style.fontWeight =
        "900";
      workflowTitle.style.fontSize =
        "16px";

      workflow.appendChild(
        workflowTitle
      );

      var workflowText =
        el(
          "div",
          state.selectedInvoiceApplied
            ? "Vektet innkj\u00F8pspris er beregnet og endringene er synket til Quickbutik."
            : (
                historicalBaselineInvoice
                  ? "Denne fakturaen inng\u00E5r i den historiske kostbaselinen og skal ikke behandles som et nytt mottak."
                  : (
                      remainingLines > 0
                        ? (
                            String(
                              finishedLines
                            ) +
                            "/" +
                            String(
                              totalLines
                            ) +
                            " linjer er klare. Rett bare linjene nedenfor som systemet ikke kunne avgj\u00F8re sikkert."
                          )
                        : (
                            "Alle " +
                            String(
                              totalLines
                            ) +
                            " linjer er klare. Trykk \u00ABOppdater faktura\u00BB for \u00E5 beregne ny vektet kost og synke til Quickbutik."
                          )
                    )
              )
        );

      workflowText.style.marginTop =
        "4px";
      workflowText.style.color =
        "#475569";
      workflowText.style.fontSize =
        "13px";

      workflow.appendChild(
        workflowText
      );

      right.appendChild(
        workflow
      );

      renderInvoiceActions(
        right,
        summary
      );

      renderOutstandingReview(
        right,
        summary
      );

      renderSafeSuggestions(
        right,
        summary
      );

      renderConfirmedRows(
        right,
        summary
      );

      renderCostPreview(
        right,
        summary,
        importSummary
      );
    }

    function syncPendingQuickbutikPurchasePricesForInvoice() {
      var totalRequested = 0;
      var totalMarked = 0;
      var batchNumber = 0;
      var latestSummary = null;
      var accessToken = null;


      function sleep(ms) {
        return new Promise(
          function (resolve) {
            setTimeout(
              resolve,
              ms
            );
          }
        );
      }


      function runBatch() {
        batchNumber += 1;

        if (batchNumber > 100) {
          throw new Error(
            "Sikkerhetsstopp: mer enn 100 Quickbutik-batcher."
          );
        }

        var url =
          "https://sportskongen-quickbutik-sync.post-cd6.workers.dev/sync-purchase-prices" +
          "?dryRun=false" +
          "&limit=20";

        return fetch(
          url,
          {
            method: "GET",
            headers: {
              "Authorization":
                "Bearer " +
                accessToken
            }
          }
        )
          .then(
            function (response) {
              return response
                .json()
                .then(
                  function (data) {
                    return {
                      ok:
                        response.ok,
                      status:
                        response.status,
                      data:
                        data
                    };
                  }
                );
            }
          )
          .then(
            function (result) {
              if (
                !result.ok ||
                !result.data ||
                result.data.ok !== true
              ) {
                throw new Error(
                  "Quickbutik-synk feilet (" +
                    String(
                      result.status
                    ) +
                    "): " +
                    JSON.stringify(
                      result.data
                    )
                );
              }

              var requested =
                Number(
                  result.data.requested ||
                  0
                );

              var marked =
                Number(
                  result.data.marked_synced ||
                  0
                );

              totalRequested +=
                requested;

              totalMarked +=
                marked;

              latestSummary =
                result.data.summary ||
                latestSummary;

              if (
                requested === 0
              ) {
                return;
              }

              if (
                latestSummary &&
                Number(
                  latestSummary.needs_sync ||
                  0
                ) === 0
              ) {
                return;
              }

              return sleep(
                300
              ).then(
                runBatch
              );
            }
          );
      }


      return sb.auth.getSession()
        .then(
          function (sessionResult) {
            var session =
              sessionResult.data &&
              sessionResult.data.session;

            accessToken =
              session &&
              session.access_token;

            if (!accessToken) {
              throw new Error(
                "Fant ikke innlogget Supabase-session."
              );
            }

            return runBatch();
          }
        )
        .then(
          function () {
            return {
              batches:
                batchNumber,

              requested:
                totalRequested,

              marked_synced:
                totalMarked,

              remaining:
                latestSummary
                  ? Number(
                      latestSummary.needs_sync ||
                      0
                    )
                  : 0
            };
          }
        );
    }


    function updateInvoiceEndToEnd(
      summary,
      button
    ) {
      if (
        !summary ||
        !summary.invoice_id
      ) {
        return;
      }

      var invoiceNumber =
        String(
          summary.invoice_number ||
          ""
        );

      var confirmed =
        window.confirm(
          "Oppdatere faktura " +
            invoiceNumber +
            "?\n\n" +
            "Ny vektet innkj\u00F8pspris beregnes og endringer synkes til Quickbutik.\n\n" +
            "Lager og salgspris endres ikke."
        );

      if (!confirmed) {
        return;
      }

      var originalLabel =
        button.textContent;

      button.disabled = true;
      button.textContent =
        "Oppdaterer faktura\u2026";

      var finalizeRow = null;
      var shipmentResult = null;
      var previewRows = [];
      var applyRow = null;
      var quickbutikResult = null;
      var historicalFinalized = false;


      function finalizeCost() {
        button.textContent =
          "1/4 \u00B7 Lagrer kost\u2026";

        return sb.rpc(
          "internal_supplier_invoice_finalize_cost_only",
          {
            p_invoice_id:
              summary.invoice_id
          }
        )
          .then(
            function (result) {
              if (result.error) {
                throw result.error;
              }

              finalizeRow =
                result.data &&
                result.data[0]
                  ? result.data[0]
                  : null;

              return refreshSharedShipmentForInvoice(
                summary.invoice_id
              );
            }
          )
          .then(
            function (result) {
              shipmentResult =
                result || {
                  linked: false,
                  refreshed_invoices: 0,
                  skipped_invoices: 0
                };

              if (
                shipmentResult.linked &&
                Number(
                  shipmentResult.skipped_invoices ||
                  0
                ) > 0
              ) {
                throw new Error(
                  "Denne fakturaen inng\u00E5r i en felles forsendelse, men " +
                    String(
                      shipmentResult.skipped_invoices
                    ) +
                    " tilknyttet faktura(er) er ikke ferdigstilt enn\u00E5. Ferdigstill/kontroller alle fakturaene i samme forsendelse f\u00F8r kostprisen oppdateres."
                );
              }
            }
          );
      }


      function previewWeightedUpdate() {
        button.textContent =
          "2/4 \u00B7 Kontrollerer vekting\u2026";

        return sb.rpc(
          "internal_preview_invoice_weighted_update",
          {
            p_invoice_id:
              summary.invoice_id
          }
        )
          .then(
            function (result) {
              if (result.error) {
                throw result.error;
              }

              previewRows =
                Array.isArray(
                  result.data
                )
                  ? result.data
                  : [];

              if (!previewRows.length) {
                throw new Error(
                  "Fant ingen kostlinjer som kan beregnes for denne fakturaen."
                );
              }

              var variantProblems =
                previewRows.filter(
                  function (row) {
                    return row
                      .requires_variant_distribution ===
                      true;
                  }
                );

              if (
                variantProblems.length > 0
              ) {
                throw new Error(
                  String(
                    variantProblems.length
                  ) +
                    " kostlinje(r) gjelder produkter med varianter uten konkret variantfordeling. Fordel disse p\u00E5 riktige varianter f\u00F8r du trykker Oppdater faktura."
                );
              }

              var historical =
                previewRows.find(
                  function (row) {
                    return String(
                      row.readiness_status ||
                      ""
                    ).indexOf(
                      "Historisk faktura"
                    ) >= 0;
                  }
                );

              if (historical) {
                historicalFinalized = true;
              }
            }
          );
      }


      function applyWeightedUpdate() {
        if (historicalFinalized) {
          return Promise.resolve();
        }

        var allApplied =
          previewRows.length > 0 &&
          previewRows.every(
            function (row) {
              return row.already_applied === true;
            }
          );

        if (allApplied) {
          return Promise.resolve();
        }

        button.textContent =
          "3/4 \u00B7 Beregner ny kost\u2026";

        return sb.rpc(
          "internal_apply_invoice_weighted_update",
          {
            p_invoice_id:
              summary.invoice_id
          }
        )
          .then(
            function (result) {
              if (result.error) {
                throw result.error;
              }

              applyRow =
                result.data &&
                result.data[0]
                  ? result.data[0]
                  : null;
            }
          );
      }


      function syncQuickbutik() {
        if (historicalFinalized) {
          return Promise.resolve();
        }

        button.textContent =
          "4/4 \u00B7 Synker Quickbutik\u2026";

        return syncPendingQuickbutikPurchasePricesForInvoice()
          .then(
            function (result) {
              quickbutikResult =
                result;

              if (
                Number(
                  result.remaining ||
                  0
                ) > 0
              ) {
                throw new Error(
                  "Quickbutik-synken stoppet f\u00F8r alt var ferdig. " +
                    String(
                      result.remaining
                    ) +
                    " kostm\u00E5l gjenst\u00E5r."
                );
              }
            }
          );
      }


      finalizeCost()
        .then(
          previewWeightedUpdate
        )
        .then(
          applyWeightedUpdate
        )
        .then(
          syncQuickbutik
        )
        .then(
          function () {
            if (historicalFinalized) {
              alert(
                "\u2705 Faktura " +
                  invoiceNumber +
                  " er ferdig kostberegnet.\n\n" +
                  "Fakturaen er fra f\u00F8r historisk baseline 30.08.2026. Den er derfor registrert i kosthistorikken, men behandles ikke som et nytt varemottak.\n\n" +
                  "Lager og Quickbutik-priser er ikke endret."
              );

              refreshAll(
                summary.invoice_id
              );
              return;
            }

            var updatedTargets =
              Number(
                applyRow &&
                applyRow.products_updated ||
                0
              ) +
              Number(
                applyRow &&
                applyRow.variants_updated ||
                0
              );

            var message =
              "\u2705 Faktura " +
              invoiceNumber +
              " er ferdig.\n\n";

            if (finalizeRow) {
              message +=
                "Reell kost: " +
                fmtMoneyNok(
                  finalizeRow.total_real_cost_nok
                ) +
                "\n";
            }

            message +=
              "Kostpriser oppdatert: " +
              String(
                updatedTargets
              ) +
              "\n";

            if (quickbutikResult) {
              message +=
                "Quickbutik-priser synket: " +
                String(
                  quickbutikResult.marked_synced ||
                  0
                ) +
                "\n";
            }

            message +=
              "\nLager og salgspris er ikke endret.";

            alert(
              message
            );

            refreshAll(
              summary.invoice_id
            );
          }
        )
        .catch(
          function (error) {
            alert(
              "Oppdatering stoppet:\n\n" +
                skReadableError(
                  error &&
                  error.message
                    ? error.message
                    : error
                ) +
                "\n\nLager er ikke endret. Rett feilen og trykk \u00ABOppdater faktura\u00BB igjen."
            );
          }
        )
        .finally(
          function () {
            button.disabled = false;
            button.textContent =
              originalLabel;
          }
        );
    }


    function renderInvoiceActions(
      host,
      summary
    ) {
      var actions =
        el("div");

      actions.className =
        "sk-invoice-actions";

      var safeCount =
        Number(
          summary.safe_suggestion_lines ||
          0
        );

      if (safeCount > 0) {
        var accept =
          createPrimaryButton(
            "\u2705 Godkjenn " +
              String(safeCount) +
              " sikre treff"
          );

        accept.onclick =
          function () {
            if (
              !window.confirm(
                "Godkjenne " +
                  String(safeCount) +
                  " sikre produkt-/varianttreff?"
              )
            ) {
              return;
            }

            accept.disabled =
              true;
            accept.textContent =
              "Godkjenner\u2026";

            sb.rpc(
              "internal_supplier_invoice_accept_safe_suggestions",
              {
                p_invoice_id:
                  summary.invoice_id
              }
            )
              .then(
                function (result) {
                  if (result.error) {
                    throw result.error;
                  }

                  var row =
                    result.data &&
                    result.data[0]
                      ? result.data[0]
                      : null;

                  alert(
                    row
                      ? (
                          String(
                            row.confirmed_now ||
                            0
                          ) +
                          " linjer ble godkjent. " +
                          String(
                            row.still_requires_review ||
                            0
                          ) +
                          " st\u00E5r igjen til kontroll."
                        )
                      : "Trygge forslag ble godkjent."
                  );

                  refreshAll(
                    summary.invoice_id
                  );
                }
              )
              .catch(
                function (error) {
                  accept.disabled =
                    false;
                  accept.textContent =
                    "Godkjenn " +
                    String(safeCount) +
                    " trygge forslag";

                  alert(
                    "Kunne ikke godkjenne forslagene: " +
                      skReadableError(
                        error &&
                        error.message
                          ? error.message
                          : error
                      )
                  );
                }
              );
          };

        actions.appendChild(
          accept
        );
      }

      var invoiceDate =
        String(
          summary.invoice_date ||
          ""
        );

      var historicalBaselineInvoice =
        summary.status === "costed" &&
        invoiceDate &&
        invoiceDate <= "2026-08-30";


      if (
        Number(
          summary.remaining_review_lines ||
          0
        ) === 0 &&
        !historicalBaselineInvoice &&
        !state.selectedInvoiceApplied
      ) {
        var updateInvoice =
          createPrimaryButton(
            "\u2705 Oppdater faktura"
          );

        updateInvoice.onclick =
          function () {
            updateInvoiceEndToEnd(
              summary,
              updateInvoice
            );
          };

        actions.appendChild(
          updateInvoice
        );
      }


      if (
        historicalBaselineInvoice ||
        state.selectedInvoiceApplied
      ) {
        var doneBadge =
          el(
            "span",
            state.selectedInvoiceApplied
              ? "\u2705 Ferdig"
              : "\u2705 Historisk ferdig"
          );

        doneBadge.style.display =
          "inline-flex";
        doneBadge.style.alignItems =
          "center";
        doneBadge.style.padding =
          "9px 12px";
        doneBadge.style.borderRadius =
          "999px";
        doneBadge.style.background =
          "#dcfce7";
        doneBadge.style.color =
          "#166534";
        doneBadge.style.fontWeight =
          "900";
        doneBadge.style.fontSize =
          "13px";

        actions.appendChild(
          doneBadge
        );
      }

      if (
        Number(
          summary.unmatched_product_lines ||
          0
        ) > 0 &&
        summary.status !== "costed"
      ) {
        var smartMatch =
          createButton(
            "\u2728 Finn flere treff"
          );

        smartMatch.onclick =
          function () {
            smartMatch.disabled =
              true;
            smartMatch.textContent =
              "S\u00F8ker smart\u2026";

            sb.rpc(
              "internal_supplier_invoice_apply_smart_suggestions",
              {
                p_invoice_id:
                  summary.invoice_id
              }
            )
              .then(
                function (result) {
                  if (result.error) {
                    throw result.error;
                  }

                  var smartRow =
                    result.data &&
                    result.data[0]
                      ? result.data[0]
                      : {};

                  alert(
                    "Smart produkts\u00F8k fant " +
                      String(
                        smartRow.suggestions_added ||
                        0
                      ) +
                      " nye forslag. " +
                      String(
                        smartRow.still_unmatched ||
                        0
                      ) +
                      " linjer st\u00E5r fortsatt uten sikker produktmatch."
                  );

                  refreshAll(
                    summary.invoice_id
                  );
                }
              )
              .catch(
                function (error) {
                  smartMatch.disabled =
                    false;
                  smartMatch.textContent =
                    "\u2728 Finn flere treff";

                  alert(
                    "Smart produkts\u00F8k feilet: " +
                      skReadableError(
                        error &&
                        error.message
                          ? error.message
                          : error
                      )
                  );
                }
              );
          };

        actions.appendChild(
          smartMatch
        );
      }

      host.appendChild(actions);
    }

    function variantsForProduct(
      productId
    ) {
      return (
        state.variantsByProduct[
          productId
        ] || []
      );
    }

    function variantOptionLabel(
      variant
    ) {
      var parts = [
        variant.quickbutik_variant_sku ||
          variant.variant_name ||
          "Variant"
      ];

      parts.push(
        "lager " +
          fmtNumber(
            variant.stock_quantity,
            0
          )
      );

      parts.push(
        "kost " +
          fmtMoneyNok(
            variant.purchase_price_ex_vat
          )
      );

      return parts.join(" \u00B7 ");
    }

