    function createVariantSplitEditor(
      row,
      productId,
      variants
    ) {
      var box =
        el("div");

      box.className =
        "sk-variant-split";

      var title =
        el(
          "div",
          "Fordel " +
            fmtNumber(
              row.quantity,
              0
            ) +
            " stk p\u00E5 varianter"
        );

      title.className =
        "sk-variant-split-title";
      box.appendChild(title);

      var help =
        el(
          "div",
          "Legg inn hvor mange av hver Quickbutik-variant som faktisk kom p\u00E5 denne fakturalinjen. Summen m\u00E5 v\u00E6re n\u00F8yaktig " +
            fmtNumber(
              row.quantity,
              0
            ) +
            " stk. Dette brukes bare til kosthistorikk \u2013 lagerantall endres ikke."
        );

      help.className =
        "sk-variant-split-help";
      box.appendChild(help);

      var list =
        el("div");

      list.className =
        "sk-variant-split-list";
      box.appendChild(list);

      var inputs = [];

      (
        variants || []
      ).forEach(
        function (variant) {
          var line =
            el("div");

          line.className =
            "sk-variant-split-row";

          var name =
            el(
              "div",
              variantOptionLabel(
                variant
              )
            );

          name.className =
            "sk-variant-split-name";

          var input =
            el("input");

          input.type =
            "number";
          input.min =
            "0";
          input.step =
            "1";
          input.inputMode =
            "numeric";
          input.placeholder =
            "0";
          input.value =
            "";

          line.appendChild(name);
          line.appendChild(input);
          list.appendChild(line);

          inputs.push({
            variant: variant,
            input: input
          });
        }
      );

      var footer =
        el("div");

      footer.className =
        "sk-variant-split-footer";

      var total =
        el("div");

      total.className =
        "sk-variant-split-total";

      var save =
        createPrimaryButton(
          "Godkjenn fordeling"
        );

      footer.appendChild(total);
      footer.appendChild(save);
      box.appendChild(footer);

      function readAllocationState() {
        var allocations = [];
        var sum = 0;
        var invalid = false;

        inputs.forEach(
          function (entry) {
            var raw =
              String(
                entry.input.value ||
                ""
              ).trim();

            if (!raw) {
              return;
            }

            var quantity =
              Number(
                raw.replace(
                  ",",
                  "."
                )
              );

            if (
              !Number.isFinite(
                quantity
              ) ||
              quantity < 0
            ) {
              invalid = true;
              return;
            }

            if (quantity > 0) {
              sum += quantity;

              allocations.push({
                variant_id:
                  entry.variant.id,
                quantity:
                  quantity
              });
            }
          }
        );

        return {
          allocations:
            allocations,
          sum:
            sum,
          invalid:
            invalid
        };
      }

      function updateTotal() {
        var stateValue =
          readAllocationState();

        var wanted =
          Number(
            row.quantity ||
            0
          );

        var isOk =
          !stateValue.invalid &&
          stateValue.allocations.length >
            0 &&
          Math.abs(
            stateValue.sum -
            wanted
          ) < 0.000001;

        total.textContent =
          "Fordelt: " +
          fmtNumber(
            stateValue.sum,
            0
          ) +
          " / " +
          fmtNumber(
            wanted,
            0
          ) +
          " stk";

        total.className =
          "sk-variant-split-total" +
          (
            isOk
              ? " is-ok"
              : ""
          );

        save.disabled =
          !isOk;
      }

      inputs.forEach(
        function (entry) {
          entry.input.addEventListener(
            "input",
            updateTotal
          );
        }
      );

      save.onclick =
        function () {
          var stateValue =
            readAllocationState();

          var wanted =
            Number(
              row.quantity ||
              0
            );

          if (
            stateValue.invalid ||
            !stateValue.allocations.length ||
            Math.abs(
              stateValue.sum -
              wanted
            ) >= 0.000001
          ) {
            alert(
              "Variantantallene m\u00E5 summere til n\u00F8yaktig " +
                fmtNumber(
                  wanted,
                  0
                ) +
                " stk."
            );
            return;
          }

          if (
            !window.confirm(
              "Godkjenne fakturalinjen med " +
                String(
                  stateValue.allocations.length
                ) +
                " varianter og totalt " +
                fmtNumber(
                  stateValue.sum,
                  0
                ) +
                " stk? Lagerantall endres ikke."
            )
          ) {
            return;
          }

          confirmRowVariantSplit(
            row,
            productId,
            stateValue.allocations,
            save
          );
        };

      updateTotal();

      return {
        box: box,

        open: function () {
          box.classList.add(
            "is-open"
          );
        },

        close: function () {
          box.classList.remove(
            "is-open"
          );
        },

        isOpen: function () {
          return box.classList.contains(
            "is-open"
          );
        }
      };
    }


    function ignoreInvoiceRow(
      row,
      button
    ) {
      var reason =
        window.prompt(
          "Hvorfor skal linjen utelates fra produktkost? Linjen beholdes p\u00E5 fakturaen.",
          "Ikke lagerf\u00F8rt produkt / skal ikke p\u00E5virke produktkost"
        );

      if (reason === null) {
        return;
      }

      if (
        !window.confirm(
          "Utelate denne fakturalinjen fra produktkost? Den beholdes p\u00E5 fakturaen og dens andel av frakt/tillegg blir ikke flyttet over p\u00E5 andre varer."
        )
      ) {
        return;
      }

      button.disabled = true;
      var oldText =
        button.textContent;
      button.textContent =
        "Utelater\u2026";

      sb.rpc(
        "internal_supplier_invoice_ignore_row",
        {
          p_import_row_id:
            row.import_row_id,
          p_reason:
            reason || null
        }
      )
        .then(
          function (result) {
            if (result.error) {
              throw result.error;
            }

            refreshAll(
              row.invoice_id
            );
          }
        )
        .catch(
          function (error) {
            button.disabled =
              false;
            button.textContent =
              oldText;

            alert(
              "Kunne ikke utelate linjen: " +
                skReadableError(
                  error &&
                  error.message
                    ? error.message
                    : error
                )
            );
          }
        );
    }


    function renderOutstandingReview(
      host,
      summary
    ) {
      var rows =
        state.reviewRows.filter(
          function (row) {
            return (
              (
                row.variant_review_status ===
                  "manual_variant_review" ||
                row.variant_review_status ===
                  "product_unmatched"
              )
            );
          }
        );

      if (!rows.length) {
        return;
      }

      var section =
        el("div");

      section.className =
        "sk-invoice-section";

      section.appendChild(
        el(
          "h3",
          "Kontroller disse linjene \u00B7 " +
            String(rows.length)
        )
      );

      var desc =
        el(
          "div",
          "Systemet var ikke sikkert nok p\u00E5 disse. Velg riktig produkt/variant, fordel p\u00E5 flere varianter ved behov, eller utelat linjen."
        );

      desc.className =
        "sk-invoice-section-sub";

      section.appendChild(desc);

      var list = el("div");
      list.className =
        "sk-invoice-review-list";

      rows.forEach(
        function (row) {
          if (
            row.variant_review_status ===
            "product_unmatched"
          ) {
            renderUnmatchedProductRow(
              list,
              row
            );
          } else {
            renderManualVariantRow(
              list,
              row
            );
          }
        }
      );

      section.appendChild(list);
      host.appendChild(section);
    }

