    function selectCount(
      countId,
      destination
    ) {
      if (
        Object.keys(
          pendingStockChanges
        ).length
      ) {
        var discard =
          window.confirm(
            "Du har ulagrede endringer i tellingen.\n\nBytte varetelling og forkaste de ulagrede endringene?"
          );

        if (!discard) {
          return;
        }

        pendingStockChanges =
          {};
      }

      selectedCountId =
        countId;

      localStorage.setItem(
        "sk_internal_selected_stock_count_id",
        countId
      );

      countingFilterTouched =
        false;

      renderCurrentCounts();
      renderWorkspace();
      renderReport();
      renderHistory();

      var target =
        destination ===
        "report"
          ? reportSection.wrap
          : workspaceSection.wrap;

      setTimeout(
        function () {
          target.scrollIntoView({
            behavior:
              "smooth",
            block:
              "start"
          });
        },
        30
      );
    }


