    function cleanVariantText(
      item
    ) {
      var parts = [];


      function addPart(
        value
      ) {
        value =
          String(
            value ||
            ""
          )
            .trim();

        if (!value) {
          return;
        }

        value =
          value
            .replace(
              /\bvariant\s*\d+\b/gi,
              ""
            )
            .replace(
              /^[\s\-\u2013\u2014|/\u00B7:]+/g,
              ""
            )
            .replace(
              /[\s\-\u2013\u2014|/\u00B7:]+$/g,
              ""
            )
            .trim();

        if (
          value &&
          parts.indexOf(
            value
          ) === -1
        ) {
          parts.push(
            value
          );
        }
      }


      function escapeRegex(
        value
      ) {
        return String(
          value ||
          ""
        ).replace(
          /[.*+?^${}()|[\]\\]/g,
          "\\$&"
        );
      }


      function removeProductName(
        value,
        productName
      ) {
        value =
          String(
            value ||
            ""
          )
            .trim();

        productName =
          String(
            productName ||
            ""
          )
            .trim();

        if (
          !value ||
          !productName
        ) {
          return value;
        }

        var regex =
          new RegExp(
            escapeRegex(
              productName
            ),
            "gi"
          );

        return value
          .replace(
            regex,
            ""
          )
          .replace(
            /\bvariant\s*\d+\b/gi,
            ""
          )
          .replace(
            /^[\s\-\u2013\u2014|/\u00B7:]+/g,
            ""
          )
          .replace(
            /[\s\-\u2013\u2014|/\u00B7:]+$/g,
            ""
          )
          .replace(
            /\s{2,}/g,
            " "
          )
          .trim();
      }


      addPart(
        item.option_1_value
      );

      addPart(
        item.option_2_value
      );

      addPart(
        item.option_3_value
      );


      if (
        parts.length === 0 &&
        item.quickbutik_variant_sku
      ) {
        var cleanedSku =
          removeProductName(
            item
              .quickbutik_variant_sku,
            item.name
          );

        cleanedSku =
          cleanedSku
            .replace(
              /\s+-\s+/g,
              " / "
            )
            .replace(
              /\s+\u2013\s+/g,
              " / "
            )
            .replace(
              /\s+\u2014\s+/g,
              " / "
            )
            .replace(
              /\s{2,}/g,
              " "
            )
            .trim();

        addPart(
          cleanedSku
        );
      }


      if (
        parts.length === 0 &&
        item.variant_name
      ) {
        addPart(
          item.variant_name
        );
      }


      return (
        parts.length
          ? parts.join(
              " / "
            )
          : "-"
      );
    }


    function visibleItems(
      count,
      searchValue,
      filterValue,
      hideZero
    ) {
      var query =
        String(
          searchValue ||
          ""
        )
          .toLowerCase()
          .trim();


      return countItems(
        count.id
      )
        .filter(
          function (item) {
            var isCounted =
              item.counted_quantity !==
                null &&
              item.counted_quantity !==
                undefined;


            if (
              filterValue ===
                "not_counted" &&
              isCounted
            ) {
              return false;
            }


            if (
              filterValue ===
                "counted" &&
              !isCounted
            ) {
              return false;
            }


            if (
              filterValue ===
                "differences" &&
              (
                !isCounted ||
                Number(
                  item.difference_quantity ||
                  0
                ) === 0
              )
            ) {
              return false;
            }


            if (
              hideZero &&
              Number(
                item.expected_quantity ||
                0
              ) === 0
            ) {
              return false;
            }


            if (!query) {
              return true;
            }


            var haystack = [
              item.name,
              item.brand,
              item.category,
              item.supplier_name,
              item.quickbutik_sku,
              item.quickbutik_product_id,
              item.quickbutik_variant_id,
              item.quickbutik_variant_sku,
              item.variant_name,
              item.option_1_value,
              item.option_2_value,
              item.option_3_value
            ]
              .map(
                function (value) {
                  return String(
                    value ||
                    ""
                  ).toLowerCase();
                }
              )
              .join(" ");


            return (
              haystack.indexOf(
                query
              ) >= 0
            );
          }
        )
        .sort(
          function (a, b) {
            return String(
              a.name ||
              ""
            ).localeCompare(
              String(
                b.name ||
                ""
              ),
              "no"
            );
          }
        );
    }


