  function addFilterButton(
    label,
    filterKey,
    count
  ) {
    var btn =
      createButton(
        label +
          " \u00B7 " +
          String(count)
      );

    btn.onclick =
      function () {
        activeFilter =
          filterKey;

        updateFilterButtons();
        renderRows();
      };

    filterButtons[
      filterKey
    ] = btn;

    toolbar.appendChild(
      btn
    );
  }


  function updateFilterButtons() {
    Object.keys(
      filterButtons
    ).forEach(
      function (key) {
        var btn =
          filterButtons[key];

        if (
          key ===
          activeFilter
        ) {
          btn.style.background =
            "#111827";
          btn.style.color =
            "#fff";
          btn.style.borderColor =
            "#111827";
        } else {
          btn.style.background =
            "#fff";
          btn.style.color =
            "#111827";
          btn.style.borderColor =
            "#d1d5db";
        }
      }
    );
  }


