    function rebuildProductOptions(searchText) {
      var previousValue =
        productSelect.value;

      clear(productSelect);

      var emptyOption = el(
        "option",
        "Velg produkt..."
      );

      emptyOption.value = "";
      productSelect.appendChild(
        emptyOption
      );

      var normalizedSearch =
        String(searchText || "")
          .toLowerCase()
          .trim();

      var filteredProducts =
        relevantProducts.filter(
          function (product) {
            if (!normalizedSearch) {
              return true;
            }

            var haystack = (
              String(product.name || "") +
              " " +
              String(product.brand || "") +
              " " +
              String(product.quickbutik_sku || "")
            ).toLowerCase();

            return haystack.includes(
              normalizedSearch
            );
          }
        );

      filteredProducts.forEach(
        function (product) {
          var option = el(
            "option",
            getProductOptionLabel(product)
          );

          option.value = product.id;

          productSelect.appendChild(
            option
          );
        }
      );

      if (
        previousValue &&
        filteredProducts.some(
          function (product) {
            return (
              String(product.id) ===
              String(previousValue)
            );
          }
        )
      ) {
        productSelect.value =
          previousValue;
      }

      if (
        normalizedSearch &&
        filteredProducts.length === 1
      ) {
        productSelect.value =
          filteredProducts[0].id;
      }
    }

