    function getPriceCheckToken() {
      return sb.auth
        .getSession()
        .then(function (sessionResult) {
          if (sessionResult.error) {
            throw sessionResult.error;
          }

          var session =
            sessionResult.data &&
            sessionResult.data.session;

          var token =
            session &&
            session.access_token;

          if (!token) {
            throw new Error(
              "Fant ikke aktiv Supabase-session."
            );
          }

          return token;
        });
    }

    function isRetryablePriceCheckError(
      error
    ) {
      var message =
        String(
          error &&
          (
            error.message ||
            error
          ) ||
          ""
        ).toLowerCase();

      return (
        message.indexOf(
          "failed to fetch"
        ) !== -1 ||
        message.indexOf(
          "networkerror"
        ) !== -1 ||
        message.indexOf(
          "load failed"
        ) !== -1 ||
        message.indexOf(
          "http 429"
        ) !== -1 ||
        message.indexOf(
          "http 500"
        ) !== -1 ||
        message.indexOf(
          "http 502"
        ) !== -1 ||
        message.indexOf(
          "http 503"
        ) !== -1 ||
        message.indexOf(
          "http 504"
        ) !== -1
      );
    }

    function callPriceCheckWorkerOnce(
      payload
    ) {
      return getPriceCheckToken()
        .then(function (token) {
          return fetch(
            "https://golfkongen-price-check.post-cd6.workers.dev/check",
            {
              method: "POST",
              headers: {
                "Authorization":
                  "Bearer " + token,
                "Content-Type":
                  "application/json"
              },
              body:
                JSON.stringify(
                  payload
                )
            }
          );
        })
        .then(function (response) {
          return response
            .text()
            .then(function (responseText) {
              var responseData = null;

              try {
                responseData =
                  responseText
                    ? JSON.parse(
                        responseText
                      )
                    : {};
              } catch (_) {
                var invalidError =
                  new Error(
                    "Prissjekken ga ugyldig svar (HTTP " +
                    String(
                      response.status
                    ) +
                    ")."
                  );

                invalidError.retryable =
                  response.status >= 500;

                throw invalidError;
              }

              if (!response.ok) {
                var httpError =
                  new Error(
                    responseData.error ||
                    "Prissjekken svarte HTTP " +
                      response.status
                  );

                httpError.retryable =
                  response.status === 429 ||
                  response.status >= 500;

                throw httpError;
              }

              return responseData;
            });
        });
    }

    function callPriceCheckWorker(
      payload,
      attempt
    ) {
      var currentAttempt =
        Number(attempt || 1);

      return callPriceCheckWorkerOnce(
        payload
      ).catch(function (error) {
        var retryable =
          error &&
          error.retryable === true
            ? true
            : isRetryablePriceCheckError(
                error
              );

        if (
          retryable &&
          currentAttempt < 4
        ) {
          var delay =
            currentAttempt === 1
              ? 3500
              : currentAttempt === 2
                ? 7000
                : 14000;

          return waitPriceCheck(
            delay
          ).then(function () {
            return callPriceCheckWorker(
              payload,
              currentAttempt + 1
            );
          });
        }

        throw error;
      });
    }

    var PRICE_CHECK_SOURCE_FALLBACKS = [
      {
        key: "discinstock",
        label: "DiscInStock"
      },
      {
        key: "krokhol",
        label: "Krokhol"
      },
      {
        key: "dgshop",
        label: "DGshop"
      },
      {
        key: "frisbeebutikken",
        label: "Frisbeebutikken"
      },
      {
        key: "wearediscgolf",
        label: "WeAreDiscGolf"
      }
    ];

    function clonePriceCheckPayload(
      payload
    ) {
      return JSON.parse(
        JSON.stringify(
          payload || {}
        )
      );
    }

    function callPriceCheckSourceFallback(
      payload,
      sourceDefinition,
      attempt
    ) {
      var currentAttempt =
        Number(attempt || 1);

      var sourcePayload =
        clonePriceCheckPayload(
          payload
        );

      sourcePayload.sources = [
        sourceDefinition.key
      ];

      return callPriceCheckWorkerOnce(
        sourcePayload
      ).catch(function (error) {
        var retryable =
          error &&
          error.retryable === true
            ? true
            : isRetryablePriceCheckError(
                error
              );

        if (
          retryable &&
          currentAttempt < 2
        ) {
          return waitPriceCheck(
            3000
          ).then(function () {
            return callPriceCheckSourceFallback(
              payload,
              sourceDefinition,
              currentAttempt + 1
            );
          });
        }

        throw error;
      });
    }

    function mergePriceCheckSourceResults(
      payload,
      sourceRuns,
      originalError
    ) {
      var mergedProductResult = null;
      var mergedCandidates = [];
      var mergedSourceStatus = {};
      var mergedSuggestions = [];
      var sourceFailures = [];
      var generatedAt = null;
      var version = null;
      var rateLimited = false;
      var successfulSources = 0;

      sourceRuns.forEach(
        function (sourceRun) {
          if (!sourceRun.ok) {
            sourceFailures.push({
              key:
                sourceRun.source.key,
              label:
                sourceRun.source.label,
              error:
                sourceRun.error
            });

            mergedSourceStatus[
              sourceRun.source.key
            ] = {
              ok: false,
              error:
                sourceRun.error
            };

            return;
          }

          successfulSources += 1;

          var result =
            sourceRun.result || {};

          version =
            version ||
            result.version ||
            null;

          generatedAt =
            result.generatedAt ||
            generatedAt;

          if (
            result.stoppedBecauseRateLimited
          ) {
            rateLimited = true;
          }

          var productResult =
            result.productResults &&
            result.productResults[0];

          if (productResult) {
            if (!mergedProductResult) {
              mergedProductResult =
                {
                  productId:
                    productResult.productId,
                  productName:
                    productResult.productName,
                  productBrand:
                    productResult.productBrand,
                  golfkongenPrice:
                    productResult.golfkongenPrice,
                  stockQuantity:
                    productResult.stockQuantity,
                  candidates: [],
                  sourceStatus: {}
                };
            }

            (
              productResult.candidates ||
              []
            ).forEach(
              function (candidate) {
                mergedCandidates.push(
                  candidate
                );
              }
            );

            Object.keys(
              productResult.sourceStatus ||
              {}
            ).forEach(
              function (sourceKey) {
                mergedSourceStatus[
                  sourceKey
                ] =
                  productResult
                    .sourceStatus[
                      sourceKey
                    ];
              }
            );
          }

          (
            result.suggestions ||
            []
          ).forEach(
            function (suggestion) {
              mergedSuggestions.push(
                suggestion
              );
            }
          );
        }
      );

      if (!mergedProductResult) {
        var noResultError =
          new Error(
            "Alle priskilder feilet ogs\u00E5 i kildevis fallback."
          );

        noResultError.sourceFailures =
          sourceFailures;

        throw noResultError;
      }

      mergedProductResult.candidates =
        mergedCandidates;

      mergedProductResult.sourceStatus =
        mergedSourceStatus;

      mergedProductResult.fallbackUsed =
        true;

      mergedProductResult.fallbackSourceFailures =
        sourceFailures;

      /*
       * Produktet er delvis kontrollert dersom minst \u00E9n kilde
       * fortsatt ikke lot seg kj\u00F8re. Forslag fra kildene som
       * fungerte beholdes og kan lagres, men produktet blir
       * st\u00E5ende i retry-listen til alle kilder er kontrollert.
       */
      if (sourceFailures.length) {
        mergedProductResult.error =
          "Kildevis fallback: " +
          sourceFailures.map(
            function (failure) {
              return (
                failure.label +
                ": " +
                failure.error
              );
            }
          ).join(" | ");
      }

      return {
        ok: true,
        version:
          version || "fallback",
        mode:
          payload.mode || "selected",
        requestedProducts: 1,
        checkedProducts: 1,
        totalSuggestions:
          mergedCandidates.length,
        stoppedBecauseRateLimited:
          rateLimited,
        fallbackUsed: true,
        fallbackOriginalError:
          originalError &&
          (
            originalError.message ||
            String(originalError)
          ),
        fallbackSuccessfulSources:
          successfulSources,
        fallbackSourceFailures:
          sourceFailures,
        productResults: [
          mergedProductResult
        ],
        suggestions:
          mergedSuggestions,
        generatedAt:
          generatedAt ||
          new Date().toISOString()
      };
    }

    function callPriceCheckWorkerResilient(
      payload
    ) {
      return callPriceCheckWorker(
        payload
      ).catch(function (originalError) {
        /*
         * Bare fall tilbake kilde-for-kilde n\u00E5r vi sjekker ett
         * produkt. Fullkj\u00F8ringen sender n\u00E5 alltid ett produkt
         * per kall.
         */
        var productCount =
          Array.isArray(
            payload.product_ids
          )
            ? payload.product_ids.length
            : (
                payload.product_id
                  ? 1
                  : 0
              );

        if (productCount !== 1) {
          throw originalError;
        }

        var sourceRuns = [];
        var chain =
          Promise.resolve();

        PRICE_CHECK_SOURCE_FALLBACKS
          .forEach(
            function (
              sourceDefinition
            ) {
              chain =
                chain.then(
                  function () {
                    return callPriceCheckSourceFallback(
                      payload,
                      sourceDefinition,
                      1
                    )
                      .then(
                        function (result) {
                          sourceRuns.push({
                            ok: true,
                            source:
                              sourceDefinition,
                            result:
                              result
                          });
                        }
                      )
                      .catch(
                        function (error) {
                          sourceRuns.push({
                            ok: false,
                            source:
                              sourceDefinition,
                            error:
                              error &&
                              (
                                error.message ||
                                String(error)
                              )
                          });
                        }
                      )
                      .then(
                        function () {
                          return waitPriceCheck(
                            900
                          );
                        }
                      );
                  }
                );
            }
          );

        return chain.then(
          function () {
            return mergePriceCheckSourceResults(
              payload,
              sourceRuns,
              originalError
            );
          }
        );
      });
    }

    function renderPriceCheckWorkerResult(result) {
      clear(workerResult);
      workerResult.style.display = "block";

      var productResult =
        result &&
        result.productResults &&
        result.productResults[0];

      if (!productResult) {
        workerResult.appendChild(
          el(
            "div",
            "Prissjekken returnerte ikke noe produktresultat."
          )
        );
        return;
      }

      var summary = el("div");
      summary.style.padding = "14px";
      summary.style.border =
        "1px solid #d1d5db";
      summary.style.borderRadius = "14px";
      summary.style.background = "#f8fafc";

      var summaryTitle = el(
        "h3",
        productResult.productName ||
          "Produktresultat"
      );

      summaryTitle.style.margin =
        "0 0 10px 0";

      summary.appendChild(summaryTitle);

      var ownPrice = el(
        "p",
        "GolfKongen-pris: " +
          formatPriceCheckMoney(
            productResult.golfkongenPrice
          )
      );

      ownPrice.style.margin = "4px 0";
      summary.appendChild(ownPrice);

      function sourceSummary(label, key, countKey) {
        var status =
          productResult.sourceStatus &&
          productResult.sourceStatus[key];

        if (!status || !status.ok) {
          return label + ": feil";
        }

        return (
          label +
          ": " +
          String(status[countKey] || 0)
        );
      }

      var sourceText = el(
        "p",
        [
          sourceSummary(
            "Krokhol",
            "krokhol",
            "productsFound"
          ),
          sourceSummary(
            "DiscInStock",
            "discinstock",
            "cardsFound"
          ),
          sourceSummary(
            "DGshop",
            "dgshop",
            "productsFound"
          ),
          sourceSummary(
            "Frisbeebutikken",
            "frisbeebutikken",
            "productsFound"
          ),
          sourceSummary(
            "WeAreDiscGolf",
            "wearediscgolf",
            "productsFound"
          )
        ].join(" \u00B7 ")
      );

      sourceText.style.margin = "4px 0";
      sourceText.style.color = "#475569";

      summary.appendChild(sourceText);
      workerResult.appendChild(summary);

      var candidates =
        productResult.candidates || [];

      if (!candidates.length) {
        var diagnostics =
          productResult.diagnostics ||
          {};

        var sourceCounts = [];

        [
          ["Krokhol", "krokhol", "productsFound"],
          ["DiscInStock", "discinstock", "cardsFound"],
          ["DGshop", "dgshop", "productsFound"],
          ["Frisbeebutikken", "frisbeebutikken", "productsFound"],
          ["WeAreDiscGolf", "wearediscgolf", "productsFound"]
        ].forEach(function (definition) {
          var status =
            productResult.sourceStatus &&
            productResult.sourceStatus[
              definition[1]
            ];

          sourceCounts.push({
            label: definition[0],
            count:
              status && status.ok
                ? Number(
                    status[
                      definition[2]
                    ] || 0
                  )
                : null,
            note:
              status &&
              status.note
                ? status.note
                : null,
            error:
              status &&
              status.ok === false
                ? status.error
                : null
          });
        });

        var totalSearchResults =
          sourceCounts.reduce(
            function (sum, item) {
              return (
                sum +
                (
                  item.count === null
                    ? 0
                    : item.count
                )
              );
            },
            0
          );

        var noCandidates = el(
          "div",
          totalSearchResults > 0
            ? (
                "Ingen sikre konkurrenttreff. S\u00F8ket fant " +
                String(totalSearchResults) +
                " mulige produkter hos kildene, men ingen bestod alle kravene."
              )
            : (
                "Ingen konkurrentprodukter ble funnet i s\u00F8ket."
              )
        );

        noCandidates.className =
          "sk-note";
        noCandidates.style.marginTop =
          "12px";

        workerResult.appendChild(
          noCandidates
        );

        var diagnosticGrid =
          el("div");

        diagnosticGrid.className =
          "sk-card-grid";

        [
          {
            label:
              "Unike kandidater",
            value:
              diagnostics.uniqueCandidates !==
                undefined
                ? diagnostics.uniqueCandidates
                : "-"
          },
          {
            label:
              "Filtrert av l\u00E6ring",
            value:
              diagnostics.excludedByLearning !==
                undefined
                ? diagnostics.excludedByLearning
                : "-"
          },
          {
            label:
              "Under minimumsscore",
            value:
              diagnostics.belowMinimumConfidence !==
                undefined
                ? diagnostics.belowMinimumConfidence
                : "-"
          },
          {
            label:
              "L\u00E6ringseksempler",
            value:
              productResult.learningExamples !==
                undefined
                ? productResult.learningExamples
                : "-"
          }
        ].forEach(function (item) {
          var box = el("div");
          box.className = "sk-card";

          var label =
            el(
              "div",
              item.label
            );
          label.className =
            "sk-card-label";

          var value =
            el(
              "strong",
              String(item.value)
            );
          value.className =
            "sk-card-value";

          box.appendChild(label);
          box.appendChild(value);
          diagnosticGrid.appendChild(box);
        });

        workerResult.appendChild(
          diagnosticGrid
        );

        var sourceDiagnostic =
          el("div");

        sourceDiagnostic.className =
          "sk-diagnostic-list";

        sourceCounts.forEach(
          function (item) {
            var row = el("div");
            row.className =
              "sk-diagnostic-row";

            row.appendChild(
              el(
                "strong",
                item.label +
                  ": " +
                  (
                    item.count === null
                      ? "feil"
                      : String(
                          item.count
                        ) +
                        " s\u00F8keresultat"
                  )
              )
            );

            if (item.note) {
              row.appendChild(
                el(
                  "div",
                  item.note
                )
              );
            }

            if (item.error) {
              row.appendChild(
                el(
                  "div",
                  "Feil: " +
                    item.error
                )
              );
            }

            sourceDiagnostic.appendChild(
              row
            );
          }
        );

        workerResult.appendChild(
          sourceDiagnostic
        );

        var filtered =
          diagnostics.topFilteredCandidates ||
          [];

        if (filtered.length) {
          var filteredTitle =
            el(
              "h3",
              "N\u00E6rmeste kandidater som ble stoppet"
            );

          filteredTitle.style.margin =
            "18px 0 8px";

          workerResult.appendChild(
            filteredTitle
          );

          filtered.forEach(
            function (candidate) {
              var row = el("div");
              row.className =
                "sk-diagnostic-row";

              var reasonParts = [];

              if (
                candidate.excludedByLearning
              ) {
                reasonParts.push(
                  "stoppet av tidligere l\u00E6ring"
                );
              } else {
                reasonParts.push(
                  "score " +
                    String(
                      candidate.matchConfidence ||
                      0
                    ) +
                    "%, minimum " +
                    String(
                      diagnostics.minimumConfidence ||
                      70
                    ) +
                    "%"
                );
              }

              (
                candidate.matchWarnings ||
                []
              ).forEach(
                function (warning) {
                  reasonParts.push(
                    warning
                  );
                }
              );

              (
                candidate.learningApplied ||
                []
              ).forEach(
                function (learning) {
                  reasonParts.push(
                    "l\u00E6ring: " +
                      learning
                  );
                }
              );

              row.appendChild(
                el(
                  "strong",
                  (
                    candidate.name ||
                    "Ukjent produkt"
                  ) +
                    " \u00B7 " +
                    (
                      candidate.store ||
                      "ukjent butikk"
                    )
                )
              );

              row.appendChild(
                el(
                  "div",
                  reasonParts.join(
                    " \u00B7 "
                  )
                )
              );

              workerResult.appendChild(
                row
              );
            }
          );
        }

        return;
      }

      candidates.forEach(function (candidate) {
        var card = el("div");

        card.style.marginTop = "12px";
        card.style.padding = "14px";
        card.style.border =
          "1px solid #bbf7d0";
        card.style.borderRadius = "14px";
        card.style.background = "#f0fdf4";

        var candidateTitle = el(
          "h3",
          candidate.name ||
            "Konkurrentprodukt"
        );

        candidateTitle.style.margin =
          "0 0 8px 0";

        card.appendChild(candidateTitle);

        var details = el(
          "div",
          (candidate.store ||
            "Ukjent butikk") +
            " \u00B7 " +
            formatPriceCheckMoney(candidate.price) +
            " \u00B7 Treff: " +
            String(
              candidate.matchConfidence || 0
            ) +
            "%"
        );

        details.style.fontWeight = "700";
        details.style.marginBottom = "10px";

        card.appendChild(details);

        addPriceCandidateShippingBox(
          card,
          productResult,
          candidate
        );

        if (
          candidate.matchWarnings &&
          candidate.matchWarnings.length
        ) {
          var warningText = el(
            "div",
            "Kontroll: " +
              candidate.matchWarnings.join(" \u00B7 ")
          );
          warningText.style.color = "#92400e";
          warningText.style.fontSize = "12px";
          warningText.style.marginBottom = "8px";
          card.appendChild(warningText);
        }

        if (candidate.quantity !== null &&
            candidate.quantity !== undefined) {
          var stockInfo = el(
            "div",
            "Konkurrentlager: " +
              String(candidate.quantity)
          );

          stockInfo.style.marginBottom = "10px";
          card.appendChild(stockInfo);
        }

        var candidateActions = el("div");
        candidateActions.style.display = "flex";
        candidateActions.style.gap = "8px";
        candidateActions.style.flexWrap = "wrap";

        if (candidate.url) {
          var openCandidate = el(
            "a",
            "\u00C5pne hos konkurrent"
          );

          openCandidate.href = candidate.url;
          openCandidate.target = "_blank";
          openCandidate.rel = "noopener";
          openCandidate.style.display =
            "inline-flex";
          openCandidate.style.padding =
            "8px 11px";
          openCandidate.style.borderRadius =
            "9px";
          openCandidate.style.border =
            "1px solid #86efac";
          openCandidate.style.background =
            "#ffffff";
          openCandidate.style.color =
            "#166534";
          openCandidate.style.fontWeight =
            "800";
          openCandidate.style.textDecoration =
            "none";

          candidateActions.appendChild(
            openCandidate
          );
        }

        var saveSuggestionButton =
          createPrimaryButton(
            "Lagre forslag"
          );

        saveSuggestionButton.style.padding =
          "8px 11px";

        saveSuggestionButton.onclick =
          function () {
            var competitor =
              (data.priceCompetitors || [])
                .find(function (row) {
                  var baseUrl =
                    String(
                      row.base_url || ""
                    ).toLowerCase();

                  var name =
                    String(
                      row.name || ""
                    ).toLowerCase();

                  var store =
                    String(
                      candidate.store || ""
                    ).toLowerCase();

                  return (
                    row.is_active !== false &&
                    (
                      baseUrl.includes(store) ||
                      store.includes(
                        baseUrl
                          .replace(/^https?:\/\//, "")
                          .replace(/^www\./, "")
                          .replace(/\/+$/, "")
                      ) ||
                      (
                        store === "krokholdgs.no" &&
                        name.includes("krokhol")
                      )
                    )
                  );
                });

            if (!competitor) {
              alert(
                "Fant ikke aktiv konkurrent i registeret for " +
                  String(
                    candidate.store ||
                    "denne butikken"
                  ) +
                  "."
              );
              return;
            }

            saveSuggestionButton.disabled = true;
            saveSuggestionButton.textContent =
              "Lagrer...";

            sb.rpc(
              "internal_save_price_check_suggestion",
              {
                p_product_id:
                  productResult.productId,
                p_competitor_id:
                  competitor.id,
                p_competitor_product_name:
                  candidate.name || null,
                p_competitor_product_url:
                  candidate.url,
                p_competitor_price_inc_vat:
                  candidate.price,
                p_competitor_shipping_inc_vat:
                  null,
                p_competitor_in_stock:
                  candidate.inStock,
                p_match_confidence:
                  candidate.matchConfidence,
                p_raw_data: {
                  source:
                    candidate.source || null,
                  source_label:
                    candidate.sourceLabel || null,
                  store:
                    candidate.store || null,
                  quantity:
                    candidate.quantity ?? null,
                  image:
                    candidate.image || null,
                  worker_version:
                    result.version || null,
                  checked_at:
                    result.generatedAt || null,
                  shipping_known: false,
                  match_warnings:
                    candidate.matchWarnings || [],
                  learning_applied:
                    candidate.learningApplied || []
                }
              }
            )
              .then(function (rpcResult) {
                if (rpcResult.error) {
                  throw rpcResult.error;
                }

                saveSuggestionButton.textContent =
                  "Forslag lagret";
                saveSuggestionButton.disabled = true;

                card.style.border =
                  "1px solid #86efac";
                card.style.background =
                  "#ecfdf5";
              })
              .catch(function (error) {
                saveSuggestionButton.disabled = false;
                saveSuggestionButton.textContent =
                  "Lagre forslag";

                alert(
                  "Kunne ikke lagre forslaget: " +
                    (
                      error.message ||
                      String(error)
                    )
                );
              });
          };

        candidateActions.appendChild(
          saveSuggestionButton
        );

        card.appendChild(
          candidateActions
        );

        workerResult.appendChild(card);
      });
    }

    checkProductButton.onclick = function () {
      var productId =
        productSelect.value;

      if (!productId) {
        alert(
          "Velg et produkt som skal prissjekkes."
        );
        return;
      }

      checkProductButton.disabled = true;
      checkProductButton.textContent =
        "Sjekker...";

      workerStatus.style.display = "block";
      workerStatus.textContent =
        "S\u00F8ker hos Krokhol, DiscInStock, DGshop, Frisbeebutikken og WeAreDiscGolf...";

      workerResult.style.display = "none";
      clear(workerResult);

      callPriceCheckWorkerResilient({
        mode: "single",
        product_id: productId
      })
        .then(function (result) {
          workerStatus.textContent =
            "Prissjekken er ferdig. " +
            String(
              result.totalSuggestions || 0
            ) +
            " sikkert treff funnet.";

          renderPriceCheckWorkerResult(
            result
          );
        })
        .catch(function (error) {
          workerStatus.textContent =
            "Feil: " +
            (
              error.message ||
              String(error)
            );
        })
        .finally(function () {
          checkProductButton.disabled = false;
          checkProductButton.textContent =
            "Sjekk valgt produkt";
        });
    };

