    function getSelectedProductIds() {
      return Object.keys(
        selectedProductIds
      ).filter(function (id) {
        return selectedProductIds[id] === true;
      });
    }

    function updateSelectedCount() {
      var count =
        getSelectedProductIds().length;

      selectedCount.textContent =
        String(count) + " valgt";

      if (count > 5) {
        selectedCount.style.background =
          "#fee2e2";
        selectedCount.style.color =
          "#991b1b";
      } else {
        selectedCount.style.background =
          "#f1f5f9";
        selectedCount.style.color =
          "#111827";
      }
    }

    function getFilteredBatchProducts() {
      var searchText =
        String(
          batchSearchInput.value || ""
        )
          .toLowerCase()
          .trim();

      return relevantProducts.filter(
        function (product) {
          if (!searchText) {
            return true;
          }

          var haystack = (
            String(product.name || "") +
            " " +
            String(product.brand || "") +
            " " +
            String(
              product.quickbutik_sku || ""
            )
          ).toLowerCase();

          return haystack.includes(
            searchText
          );
        }
      );
    }

    function renderBatchProductList() {
      clear(batchProductList);

      var filteredProducts =
        getFilteredBatchProducts();

      batchInfo.textContent =
        String(filteredProducts.length) +
        " produkter vises. Maks 5 kan sjekkes per kj\u00F8ring.";

      if (!filteredProducts.length) {
        batchProductList.appendChild(
          el(
            "div",
            "Ingen produkter matcher s\u00F8ket."
          )
        );
        return;
      }

      filteredProducts.forEach(
        function (product) {
          var row = el("label");

          row.style.display = "grid";
          row.style.gridTemplateColumns =
            "24px minmax(0, 1fr) auto";
          row.style.gap = "8px";
          row.style.alignItems = "center";
          row.style.padding = "9px";
          row.style.borderBottom =
            "1px solid #f1f5f9";
          row.style.cursor = "pointer";

          var checkbox = el("input");

          checkbox.type = "checkbox";
          checkbox.checked =
            selectedProductIds[product.id] ===
            true;
          checkbox.style.width = "18px";
          checkbox.style.height = "18px";

          checkbox.addEventListener(
            "change",
            function () {
              selectedProductIds[
                product.id
              ] = checkbox.checked;

              updateSelectedCount();
            }
          );

          var textWrap = el("div");

          var productName = el(
            "div",
            (
              product.brand
                ? product.brand + " \u2013 "
                : ""
            ) +
              product.name
          );

          productName.style.fontWeight =
            "700";

          var productMeta = el(
            "div",
            "SKU: " +
              String(
                product.quickbutik_sku ||
                "-"
              )
          );

          productMeta.style.fontSize =
            "11px";
          productMeta.style.color =
            "#64748b";

          textWrap.appendChild(
            productName
          );

          textWrap.appendChild(
            productMeta
          );

          var price = el(
            "div",
            formatPriceCheckMoney(
              product.sales_price_inc_vat
            )
          );

          price.style.fontWeight = "800";
          price.style.whiteSpace = "nowrap";

          row.appendChild(checkbox);
          row.appendChild(textWrap);
          row.appendChild(price);

          batchProductList.appendChild(
            row
          );
        }
      );
    }

    batchSearchInput.addEventListener(
      "input",
      renderBatchProductList
    );

    selectVisibleButton.onclick =
      function () {
        var filteredProducts =
          getFilteredBatchProducts();

        var currentIds =
          getSelectedProductIds();

        var remaining =
          Math.max(
            0,
            5 - currentIds.length
          );

        filteredProducts
          .filter(function (product) {
            return (
              selectedProductIds[
                product.id
              ] !== true
            );
          })
          .slice(0, remaining)
          .forEach(function (product) {
            selectedProductIds[
              product.id
            ] = true;
          });

        updateSelectedCount();
        renderBatchProductList();
      };

    clearSelectedButton.onclick =
      function () {
        selectedProductIds = {};

        updateSelectedCount();
        renderBatchProductList();
      };

    function findPriceCompetitor(
      candidate
    ) {
      return (
        data.priceCompetitors || []
      ).find(function (row) {
        var baseUrl =
          String(
            row.base_url || ""
          ).toLowerCase();

        var name =
          String(
            row.name || ""
          ).toLowerCase();

        var store =
          String(
            candidate.store || ""
          ).toLowerCase();

        var normalizedBase =
          baseUrl
            .replace(/^https?:\/\//, "")
            .replace(/^www\./, "")
            .replace(/\/+$/, "");

        return (
          row.is_active !== false &&
          (
            baseUrl.includes(store) ||
            store.includes(
              normalizedBase
            ) ||
            (
              store ===
                "krokholdgs.no" &&
              name.includes("krokhol")
            )
          )
        );
      });
    }

    function getPriceCheckProductCategory(
      productResult
    ) {
      var ownProduct =
        (data.products || []).find(
          function (product) {
            return (
              String(product.id) ===
              String(productResult.productId)
            );
          }
        );

      return ownProduct &&
        ownProduct.category
          ? String(ownProduct.category)
          : String(
              productResult.category ||
              "disc"
            );
    }

    function resolveGolfKongenShipping(
      productResult
    ) {
      var category =
        getPriceCheckProductCategory(
          productResult
        );

      var ownPrice =
        Number(
          productResult.golfkongenPrice
        );

      var normalizedCategory =
        String(category || "")
          .toLowerCase();

      var className =
        normalizedCategory === "kurv"
          ? "basket"
          : normalizedCategory === "tilbehor"
            ? "small"
            : normalizedCategory === "disc"
              ? "disc"
              : "all";

      var applicable =
        (ownShippingRules || [])
          .filter(function (rule) {
            return (
              rule.is_active !== false &&
              rule.is_verified === true &&
              (
                String(rule.shipping_class) ===
                  className ||
                String(rule.shipping_class) ===
                  "all"
              )
            );
          })
          .sort(function (a, b) {
            var aExact =
              String(a.shipping_class) ===
              className
                ? 0
                : 1;

            var bExact =
              String(b.shipping_class) ===
              className
                ? 0
                : 1;

            if (aExact !== bExact) {
              return aExact - bExact;
            }

            return (
              Number(a.priority || 100) -
              Number(b.priority || 100)
            );
          });

      if (
        !applicable.length ||
        !Number.isFinite(ownPrice)
      ) {
        return {
          known: false,
          shipping: null,
          total: null,
          ruleName: null,
          methodName: null
        };
      }

      var rule =
        applicable[0];

      var freeFrom =
        rule.free_shipping_threshold_inc_vat ===
          null ||
        rule.free_shipping_threshold_inc_vat ===
          undefined ||
        rule.free_shipping_threshold_inc_vat ===
          ""
          ? null
          : Number(
              rule
                .free_shipping_threshold_inc_vat
            );

      var fixed =
        rule.fixed_shipping_inc_vat === null ||
        rule.fixed_shipping_inc_vat === undefined ||
        rule.fixed_shipping_inc_vat === ""
          ? null
          : Number(
              rule.fixed_shipping_inc_vat
            );

      var shipping = null;

      if (
        Number.isFinite(freeFrom) &&
        ownPrice >= freeFrom
      ) {
        shipping = 0;
      } else if (
        Number.isFinite(fixed)
      ) {
        shipping = fixed;
      }

      if (shipping === null) {
        return {
          known: false,
          shipping: null,
          total: null,
          ruleName:
            rule.rule_name || null,
          methodName:
            rule.method_name || null
        };
      }

      return {
        known: true,
        shipping: shipping,
        total:
          ownPrice + shipping,
        ruleName:
          rule.rule_name || null,
        methodName:
          rule.method_name || null
      };
    }

    function resolvePriceCandidateShipping(
      productResult,
      candidate
    ) {
      var competitor =
        findPriceCompetitor(candidate);

      if (!competitor) {
        return Promise.resolve({
          known: false,
          shipping: null,
          total: null,
          ruleName: null,
          sourceUrl: null
        });
      }

      var productCategory =
        getPriceCheckProductCategory(
          productResult
        );

      return sb.rpc(
        "internal_resolve_price_shipping",
        {
          p_competitor_id:
            competitor.id,
          p_product_category:
            productCategory,
          p_order_value_inc_vat:
            candidate.price
        }
      ).then(function (result) {
        if (result.error) {
          throw result.error;
        }

        var row =
          result.data &&
          result.data[0];

        if (
          !row ||
          row.shipping_is_known !== true ||
          row.shipping_inc_vat === null ||
          row.shipping_inc_vat === undefined
        ) {
          return {
            known: false,
            shipping: null,
            total: null,
            ruleName:
              row && row.shipping_rule_name
                ? row.shipping_rule_name
                : null,
            sourceUrl:
              row && row.shipping_source_url
                ? row.shipping_source_url
                : null
          };
        }

        var shipping =
          Number(row.shipping_inc_vat);

        var price =
          Number(candidate.price);

        return {
          known: true,
          shipping: shipping,
          total:
            Number.isFinite(price)
              ? price + shipping
              : null,
          ruleName:
            row.shipping_rule_name || null,
          sourceUrl:
            row.shipping_source_url || null
        };
      });
    }

    function addPriceCandidateShippingBox(
      parent,
      productResult,
      candidate
    ) {
      var box = el(
        "div",
        "Frakt: beregner..."
      );

      box.style.marginBottom = "10px";
      box.style.padding = "9px 10px";
      box.style.border =
        "1px solid #d1fae5";
      box.style.borderRadius = "9px";
      box.style.background = "#ffffff";
      box.style.fontSize = "13px";
      box.style.lineHeight = "1.5";

      parent.appendChild(box);

      var ownShippingInfo =
        resolveGolfKongenShipping(
          productResult
        );

      resolvePriceCandidateShipping(
        productResult,
        candidate
      )
        .then(function (shippingInfo) {
          clear(box);

          var competitorPrice =
            Number(candidate.price);

          var ownPrice =
            Number(
              productResult.golfkongenPrice
            );

          var productDifference =
            Number.isFinite(ownPrice) &&
            Number.isFinite(competitorPrice)
              ? ownPrice - competitorPrice
              : null;

          var ownPriceLine = el(
            "div",
            "GolfKongen vare: " +
              formatPriceCheckMoney(
                ownPrice
              )
          );

          ownPriceLine.style.fontWeight =
            "700";

          box.appendChild(
            ownPriceLine
          );

          box.appendChild(
            el(
              "div",
              ownShippingInfo.known
                ? (
                    "GolfKongen-frakt: " +
                    formatPriceCheckMoney(
                      ownShippingInfo.shipping
                    ) +
                    (
                      ownShippingInfo.methodName
                        ? (
                            " (" +
                            ownShippingInfo.methodName +
                            ")"
                          )
                        : ""
                    )
                  )
                : "GolfKongen-frakt: Ikke verifisert for denne varetypen"
            )
          );

          if (
            ownShippingInfo.known &&
            ownShippingInfo.total !== null
          ) {
            box.appendChild(
              el(
                "div",
                "GolfKongen levert: " +
                  formatPriceCheckMoney(
                    ownShippingInfo.total
                  )
              )
            );
          }

          var divider =
            el("div");

          divider.style.height = "1px";
          divider.style.background =
            "#e5e7eb";
          divider.style.margin =
            "6px 0";

          box.appendChild(divider);

          var competitorPriceLine =
            el(
              "div",
              "Konkurrent vare: " +
                formatPriceCheckMoney(
                  candidate.price
                )
            );

          competitorPriceLine.style.fontWeight =
            "700";

          box.appendChild(
            competitorPriceLine
          );

          box.appendChild(
            el(
              "div",
              shippingInfo.known
                ? (
                    "Konkurrentfrakt: " +
                    formatPriceCheckMoney(
                      shippingInfo.shipping
                    )
                  )
                : "Konkurrentfrakt: Ikke verifisert"
            )
          );

          if (
            shippingInfo.known &&
            shippingInfo.total !== null
          ) {
            box.appendChild(
              el(
                "div",
                "Konkurrent levert: " +
                  formatPriceCheckMoney(
                    shippingInfo.total
                  )
              )
            );
          }

          if (
            productDifference !== null
          ) {
            var productLine =
              el(
                "div",
                Math.abs(
                  productDifference
                ) < 0.005
                  ? "Vare mot vare: samme pris"
                  : productDifference < 0
                    ? (
                        "Vare mot vare: GolfKongen er " +
                        formatPriceCheckMoney(
                          Math.abs(
                            productDifference
                          )
                        ) +
                        " billigere"
                      )
                    : (
                        "Vare mot vare: GolfKongen er " +
                        formatPriceCheckMoney(
                          productDifference
                        ) +
                        " dyrere"
                      )
              );

            productLine.style.color =
              "#475569";

            box.appendChild(
              productLine
            );
          }

          if (
            ownShippingInfo.known &&
            ownShippingInfo.total !== null &&
            shippingInfo.known &&
            shippingInfo.total !== null
          ) {
            var deliveredDifference =
              ownShippingInfo.total -
              shippingInfo.total;

            var deliveredText =
              Math.abs(
                deliveredDifference
              ) < 0.005
                ? "Levert mot levert: samme pris"
                : deliveredDifference < 0
                  ? (
                      "Levert mot levert: GolfKongen er " +
                      formatPriceCheckMoney(
                        Math.abs(
                          deliveredDifference
                        )
                      ) +
                      " billigere"
                    )
                  : (
                      "Levert mot levert: GolfKongen er " +
                      formatPriceCheckMoney(
                        deliveredDifference
                      ) +
                      " dyrere"
                    );

            var deliveredLine =
              el(
                "div",
                deliveredText
              );

            deliveredLine.style.fontWeight =
              "700";

            deliveredLine.style.marginTop =
              "4px";

            box.appendChild(
              deliveredLine
            );
          }

          if (
            ownShippingInfo.ruleName
          ) {
            var ownRuleLine =
              el(
                "div",
                "GolfKongen-regel: " +
                  ownShippingInfo.ruleName
              );

            ownRuleLine.style.color =
              "#64748b";
            ownRuleLine.style.fontSize =
              "12px";

            box.appendChild(
              ownRuleLine
            );
          }

          if (
            shippingInfo.ruleName
          ) {
            var ruleLine =
              el(
                "div",
                "Konkurrentregel: " +
                  shippingInfo.ruleName
              );

            ruleLine.style.color =
              "#64748b";
            ruleLine.style.fontSize =
              "12px";

            box.appendChild(
              ruleLine
            );
          }
        })
        .catch(function (error) {
          box.textContent =
            "Frakt: Kunne ikke beregnes (" +
            (
              error.message ||
              String(error)
            ) +
            ")";

          box.style.color =
            "#92400e";
        });
    }

    function saveBatchSuggestion(
      productResult,
      candidate,
      workerResult,
      button,
      card
    ) {
      var competitor =
        findPriceCompetitor(candidate);

      if (!competitor) {
        alert(
          "Fant ikke aktiv konkurrent for " +
            String(
              candidate.store ||
              "denne butikken"
            )
        );
        return;
      }

      button.disabled = true;
      button.textContent = "Lagrer...";

      sb.rpc(
        "internal_save_price_check_suggestion",
        {
          p_product_id:
            productResult.productId,
          p_competitor_id:
            competitor.id,
          p_competitor_product_name:
            candidate.name || null,
          p_competitor_product_url:
            candidate.url,
          p_competitor_price_inc_vat:
            candidate.price,
          p_competitor_shipping_inc_vat:
            null,
          p_competitor_in_stock:
            candidate.inStock,
          p_match_confidence:
            candidate.matchConfidence,
          p_raw_data: {
            source:
              candidate.source || null,
            source_label:
              candidate.sourceLabel || null,
            store:
              candidate.store || null,
            quantity:
              candidate.quantity ?? null,
            image:
              candidate.image || null,
            worker_version:
              workerResult.version || null,
            checked_at:
              workerResult.generatedAt || null,
            shipping_known: false,
            match_warnings:
              candidate.matchWarnings || [],
            learning_applied:
              candidate.learningApplied || []
          }
        }
      )
        .then(function (rpcResult) {
          if (rpcResult.error) {
            throw rpcResult.error;
          }

          button.textContent =
            "Forslag lagret";
          button.disabled = true;

          card.style.background =
            "#ecfdf5";
          card.style.border =
            "1px solid #86efac";
        })
        .catch(function (error) {
          button.disabled = false;
          button.textContent =
            "Lagre forslag";

          alert(
            "Kunne ikke lagre forslaget: " +
              (
                error.message ||
                String(error)
              )
          );
        });
    }

    function renderBatchResults(result) {
      clear(batchResults);

      batchResults.style.display =
        "block";

      var productResults =
        result.productResults || [];

      if (!productResults.length) {
        batchResults.appendChild(
          el(
            "div",
            "Ingen produktresultater ble returnert."
          )
        );
        return;
      }

      productResults.forEach(
        function (productResult) {
          var productCard = el("div");

          productCard.style.padding =
            "14px";
          productCard.style.marginBottom =
            "14px";
          productCard.style.border =
            "1px solid #d1d5db";
          productCard.style.borderRadius =
            "14px";
          productCard.style.background =
            "#f8fafc";

          var title = el(
            "h3",
            productResult.productName ||
              "Ukjent produkt"
          );

          title.style.margin =
            "0 0 5px 0";

          productCard.appendChild(title);

          var ownPrice = el(
            "div",
            "GolfKongen: " +
              formatPriceCheckMoney(
                productResult.golfkongenPrice
              )
          );

          ownPrice.style.fontWeight =
            "700";
          ownPrice.style.marginBottom =
            "10px";

          productCard.appendChild(
            ownPrice
          );

          if (productResult.error) {
            var errorText = el(
              "div",
              "Feil: " +
                productResult.error
            );

            errorText.style.color =
              "#991b1b";

            productCard.appendChild(
              errorText
            );

            batchResults.appendChild(
              productCard
            );

            return;
          }

          var candidates =
            productResult.candidates || [];

          if (!candidates.length) {
            var noResult = el(
              "div",
              "Ingen sikre konkurrenttreff."
            );

            noResult.className = "sk-note";

            productCard.appendChild(
              noResult
            );

            batchResults.appendChild(
              productCard
            );

            return;
          }

          candidates.forEach(
            function (candidate) {
              var candidateCard =
                el("div");

              candidateCard.style.padding =
                "12px";
              candidateCard.style.marginTop =
                "10px";
              candidateCard.style.border =
                "1px solid #bbf7d0";
              candidateCard.style.borderRadius =
                "12px";
              candidateCard.style.background =
                "#f0fdf4";

              var candidateTitle = el(
                "div",
                candidate.name ||
                  "Konkurrentprodukt"
              );

              candidateTitle.style.fontWeight =
                "800";

              candidateCard.appendChild(
                candidateTitle
              );

              var candidateMeta = el(
                "div",
                String(
                  candidate.store ||
                  "Ukjent butikk"
                ) +
                  " \u00B7 " +
                  formatPriceCheckMoney(
                    candidate.price
                  ) +
                  " \u00B7 Treff: " +
                  String(
                    candidate.matchConfidence ||
                    0
                  ) +
                  "%"
              );

              candidateMeta.style.margin =
                "5px 0 10px 0";

              candidateCard.appendChild(
                candidateMeta
              );

              addPriceCandidateShippingBox(
                candidateCard,
                productResult,
                candidate
              );

              if (
                candidate.matchWarnings &&
                candidate.matchWarnings.length
              ) {
                var warningText = el(
                  "div",
                  "Kontroll: " +
                    candidate.matchWarnings.join(" \u00B7 ")
                );
                warningText.style.color = "#92400e";
                warningText.style.fontSize = "12px";
                warningText.style.marginBottom = "8px";
                candidateCard.appendChild(warningText);
              }

              var actions = el("div");

              actions.style.display =
                "flex";
              actions.style.gap = "8px";
              actions.style.flexWrap =
                "wrap";

              if (candidate.url) {
                var openLink = el(
                  "a",
                  "\u00C5pne konkurrentprodukt"
                );

                openLink.href =
                  candidate.url;
                openLink.target =
                  "_blank";
                openLink.rel =
                  "noopener";
                openLink.style.padding =
                  "8px 10px";
                openLink.style.border =
                  "1px solid #86efac";
                openLink.style.borderRadius =
                  "9px";
                openLink.style.background =
                  "#ffffff";
                openLink.style.color =
                  "#166534";
                openLink.style.fontWeight =
                  "700";
                openLink.style.textDecoration =
                  "none";

                actions.appendChild(
                  openLink
                );
              }

              var saveButton =
                createPrimaryButton(
                  "Lagre forslag"
                );

              saveButton.onclick =
                function () {
                  saveBatchSuggestion(
                    productResult,
                    candidate,
                    result,
                    saveButton,
                    candidateCard
                  );
                };

              actions.appendChild(
                saveButton
              );

              candidateCard.appendChild(
                actions
              );

              productCard.appendChild(
                candidateCard
              );
            }
          );

          batchResults.appendChild(
            productCard
          );
        }
      );
    }

