    function suggestionNumberOrNull(
      value
    ) {
      if (
        value === null ||
        value === undefined ||
        value === ""
      ) {
        return null;
      }

      var number = Number(value);

      if (!Number.isFinite(number)) {
        return null;
      }

      return number;
    }

    function priceSuggestionStatusText(
      status
    ) {
      if (status === "confirmed") {
        return "Godkjent";
      }

      if (status === "rejected") {
        return "Avvist";
      }

      return "Forslag";
    }

    function getReviewReason(
      reasonCode
    ) {
      var found = null;

      reviewReasons.forEach(
        function (reason) {
          if (reason.code === reasonCode) {
            found = reason;
          }
        }
      );

      return found;
    }

    function suggestionConfidenceMatches(
      suggestion
    ) {
      var selected =
        suggestionConfidenceFilter.value;

      if (selected === "all") {
        return true;
      }

      var confidence = Number(
        suggestion.match_confidence || 0
      );

      if (selected === "100") {
        return confidence === 100;
      }

      if (selected === "95-99") {
        return (
          confidence >= 95 &&
          confidence < 100
        );
      }

      if (selected === "90-94") {
        return (
          confidence >= 90 &&
          confidence < 95
        );
      }

      if (selected === "80-89") {
        return (
          confidence >= 80 &&
          confidence < 90
        );
      }

      if (selected === "70-79") {
        return (
          confidence >= 70 &&
          confidence < 80
        );
      }

      if (selected === "under-70") {
        return confidence < 70;
      }

      return true;
    }

    function suggestionPriceMatches(
      suggestion
    ) {
      var selected =
        suggestionPriceFilter.value;

      if (selected === "all") {
        return true;
      }

      var difference =
        suggestionNumberOrNull(
          suggestion
            .price_difference_inc_vat
        );

      if (selected === "missing") {
        return difference === null;
      }

      if (difference === null) {
        return false;
      }

      if (
        selected ===
        "golfkongen-expensive"
      ) {
        return difference > 0;
      }

      if (selected === "same") {
        return difference === 0;
      }

      if (
        selected ===
        "golfkongen-cheaper"
      ) {
        return difference < 0;
      }

      return true;
    }

    function compareSuggestionNumbers(
      firstValue,
      secondValue,
      descending
    ) {
      var first =
        suggestionNumberOrNull(
          firstValue
        );

      var second =
        suggestionNumberOrNull(
          secondValue
        );

      if (
        first === null &&
        second === null
      ) {
        return 0;
      }

      if (first === null) {
        return 1;
      }

      if (second === null) {
        return -1;
      }

      return descending
        ? second - first
        : first - second;
    }

    function sortPriceSuggestions(
      suggestions
    ) {
      var selected =
        suggestionSort.value;

      suggestions.sort(
        function (a, b) {
          if (
            selected ===
            "difference-desc"
          ) {
            return compareSuggestionNumbers(
              a.price_difference_inc_vat,
              b.price_difference_inc_vat,
              true
            );
          }

          if (
            selected ===
            "absolute-desc"
          ) {
            var firstDifference =
              suggestionNumberOrNull(
                a.price_difference_inc_vat
              );

            var secondDifference =
              suggestionNumberOrNull(
                b.price_difference_inc_vat
              );

            return compareSuggestionNumbers(
              firstDifference === null
                ? null
                : Math.abs(firstDifference),
              secondDifference === null
                ? null
                : Math.abs(secondDifference),
              true
            );
          }

          if (
            selected ===
            "confidence-desc"
          ) {
            return compareSuggestionNumbers(
              a.match_confidence,
              b.match_confidence,
              true
            );
          }

          if (
            selected ===
            "confidence-asc"
          ) {
            return compareSuggestionNumbers(
              a.match_confidence,
              b.match_confidence,
              false
            );
          }

          if (
            selected ===
            "competitor-price-asc"
          ) {
            return compareSuggestionNumbers(
              a.competitor_price_inc_vat,
              b.competitor_price_inc_vat,
              false
            );
          }

          if (
            selected ===
            "product-asc"
          ) {
            return String(
              a.product_name || ""
            ).localeCompare(
              String(
                b.product_name || ""
              ),
              "nb-NO"
            );
          }

          var firstDate =
            a.checked_at
              ? new Date(
                  a.checked_at
                ).getTime()
              : 0;

          var secondDate =
            b.checked_at
              ? new Date(
                  b.checked_at
                ).getTime()
              : 0;

          return secondDate - firstDate;
        }
      );

      return suggestions;
    }

    function updatePriceSuggestionReview(
      suggestion,
      status,
      button,
      reasonCode,
      comment,
      useForLearning,
      successCallback
    ) {
      var originalText =
        button.textContent;

      button.disabled = true;

      if (status === "confirmed") {
        button.textContent =
          "Godkjenner...";
      } else if (
        status === "rejected"
      ) {
        button.textContent =
          "Avviser...";
      } else {
        button.textContent =
          "Oppdaterer...";
      }

      sb.rpc(
        "internal_review_price_match",
        {
          p_match_id:
            suggestion.price_match_id,
          p_match_status: status,
          p_reason_code:
            reasonCode || null,
          p_comment:
            comment || null,
          p_use_for_learning:
            Boolean(useForLearning)
        }
      )
        .then(function (result) {
          if (result.error) {
            throw result.error;
          }

          suggestion.match_status =
            status;

          if (status === "rejected") {
            var reason =
              getReviewReason(
                reasonCode
              );

            suggestion.review_reason_code =
              reasonCode;

            suggestion.review_reason_label =
              reason
                ? reason.label
                : reasonCode;

            suggestion.review_learning_dimension =
              reason
                ? reason.learning_dimension
                : null;

            suggestion.review_comment =
              comment || null;

            suggestion.review_use_for_learning =
              Boolean(useForLearning);

            suggestion.reviewed_at =
              new Date().toISOString();
          } else {
            suggestion.review_reason_code =
              null;

            suggestion.review_reason_label =
              null;

            suggestion.review_learning_dimension =
              null;

            suggestion.review_comment =
              null;

            suggestion.review_use_for_learning =
              false;
          }

          if (successCallback) {
            successCallback();
          }

          renderPriceSuggestions();
        })
        .catch(function (error) {
          button.disabled = false;
          button.textContent =
            originalText;

          alert(
            "Kunne ikke oppdatere forslaget: " +
              (
                error.message ||
                String(error)
              )
          );
        });
    }

