  function renderValue() {
    var toolbar = el("div");
    toolbar.className =
      "sk-analysis-toolbar";

    var groupSelect =
      makeGroupSelect();

    var vatModeSelect =
      el("select");

    addOption(
      vatModeSelect,
      "ex",
      "Verdier eks. MVA"
    );

    addOption(
      vatModeSelect,
      "inc",
      "Verdier inkl. MVA"
    );

    vatModeSelect.value =
      localStorage.getItem(
        "sk_inventory_value_vat_mode_v1"
      ) ||
      "ex";

    toolbar.appendChild(
      groupSelect
    );

    toolbar.appendChild(
      vatModeSelect
    );

    content.appendChild(toolbar);

    var summaryHost = el("div");
    var noteHost = el("div");
    var tableHost = el("div");

    content.appendChild(
      summaryHost
    );
    content.appendChild(
      noteHost
    );
    content.appendChild(
      tableHost
    );

    function rerender() {
      clear(summaryHost);
      clear(noteHost);
      clear(tableHost);

      localStorage.setItem(
        "sk_inventory_value_vat_mode_v1",
        vatModeSelect.value
      );

      var filtered =
        rows.filter(
          function (row) {
            return (
              groupSelect.value ===
                "all" ||
              skInventoryBucket(row) ===
                groupSelect.value
            );
          }
        );

      var isEx =
        vatModeSelect.value ===
        "ex";

      var purchaseKey =
        isEx
          ? "stock_purchase_value_ex_vat"
          : "stock_purchase_value_inc_vat";

      var retailKey =
        isEx
          ? "stock_retail_value_ex_vat"
          : "stock_retail_value_inc_vat";

      var purchaseValue =
        filtered.reduce(
          function (sum, row) {
            return (
              sum +
              Number(
                row[
                  purchaseKey
                ] ||
                0
              )
            );
          },
          0
        );

      var retailValue =
        filtered.reduce(
          function (sum, row) {
            return (
              sum +
              Number(
                row[
                  retailKey
                ] ||
                0
              )
            );
          },
          0
        );

      var units =
        filtered.reduce(
          function (sum, row) {
            return (
              sum +
              Number(
                row.stock_quantity ||
                0
              )
            );
          },
          0
        );

      var difference =
        retailValue -
        purchaseValue;

      addProStatGrid(
        summaryHost,
        [
          {
            label:
              isEx
                ? "Innkj\u00F8psverdi eks. MVA"
                : "Innkj\u00F8psverdi inkl. MVA",
            value:
              skFormatMoney(
                purchaseValue
              ),
            tone: "ok"
          },
          {
            label:
              isEx
                ? "Utsalgsverdi eks. MVA"
                : "Utsalgsverdi inkl. MVA",
            value:
              skFormatMoney(
                retailValue
              ),
            tone: "ok"
          },
          {
            label:
              isEx
                ? "Potensiell bruttofortjeneste eks. MVA"
                : "Prisforskjell inkl. MVA",
            value:
              skFormatMoney(
                difference
              ),
            tone:
              difference < 0
                ? "danger"
                : "ok"
          },
          {
            label:
              "Enheter p\u00E5 lager",
            value:
              String(
                Math.round(units)
              ),
            tone: "ok"
          }
        ]
      );

      var valueNote =
        el(
          "div",
          isEx
            ? (
                "Potensiell bruttofortjeneste er utsalgsverdi minus innkj\u00F8psverdi eks. MVA. " +
                "Tallet er f\u00F8r frakt, betalingskostnader, rabatter og andre kostnader."
              )
            : (
                "Inkl. MVA viser butikkverdien av lageret. Prisforskjellen inkl. MVA er ikke det samme som fortjeneste. " +
                "Velg \u00ABVerdier eks. MVA\u00BB for \u00F8konomisk bruttofortjeneste f\u00F8r frakt, betalingskostnader og andre kostnader."
              )
        );

      valueNote.className =
        "sk-note";
      valueNote.style.marginBottom =
        "10px";

      noteHost.appendChild(
        valueNote
      );

      var sorted =
        filtered.slice().sort(
          function (a, b) {
            return (
              Number(
                b[
                  purchaseKey
                ] ||
                0
              ) -
              Number(
                a[
                  purchaseKey
                ] ||
                0
              )
            );
          }
        );

      skCreateAnalysisTable(
        tableHost,
        [
          {
            label: "Produkt",
            value:
              function (row) {
                return row.name;
              }
          },
          {
            label: "Gruppe",
            value:
              skInventoryBucket
          },
          {
            label: "Lager",
            key:
              "stock_quantity",
            align: "right"
          },
          {
            label:
              isEx
                ? "Innkj\u00F8psverdi eks. MVA"
                : "Innkj\u00F8psverdi inkl. MVA",
            value:
              function (row) {
                return row[
                  purchaseKey
                ];
              },
            format: "money",
            align: "right"
          },
          {
            label:
              isEx
                ? "Utsalgsverdi eks. MVA"
                : "Utsalgsverdi inkl. MVA",
            value:
              function (row) {
                return row[
                  retailKey
                ];
              },
            format: "money",
            align: "right"
          }
        ],
        sorted,
        "Ingen produkter i dette filteret."
      );
    }

    groupSelect.onchange =
      rerender;

    vatModeSelect.onchange =
      rerender;

    rerender();
  }


