function auditRecordLabel(row) {
  var data = row.new_data || row.old_data || {};

  return (
    data.product_name ||
    data.name ||
    data.title ||
    data.count_number ||
    data.email ||
    ""
  );
}


function auditPersonAction(row) {
  if (row.action === "login") {
    return "Logget inn og \u00E5pnet " + auditPageLabel((row.new_data || {}).page);
  }

  if (row.description && !/^Oppdatert rad i /i.test(row.description)) {
    return row.description;
  }

  var recordLabel = auditRecordLabel(row);
  var text = auditActionLabel(row.action) + " " + auditAreaLabel(row.table_name).toLowerCase();

  return recordLabel ? text + " \u00B7 " + recordLabel : text;
}


function auditChangeSummary(row) {
  if (row.action === "login") {
    return "Tilgang: " + auditDisplayValue((row.new_data || {}).role);
  }

  var before = row.old_data || {};
  var after = row.new_data || {};
  var ignored = {
    updated_at: true,
    last_synced_at: true,
    synced_at: true,
    last_seen_at: true
  };
  var keys = {};

  Object.keys(before).forEach(function (key) { keys[key] = true; });
  Object.keys(after).forEach(function (key) { keys[key] = true; });

  var changes = Object.keys(keys)
    .filter(function (key) {
      return !ignored[key] && auditDisplayValue(before[key]) !== auditDisplayValue(after[key]);
    })
    .slice(0, 5)
    .map(function (key) {
      return auditFieldLabel(key) + ": " + auditDisplayValue(before[key]) + " \u2192 " + auditDisplayValue(after[key]);
    });

  return changes.length ? changes.join("\n") : (row.description || "Ingen feltendringer registrert");
}


function renderAuditLog(
  parent,
  data
) {
  createPageHeader(
    parent,
    "Endringslogg",
    "Viser handlinger utf\u00F8rt av personer. Automatiske synkroniseringer er skjult.",
    "Audit"
  );

  var rows =
    (data.auditLog || []).filter(function (row) {
      return Boolean(row.changed_by);
    });

  var toolbar = el("div");
  toolbar.className =
    "sk-analysis-toolbar";

  var search =
    el("input");
  search.placeholder =
    "S\u00F8k i loggen";

  toolbar.appendChild(
    search
  );

  parent.appendChild(
    toolbar
  );

  var host = el("div");
  parent.appendChild(host);

  function renderRows() {
    clear(host);

    var needle =
      search.value
        .trim()
        .toLowerCase();

    var filtered =
      rows.filter(
        function (row) {
          if (!needle) {
            return true;
          }

          var text =
            (
              String(
                row.table_name ||
                ""
              ) +
              " " +
              String(
                row.description ||
                ""
              ) +
              " " +
              auditPersonAction(row) +
              " " +
              String(
                row
                  .changed_by_display ||
                ""
              ) +
              " " +
              JSON.stringify(
                row.new_data ||
                {}
              ) +
              " " +
              JSON.stringify(
                row.old_data ||
                {}
              )
            ).toLowerCase();

          return (
            text.indexOf(
              needle
            ) >= 0
          );
        }
      );

    skCreateAnalysisTable(
      host,
      [
        {
          label: "Tid",
          value:
            function (row) {
              return formatAdminDateTime(
                row.changed_at
              );
            }
        },
        {
          label: "Person",
          key:
            "changed_by_display"
        },
        {
          label: "Hva personen gjorde",
          value: function (row) {
            return auditPersonAction(row);
          }
        },
        {
          label: "Detaljer",
          render: function (td, row) {
            var summary = auditChangeSummary(row);
            var firstLine = summary.split("\n")[0];
            var short = el("div", firstLine);
            short.style.maxWidth = "360px";
            short.style.whiteSpace = "normal";
            td.appendChild(short);

            if (summary.indexOf("\n") >= 0 || row.old_data || row.new_data) {
              var details = el("details");
              details.style.marginTop = "5px";
              var detailsLabel = el("summary", "Se f\u00F8r/etter");
              detailsLabel.style.cursor = "pointer";
              detailsLabel.style.fontWeight = "700";
              detailsLabel.style.color = "#334155";
              var pre = el("pre", summary);
              pre.style.whiteSpace = "pre-wrap";
              pre.style.maxWidth = "520px";
              pre.style.margin = "6px 0 0";
              pre.style.fontSize = "11px";
              details.appendChild(detailsLabel);
              details.appendChild(pre);
              td.appendChild(details);
            }
          }
        }
      ],
      filtered.slice(0, 500),
      "Ingen endringer."
    );
  }

  search.oninput =
    renderRows;

  renderRows();
}


