  crawlNote.rows = 2;
  crawlNote.placeholder =
    "F.eks. vilk\u00E5r gjennomg\u00E5tt 04.08.2026 \u2013 ingen eksplisitt blokkering av offentlig produktm\u00E5ling funnet.";

